def 층부가(층):
    """10층부터 모든 적 공격에 붙는 부가효과 (확률, 뽑을 수 있는 효과들)"""
    if 층 < 10:
        return 0.0, []
    후보 = ["약화", "둔화"]
    if 층 >= 20:
        후보.append("독")
    if 층 >= 35:
        후보.append("방어파괴")
    if 층 >= 50:
        후보.append("기절")
    return min(0.30, (층 - 9) * 0.01), 후보
