def 구역키(층):
    if 층 <= 30:
        return "감옥"
    if 층 <= 70:
        return "화산"
    if 층 <= 120:
        return "성채"
    if 층 <= 200:
        return "도시"
    if 층 <= 300:
        return "공허"
    return 구역_순환[((층 - 301) // 100) % len(구역_순환)]


def 구역시작층(층):
    if 층 > 300:
        return 301 + (층 - 301) // 100 * 100
    return {"감옥": 1, "화산": 31, "성채": 71, "도시": 121, "공허": 201}[구역키(층)]


def 구역이름(층):
    z = 구역[구역키(층)]
    return f"{z['이모지']} {'심층 ' if 층 > 300 else ''}{z['이름']}"


def 구역보스(층):
    """보스층(10의 배수)의 보스 이름. 구역 안에서 순서대로 나온다"""
    z = 구역[구역키(층)]
    return z["보스"][((층 - 구역시작층(층)) // 10) % len(z["보스"])]


