러시_시작 = 0.3             # 첫 보스 = 내 최고층 × 0.3 층의 보스
러시_증가 = 0.05            # 한 마리 잡을 때마다 최고층의 5%씩 높은 층 보스가 나온다


def 러시층(최고층, n):
    """보스 러시 n번째 보스의 세기(층, 10의 배수). 최고층이 낮아도 한 마리마다 10층씩은 오른다"""
    return max(10 * n, round(최고층 * (러시_시작 + 러시_증가 * (n - 1)) / 10) * 10)


def 일일구성(날=None):
    """그날의 (규칙, 층별 적 구성). 날짜가 씨앗이라 누구에게나 같다. 세기는 들어갈 때 각자 기준층에 맞춘다"""
    날 = 날 or datetime.now().date().isoformat()
    R = random.Random(f"일일던전:{날}")
    규칙 = R.choice(일일_규칙)
    후보 = 적종류 + 구역적
    보스이름 = [n for z in 구역.values() for n in z["보스"]]
    층들 = []
    for 단계 in range(1, 일일_층수 + 1):
        적 = [dict(이름=t["이름"], hp=t["hp"], atk=t["atk"], 종류=t["종류"], 특수=t["특수"],
                  패턴=list(t["패턴"]), 부가=list(t["부가"]), 보스=False)
             for t in R.choices(후보, k=2 + (단계 - 1) // 3)]            # 2·2·2·3·3·3·4·4·4·5 명
        if 단계 % 5 == 0:                                                # 5층 중간 보스, 10층 보스
            끝 = 단계 == 일일_층수
            적 = 적[:2]
            적.insert(0, dict(
                이름=f"👑 {R.choice(보스이름)}", hp=6.0 if 끝 else 4.0, atk=2.2 if 끝 else 1.8,
                종류=R.choice(["근접", "총", "화염", "폭발"]), 특수=None,
                패턴=R.sample(["광폭", "치유", "조준", "흡혈", "소환"], 2 if 끝 else 1),
                부가=[(R.choice(["약화", "둔화", "독", "방어파괴"]), 0.25)], 보스=True))
        층들.append(적)
    return 규칙, 층들


