def 스탠드_필요경험치(lv):
    return 30_000 * lv


def 스탠드_레벨배율(lv):
    """스탠드 능력 수치(피해·회복 등)에 곱한다. Lv.100 = 2배"""
    return 1 + lv / 100


def 스탠드능력칸(lv):
    return 1 + lv // 스탠드_능력간격


# 펫 능력 수치 (능력 레벨 lv 에 따라)
강아지_확률 = lambda lv: 0.15 + 0.0015 * lv
강아지_회복 = lambda lv: 0.12 + 0.001 * lv
고양이_확률 = 0.15
고양이_피해 = lambda lv: 45 + 2 * lv
고양이_출혈 = lambda lv: round(3 + 0.05 * lv)
돼지_회복 = lambda lv: 60 + lv
호그_속도 = 0.5            # 주인의 속도(회피)를 50% 올린다
호그_공격 = 0.2            # 주인의 공격력을 20% 올린다
호그_확률 = 0.10
호그_피해 = lambda lv: 60 + 2 * lv
펫_최대레벨 = 99
펫_공격확률 = 0.30


def 펫공격력(이름, 능력lv):
    return 펫[이름]["공격"] + 능력lv


def 펫최대체력(이름, 체력lv):
    d = 펫[이름]
    return d["hp"] + d["hp당"] * 체력lv


def 펫능력문구(이름, 능력lv):
    return _펫능력문구(이름, 능력lv) + f" · 공격 {펫공격력(이름, 능력lv)} ({int(펫_공격확률 * 100)}%)"


def _펫능력문구(이름, 능력lv):
    if 이름 == "강아지":
        return f"매 턴 {강아지_확률(능력lv) * 100:.1f}% 확률로 주인 체력 {강아지_회복(능력lv) * 100:.1f}% 회복"
    if 이름 == "고양이":
        return f"매 턴 {고양이_확률 * 100:.0f}% 확률로 할퀴기 {고양이_피해(능력lv)} 피해 + 출혈 {고양이_출혈(능력lv)}턴"
    if 이름 == "라이딩 호그":
        return f"속도 +{호그_속도 * 100:.0f}% · 공격력 +{호그_공격 * 100:.0f}% · 매 턴 {호그_확률 * 100:.0f}% 확률로 몸통 박치기 {호그_피해(능력lv)} + 기절"
    if 이름 == "스탠드":
        return f"능력 배율 ×{스탠드_레벨배율(능력lv):.2f} · 피해를 대신 받지 않고 쓰러지지 않는다"
    return f"피해 {펫['돼지']['분담'] * 100:.0f}% 대신 받기 · 매 턴 10% 확률로 자기 체력 {돼지_회복(능력lv)} 회복"


def 간식드롭(층):
    return 1 + 0.05 * (층 - 1)


