def _악세효과하나(이름):
    e = {"공격배율": 1.0, "피해배율": 1.0, "체력": 0, "부활": 0, "부활체력": 1.0, "면역": False, "산데": False,
         "펫부활": False, "위기회복": False,
         "회복확률": 0.0, "회복량": 0, "꼬리": False, "랜덤대상": False, "숨김": False, "에러조우": False,
         "회피": 0.0, "턴회복": 0.0}
    if 이름 == "천사의 날개":
        e.update(피해배율=0.7, 회복확률=0.2, 회복량=15, 체력=150, 부활=1, 부활체력=0.5)
    elif 이름 == "악마의 꼬리":
        e.update(공격배율=1.3, 랜덤대상=True, 꼬리=True, 체력=-50)
    elif 이름 == "개발자의 빛":
        e.update(공격배율=1.2, 피해배율=0.75, 회복확률=0.1, 회복량=10, 부활=1, 면역=True, 체력=150)
    elif 이름 == "부서지지 않는 다이아몬드":
        e.update(공격배율=1.15, 피해배율=0.8, 펫부활=True, 위기회복=True, 부활=1, 부활체력=1.0)
    elif 이름 == "산데비스탄":
        e.update(산데=True)
    elif 이름 == "강인한 심장":
        e.update(공격배율=1.35, 피해배율=0.8, 체력=50, 부활=1, 부활체력=0.25)
    elif 이름 == "3rR0r의 빛나는 스커프":
        e.update(공격배율=1 + random.uniform(0.8, 1.2), 피해배율=0.65, 체력=60, 부활=3, 에러조우=True)
    elif 이름 == "정복자의 훈장":
        e.update(공격배율=1.25, 피해배율=0.85, 체력=100)
    elif 이름 == "베이컨 오브 꾸이익":
        e.update(공격배율=0.5, 회피=-0.15, 피해배율=0.8, 체력=200, 턴회복=0.03, 부활=1, 부활체력=1.0)
    return e


def 악세효과(이름들):
    """전투 시작 때 한 번 정한다 (빛나는 스커프 공격력은 매번 무작위).
    이름 하나, 목록, None 다 받는다. 배율은 곱하고, 체력은 더하고, 능력은 하나라도 있으면 켜진다.
    회복은 악세마다 따로 굴리고, 부활은 체력을 많이 남기는 것부터 쓴다."""
    if isinstance(이름들, str):
        이름들 = [이름들]
    이름들 = [n for n in (이름들 or []) if n in 악세서리]
    e = _악세효과하나(None)
    e["회복"] = []                    # [(확률, 양, 이모지)]
    e["부활목록"] = []                 # [(부활체력, 이모지)] 좋은 것부터
    for n in 이름들:
        x = _악세효과하나(n)
        e["공격배율"] *= x["공격배율"]
        e["피해배율"] *= x["피해배율"]
        e["체력"] += x["체력"]
        e["회피"] += x["회피"]
        e["턴회복"] += x["턴회복"]
        for k in ("면역", "산데", "펫부활", "위기회복", "꼬리", "랜덤대상", "숨김", "에러조우"):
            e[k] = e[k] or x[k]
        if x["회복확률"]:
            e["회복"].append((x["회복확률"], x["회복량"], 악세서리[n]["이모지"]))
        e["부활목록"] += [(x["부활체력"], 악세서리[n]["이모지"])] * x["부활"]
    e["부활목록"].sort(key=lambda t: -t[0])
    e["부활"] = len(e["부활목록"])
    return e


