def 층수치(층):
    """(적 기준 체력, 적 기준 공격력, 적 1명당 골드, 적 1명당 경험치)"""
    초반 = min(1.0, 0.6 + 0.04 * (층 - 1))      # 1층은 60% 세기로 시작해 11층에서 100%
    ha, hp_ = 적_체력성장
    aa, ap = 적_공격성장
    return (
        25 * (1 + ha * (층 - 1)) ** hp_ * 초반,
        5 * (1 + aa * (층 - 1)) ** ap * 초반,
        max(1, round(1.4 * (1 + 0.08 * (층 - 1)) ** 1.3)),      # 골드
        max(1, round(6 * (1 + 0.08 * (층 - 1)) ** 1.4)),        # 경험치
    )


def 필요경험치(레벨):
    return 30 * 레벨


