BASE_DIR = os.path.dirname(os.path.abspath(__file__))
conn = sqlite3.connect(os.path.join(BASE_DIR, "bot.db"), check_same_thread=False, timeout=15)
conn.execute("PRAGMA journal_mode=WAL")
cursor = conn.cursor()

cursor.execute("""
    CREATE TABLE IF NOT EXISTS rpg_characters (
        user_id TEXT PRIMARY KEY, name TEXT,
        level INTEGER DEFAULT 1, exp INTEGER DEFAULT 0,
        stat_str INTEGER DEFAULT 0, stat_hp INTEGER DEFAULT 0,
        stat_spd INTEGER DEFAULT 0, stat_int INTEGER DEFAULT 0,
        skill_points INTEGER DEFAULT 0, created_at TEXT
    )
""")
cursor.execute("CREATE TABLE IF NOT EXISTS rpg_history (user_id TEXT PRIMARY KEY, first_created_at TEXT)")
cursor.execute("CREATE TABLE IF NOT EXISTS rpg_meta (key TEXT PRIMARY KEY, value TEXT)")
cursor.execute("""
    CREATE TABLE IF NOT EXISTS rpg_inventory (
        user_id TEXT, kind TEXT, name TEXT, qty INTEGER DEFAULT 0, enhance INTEGER DEFAULT 0,
        PRIMARY KEY (user_id, kind, name)
    )
""")
cursor.execute("CREATE TABLE IF NOT EXISTS rpg_counters (user_id TEXT, key TEXT, value INTEGER DEFAULT 0, PRIMARY KEY (user_id, key))")
cursor.execute("CREATE TABLE IF NOT EXISTS rpg_admins (user_id TEXT PRIMARY KEY)")
cursor.execute("CREATE TABLE IF NOT EXISTS rpg_accessories (user_id TEXT, name TEXT, at TEXT, PRIMARY KEY (user_id, name))")
cursor.execute("""
    CREATE TABLE IF NOT EXISTS rpg_pets (
        user_id TEXT, pet TEXT, hp_lv INTEGER DEFAULT 0, skill_lv INTEGER DEFAULT 0,
        PRIMARY KEY (user_id, pet)
    )
""")
try:
    cursor.execute("ALTER TABLE rpg_pets ADD COLUMN nickname TEXT DEFAULT NULL")
except sqlite3.OperationalError:
    pass
cursor.execute("CREATE TABLE IF NOT EXISTS rpg_achievements (user_id TEXT, name TEXT, at TEXT, PRIMARY KEY (user_id, name))")
# 스탠드: 1인 1개. abilities = 능력 JSON 목록 (스탠드능력검사 형식)
cursor.execute("CREATE TABLE IF NOT EXISTS rpg_stands (user_id TEXT PRIMARY KEY, name TEXT, level INTEGER DEFAULT 1, "
               "exp INTEGER DEFAULT 0, abilities TEXT DEFAULT '[]', created_at TEXT)")
# 스탠드 요청: kind = 생성/능력, status = 대기/완료/거절. 관리자가 클로드 코드로 처리한다 (스탠드요청.py)
cursor.execute("CREATE TABLE IF NOT EXISTS rpg_stand_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, kind TEXT, "
               "stand_name TEXT, request TEXT, status TEXT DEFAULT '대기', note TEXT, created_at TEXT, done_at TEXT)")
# 레이드: 주(월요일 날짜)마다 보스 하나. hp·max_hp·damage 는 점수 단위 (REAL)
cursor.execute(
    "CREATE TABLE IF NOT EXISTS rpg_raids (week TEXT PRIMARY KEY, boss INTEGER, max_hp REAL, hp REAL, "
    "killed_by TEXT DEFAULT NULL, killed_at TEXT DEFAULT NULL, settled INTEGER DEFAULT 0)"
)
cursor.execute(
    "CREATE TABLE IF NOT EXISTS rpg_raid_damage (week TEXT, user_id TEXT, damage REAL DEFAULT 0, "
    "reward INTEGER DEFAULT NULL, PRIMARY KEY (week, user_id))"
)
cursor.execute("CREATE TABLE IF NOT EXISTS rpg_raid_tries (user_id TEXT, day TEXT, n INTEGER DEFAULT 0, PRIMARY KEY (user_id, day))")
# 특수 던전: 하루 도전 횟수 / 기간(일일 = 날짜, 로그라이크·보스 러시 = 그 주 월요일)마다 가장 좋은 기록 하나
cursor.execute("CREATE TABLE IF NOT EXISTS rpg_dungeon_tries (user_id TEXT, mode TEXT, day TEXT, n INTEGER DEFAULT 0, "
               "PRIMARY KEY (user_id, mode, day))")
cursor.execute("CREATE TABLE IF NOT EXISTS rpg_dungeon_records (mode TEXT, period TEXT, user_id TEXT, score INTEGER, at TEXT, "
               "PRIMARY KEY (mode, period, user_id))")

for 문 in [
    "ALTER TABLE rpg_characters ADD COLUMN gold INTEGER DEFAULT 0",
    "ALTER TABLE rpg_characters ADD COLUMN weapon TEXT DEFAULT '나무막대기'",
    "ALTER TABLE rpg_characters ADD COLUMN armor TEXT DEFAULT '가죽옷'",
    "ALTER TABLE rpg_characters ADD COLUMN best_floor INTEGER DEFAULT 0",
    "ALTER TABLE rpg_characters ADD COLUMN battle_lock TEXT DEFAULT NULL",
    "ALTER TABLE rpg_characters ADD COLUMN pet TEXT DEFAULT NULL",
    "ALTER TABLE rpg_characters ADD COLUMN snacks INTEGER DEFAULT 0",
    "ALTER TABLE rpg_characters ADD COLUMN pet_weapon TEXT DEFAULT NULL",
    "ALTER TABLE rpg_characters ADD COLUMN accessory TEXT DEFAULT NULL",
    "ALTER TABLE rpg_pets ADD COLUMN nickname TEXT DEFAULT NULL",
    "ALTER TABLE rpg_inventory ADD COLUMN prefix TEXT DEFAULT '[]'",
    "ALTER TABLE rpg_accessories ADD COLUMN equipped INTEGER DEFAULT 0",
]:
    try:
        cursor.execute(문)
    except sqlite3.OperationalError:
        pass

# 악세서리 착용 정보: rpg_characters.accessory(1개) → rpg_accessories.equipped(최대 3개)
cursor.execute(
    "UPDATE rpg_accessories SET equipped = 1 WHERE EXISTS (SELECT 1 FROM rpg_characters c "
    "WHERE c.user_id = rpg_accessories.user_id AND c.accessory = rpg_accessories.name)"
)
cursor.execute("UPDATE rpg_characters SET accessory = NULL WHERE accessory IS NOT NULL")
conn.commit()

# 이름이 바뀐 아이템: 샌드위치 → 샌드비치
cursor.execute(
    "UPDATE rpg_inventory SET qty = qty + COALESCE((SELECT qty FROM rpg_inventory o WHERE o.user_id = rpg_inventory.user_id "
    "AND o.kind = 'item' AND o.name = '샌드위치'), 0) WHERE kind = 'item' AND name = '샌드비치'"
)
cursor.execute(
    "UPDATE OR IGNORE rpg_inventory SET name = '샌드비치' WHERE kind = 'item' AND name = '샌드위치'"
)
cursor.execute("DELETE FROM rpg_inventory WHERE kind = 'item' AND name = '샌드위치'")

# 예전 버전(능력치 1 시작)을 0 시작으로 한 번만 보정
cursor.execute("SELECT 1 FROM rpg_meta WHERE key = 'base_zero'")
if cursor.fetchone() is None:
    cursor.execute(
        "UPDATE rpg_characters SET stat_str = MAX(0, stat_str - 1), stat_hp = MAX(0, stat_hp - 1), "
        "stat_spd = MAX(0, stat_spd - 1), stat_int = MAX(0, stat_int - 1)"
    )
    cursor.execute("INSERT INTO rpg_meta (key, value) VALUES ('base_zero', '1')")

# 일반 유저의 99강 노키아도 신의 노키아로 (예전에 관리자만 변신하던 것 보정)
for (_uid,) in cursor.execute(
    "SELECT user_id FROM rpg_inventory WHERE kind = 'weapon' AND name = '노키아 3310' AND enhance >= 99"
).fetchall():
    cursor.execute("DELETE FROM rpg_inventory WHERE user_id = ? AND kind = 'weapon' AND name = '노키아 3310'", (_uid,))
    cursor.execute(
        "INSERT OR REPLACE INTO rpg_inventory (user_id, kind, name, qty, enhance) VALUES (?, 'weapon', ?, 1, ?)",
        (_uid, 신의노키아, 99),
    )
    cursor.execute("UPDATE rpg_characters SET weapon = ? WHERE user_id = ? AND weapon = '노키아 3310'", (신의노키아, _uid))
    cursor.execute("UPDATE rpg_characters SET pet_weapon = ? WHERE user_id = ? AND pet_weapon = '노키아 3310'", (신의노키아, _uid))
conn.commit()


def _지금():
    return datetime.now().isoformat(timespec="seconds")


# ============================================================
# 관리자
# ============================================================

_관리자캐시 = {}


def 관리자인가(user_id):
    if user_id in 관리자_아이디:
        return True
    값 = _관리자캐시.get(user_id)
    if 값 and (datetime.now() - 값[1]).total_seconds() < 30:
        return 값[0]
    cursor.execute("SELECT 1 FROM rpg_admins WHERE user_id = ?", (user_id,))
    결과 = cursor.fetchone() is not None
    _관리자캐시[user_id] = (결과, datetime.now())
    return 결과


def 관리자동기화(member):
    """디스코드 역할을 보고 관리자 기록을 켜고 끈다 (웹은 이 기록으로 판단한다)"""
    uid = str(member.id)
    역할 = {r.id for r in getattr(member, "roles", [])}
    if 역할 & 관리자_역할:
        cursor.execute("INSERT OR IGNORE INTO rpg_admins (user_id) VALUES (?)", (uid,))
    elif uid not in 관리자_아이디:
        cursor.execute("DELETE FROM rpg_admins WHERE user_id = ?", (uid,))
    conn.commit()
    _관리자캐시.pop(uid, None)


def 관리자혜택(user_id):
    """모든 장비를 넣어주고 스킬포인트를 모든 능력치를 채울 만큼 맞춘다"""
    if not 관리자인가(user_id):
        return
    for n, d in 무기.items():
        if d.get("숨김"):
            continue
        cursor.execute("INSERT OR IGNORE INTO rpg_inventory (user_id, kind, name, qty) VALUES (?, 'weapon', ?, 1)", (user_id, n))
    for n in 갑옷:
        cursor.execute("INSERT OR IGNORE INTO rpg_inventory (user_id, kind, name, qty) VALUES (?, 'armor', ?, 1)", (user_id, n))
    cursor.execute(
        f"UPDATE rpg_characters SET skill_points = "
        f"({능력치_최대} - stat_str) + ({능력치_최대} - stat_hp) + ({능력치_최대} - stat_spd) + ({능력치_최대} - stat_int) "
        f"WHERE user_id = ?",
        (user_id,),
    )
    conn.commit()


# ============================================================
# 캐릭터
# ============================================================

def 캐릭터(user_id):
    cursor.execute(
        "SELECT name, level, exp, stat_str, stat_hp, stat_spd, stat_int, skill_points, created_at, "
        "COALESCE(gold, 0), COALESCE(weapon, '나무막대기'), COALESCE(armor, '가죽옷'), COALESCE(best_floor, 0) "
        "FROM rpg_characters WHERE user_id = ?",
        (user_id,),
    )
    r = cursor.fetchone()
    if r is None:
        return None
    return {
        "name": r[0], "level": r[1], "exp": r[2],
        "힘": r[3], "체력": r[4], "속도": r[5], "지능": r[6],
        "points": r[7], "created": r[8], "gold": r[9],
        "weapon": r[10], "armor": r[11], "best": r[12], "_uid": user_id,
    }


def _기본장비(user_id):
    """나무막대기와 가죽옷은 항상 가지고 있게 한다."""
    cursor.execute(
        "INSERT OR IGNORE INTO rpg_inventory (user_id, kind, name, qty) VALUES (?, 'weapon', '나무막대기', 1)",
        (user_id,),
    )
    cursor.execute(
        "INSERT OR IGNORE INTO rpg_inventory (user_id, kind, name, qty) VALUES (?, 'armor', '가죽옷', 1)",
        (user_id,),
    )


def 전투능력(c):
    """캐릭터와 장비로 실제 전투 수치를 계산한다."""
    w = 무기.get(c["weapon"], 무기["나무막대기"])
    a = 갑옷.get(c["armor"], 갑옷["가죽옷"])
    강화 = 강화수치(c["_uid"], c["weapon"]) if "_uid" in c else 0
    회피 = 기본_회피 + c["속도"] * 속도당_회피 - a["pen"]
    if c["weapon"] == "AK-47":
        회피 -= 0.02
    if c["weapon"] == "미니건":
        회피 = 0
    return {
        "공격력": 기본_공격력 + c["힘"] * 힘당_공격력,
        "무기피해": (기본_공격력 + c["힘"] * 힘당_공격력 + w["atk"]) * w.get("배율", 1.0) * (1 + 강화 * 강화당_공격력),
        "최대체력": 기본_체력 + c["체력"] * 체력당_체력 + 레벨당_체력 * (c["level"] - 1),
        "방어력": a["dfn"],
        "회피": 회피,                       # 0 이하면 반드시 맞는다
        "치명": c["지능"] * 지능당_치명,
        "강화": 강화,
    }


def _이름검사(이름):
    이름 = (이름 or "").strip()
    최소, 최대 = 이름_길이
    if not (최소 <= len(이름) <= 최대):
        return None, f"이름은 {최소}~{최대}자여야 합니다."
    if any(ch in 이름 for ch in "@#`\n\r*_~|<>"):
        return None, "이름에 특수문자(@ # ` * _ ~ | < >)는 쓸 수 없습니다."
    cursor.execute("SELECT 1 FROM rpg_characters WHERE LOWER(name) = LOWER(?)", (이름,))
    if cursor.fetchone():
        return None, f"'{이름}' 은(는) 이미 다른 사람이 쓰고 있는 이름입니다."
    return 이름, None


def 생성(user_id, 이름):
    if 캐릭터(user_id):
        return False, "이미 캐릭터가 있습니다. `!RPG 정보` 로 확인해보세요.", False
    이름, 오류 = _이름검사(이름)
    if 오류:
        return False, 오류, False
    cursor.execute("SELECT 1 FROM rpg_history WHERE user_id = ?", (user_id,))
    첫생성 = cursor.fetchone() is None
    b = 기본_능력치
    cursor.execute(
        "INSERT INTO rpg_characters (user_id, name, stat_str, stat_hp, stat_spd, stat_int, skill_points, "
        "created_at, gold, weapon, armor, best_floor) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, '나무막대기', '가죽옷', 0)",
        (user_id, 이름, b, b, b, b, 첫생성_포인트 if 첫생성 else 0, _지금()),
    )
    if 첫생성:
        cursor.execute("INSERT INTO rpg_history (user_id, first_created_at) VALUES (?, ?)", (user_id, _지금()))
    _기본장비(user_id)
    conn.commit()
    return True, 캐릭터(user_id), 첫생성


def 포인트사용(user_id, 능력, 수량=1):
    c = 캐릭터(user_id)
    if c is None:
        return False, "캐릭터가 없습니다. `!RPG 생성 [이름]` 으로 먼저 만들어주세요."
    키 = 능력치_별칭.get(str(능력).strip().lower()) or 능력치_별칭.get(str(능력).strip())
    if 키 is None:
        return False, f"'{능력}' 은(는) 없는 능력치입니다. (힘 / 체력 / 속도 / 지능)"
    try:
        수량 = min(c["points"], 능력치_최대 - c[키]) if str(수량).strip() in ("전부", "다", "all") else int(수량)
    except (TypeError, ValueError):
        return False, "포인트는 숫자로 입력해주세요."
    if 수량 <= 0:
        return False, "올릴 수 있는 포인트가 없습니다." if c[키] >= 능력치_최대 or c["points"] <= 0 else "1 포인트 이상 써야 합니다."
    if 수량 > c["points"]:
        return False, f"스킬포인트가 부족합니다. (남은 포인트 {c['points']})"
    if c[키] + 수량 > 능력치_최대:
        남음 = 능력치_최대 - c[키]
        return False, (f"{키}은(는) 이미 최대({능력치_최대})입니다." if 남음 <= 0
                       else f"{키}은(는) 최대 {능력치_최대}까지라 {남음}포인트만 더 올릴 수 있습니다.")
    컬럼 = 능력치[키][2]
    cursor.execute(
        f"UPDATE rpg_characters SET {컬럼} = {컬럼} + ?, skill_points = skill_points - ? WHERE user_id = ?",
        (수량, 수량, user_id),
    )
    conn.commit()
    return True, 캐릭터(user_id)


# ============================================================
# 가방 / 골드 / 카운터
# ============================================================

def 보유(user_id, 종류, 이름):
    if 종류 == "item" and 관리자인가(user_id):
        return 관리자_무한
    cursor.execute("SELECT qty FROM rpg_inventory WHERE user_id = ? AND kind = ? AND name = ?", (user_id, 종류, 이름))
    r = cursor.fetchone()
    return r[0] if r else 0


접두어_목록 = ["슈퍼", "울트라", "하이퍼", "강력한", "반짝이는", "단단한", "날카로운", "위험한"]
접두어_최종 = "레전더리"      # +99 에만 확정으로 붙는다


def 접두어(user_id, 무기이름, 강화=None):
    """
    강화 10단계마다 무작위 접두어 하나 (+99 는 맨 앞에 레전더리).
    저장된 목록을 지금 강화 수치에 맞게 늘리거나 줄이고 돌려준다. (앞쪽이 최근)
    """
    cursor.execute("SELECT enhance, COALESCE(prefix, '[]') FROM rpg_inventory WHERE user_id = ? AND kind = 'weapon' AND name = ?",
                   (user_id, 무기이름))
    r = cursor.fetchone()
    if r is None:
        return []
    강화 = r[0] if 강화 is None else 강화
    try:
        목록 = [x for x in json.loads(r[1]) if x != 접두어_최종]
    except ValueError:
        목록 = []
    필요 = min(9, 강화 // 10)
    바뀜 = False
    while len(목록) < 필요:                       # 모자라면 새로 뽑아 앞에 붙인다 (되도록 겹치지 않게)
        후보 = [w for w in 접두어_목록 if w not in 목록] or 접두어_목록
        목록.insert(0, random.choice(후보))
        바뀜 = True
    if len(목록) > 필요:                          # 강화가 내려가면 최근에 붙은 것부터 뗀다
        목록 = 목록[len(목록) - 필요:]
        바뀜 = True
    if 바뀜:
        cursor.execute("UPDATE rpg_inventory SET prefix = ? WHERE user_id = ? AND kind = 'weapon' AND name = ?",
                       (json.dumps(목록, ensure_ascii=False), user_id, 무기이름))
        conn.commit()          # 열어둔 채로 두면 다른 프로그램(봇·웹)의 쓰기가 전부 막힌다
    return ([접두어_최종] if 강화 >= 최대강화 else []) + 목록


def 무기표시(user_id, 무기이름):
    """접두어를 붙인 보여주기용 이름"""
    앞 = 접두어(user_id, 무기이름)
    return " ".join(앞 + [무기이름])


def 강화수치(user_id, 무기이름):
    cursor.execute("SELECT enhance FROM rpg_inventory WHERE user_id = ? AND kind = 'weapon' AND name = ?", (user_id, 무기이름))
    r = cursor.fetchone()
    return r[0] if r else 0


def 가방추가(user_id, 종류, 이름, 수량=1, 커밋=True):
    cursor.execute(
        "INSERT INTO rpg_inventory (user_id, kind, name, qty) VALUES (?, ?, ?, ?) "
        "ON CONFLICT(user_id, kind, name) DO UPDATE SET qty = qty + ?",
        (user_id, 종류, 이름, 수량, 수량),
    )
    if 커밋:
        conn.commit()


def 가방사용(user_id, 이름, 수량=1, 커밋=True):
    """아이템을 쓴다. 모자라면 False"""
    if 관리자인가(user_id):
        return True
    if 보유(user_id, "item", 이름) < 수량:
        return False
    cursor.execute(
        "UPDATE rpg_inventory SET qty = qty - ? WHERE user_id = ? AND kind = 'item' AND name = ?",
        (수량, user_id, 이름),
    )
    if 커밋:
        conn.commit()
    return True


def 골드변경(user_id, 차이, 커밋=True):
    cursor.execute("UPDATE rpg_characters SET gold = COALESCE(gold, 0) + ? WHERE user_id = ?", (차이, user_id))
    if 커밋:
        conn.commit()


def 카운트(user_id, 키, 증가=0):
    if 증가:
        cursor.execute(
            "INSERT INTO rpg_counters (user_id, key, value) VALUES (?, ?, ?) "
            "ON CONFLICT(user_id, key) DO UPDATE SET value = value + ?",
            (user_id, 키, 증가, 증가),
        )
    cursor.execute("SELECT value FROM rpg_counters WHERE user_id = ? AND key = ?", (user_id, 키))
    r = cursor.fetchone()
    return r[0] if r else 0


def 카운트최대(user_id, 키, 값):
    """지금까지의 최고값만 남긴다 (관찰 연속 횟수, 최고 강화 등)"""
    if 값 > 카운트(user_id, 키):
        cursor.execute(
            "INSERT INTO rpg_counters (user_id, key, value) VALUES (?, ?, ?) "
            "ON CONFLICT(user_id, key) DO UPDATE SET value = ?",
            (user_id, 키, 값, 값),
        )


def _현금(user_id):
    try:
        cursor.execute("SELECT money FROM users WHERE user_id = ?", (user_id,))
        r = cursor.fetchone()
        return int(float(r[0])) if r and r[0] is not None else 0
    except sqlite3.OperationalError:
        return 0


def 골드환전(user_id, 방향, 수량):
    if not 시스템켜짐("경제") and not 관리자인가(user_id):
        return False, "지금 경제 시스템이 점검 중이라 골드 환전을 할 수 없어요."
    if 캐릭터(user_id) is None:
        return False, "캐릭터가 없습니다. `!RPG 생성 [이름]` 으로 먼저 만들어주세요."
    try:
        cursor.execute("BEGIN IMMEDIATE")
        현금 = _현금(user_id)
        cursor.execute("SELECT COALESCE(gold, 0) FROM rpg_characters WHERE user_id = ?", (user_id,))
        골드 = cursor.fetchone()[0]
        if str(수량).strip() in ("전부", "다", "all"):
            개수 = 현금 // 골드_환율 if 방향 == "구매" else 골드
        else:
            개수 = int(str(수량).replace(",", ""))
        if 개수 <= 0:
            conn.rollback()
            return False, "1골드 이상이어야 합니다." if 방향 == "판매" or 현금 >= 골드_환율 else "돈이 부족해서 1골드도 살 수 없습니다."
        금액 = 개수 * 골드_환율
        if 방향 == "구매" and 현금 < 금액:
            conn.rollback()
            return False, f"돈이 부족합니다. {개수:,}골드는 {금액:,}원 (보유 {현금:,}원, 최대 {현금 // 골드_환율:,}골드)"
        if 방향 == "판매" and 골드 < 개수:
            conn.rollback()
            return False, f"골드가 부족합니다. (보유 {골드:,}골드)"
        새현금 = 현금 - 금액 if 방향 == "구매" else 현금 + 금액
        새골드 = 골드 + 개수 if 방향 == "구매" else 골드 - 개수
        cursor.execute("UPDATE users SET money = ? WHERE user_id = ?", (str(새현금), user_id))
        cursor.execute("UPDATE rpg_characters SET gold = ? WHERE user_id = ?", (새골드, user_id))
        conn.commit()
    except (ValueError, TypeError):
        conn.rollback()
        return False, "골드 수량은 숫자나 `전부` 로 입력해주세요."
    return True, {"개수": 개수, "금액": 금액, "현금": 새현금, "골드": 새골드}


# ============================================================
# 업적 판정
# ============================================================

def 업적보유(user_id, 이름):
    cursor.execute("SELECT 1 FROM rpg_achievements WHERE user_id = ? AND name = ?", (user_id, 이름))
    return cursor.fetchone() is not None


def _업적조건(uid):
    k = lambda 키: 카운트(uid, 키)
    투척, 총기 = k("처치_투척"), k("처치_총기")

    def 봇조회(sql):
        try:
            cursor.execute(sql, (uid,))
            return cursor.fetchone()
        except sqlite3.OperationalError:
            return None

    주식 = 봇조회("SELECT 1 FROM portfolio p JOIN stocks s ON s.symbol = p.symbol "
               "WHERE p.user_id = ? AND s.is_premium IN (0, 1) AND CAST(p.quantity AS INTEGER) > 0")
    채굴 = 봇조회("SELECT 1 FROM user_rigs WHERE user_id = ? AND quantity > 0")

    return {
        "첫 사냥": k("처치") >= 1,
        "13일의 금요일": k("처치_마체테") >= 50,
        "조금 더 강한 화력...": 투척 >= 15 and 총기 >= 50,
        "더 강한 화력!": 강화수치(uid, "RPG-7") >= 50 and k("처치_RPG-7") >= 30 and 투척 >= 50 and 총기 >= 100,
        "관찰해온 신념만이 미래를 연다": k("관찰연속_최대") >= 5,
        "어쩌다 이지경까지": k("아드레날린") >= 20,
        "길막": min(k("길막_가시철조망"), k("길막_지뢰"), k("길막_설치형 방패")) >= 1
                and k("길막_가시철조망") + k("길막_지뢰") + k("길막_설치형 방패") >= 15,
        "신발보다 싼 무기의 위력": k("처치_AK-47") >= 30,
        "알라신의 마법의 알라봉": k("처치_RPG-7") >= 40,
        "던전 탐험가": k("최고층") >= 10,
        "심연을 들여다보는 자": k("최고층") >= 50,
        "끝없는 탑": k("최고층") >= 100,
        "강화 장인": k("최고강화") >= 30,
        "산산조각": k("무기소멸") >= 1,
        "학살자": k("처치") >= 1000,
        "개미": 주식 is not None,
        "채굴꾼": 채굴 is not None,
        "억만장자": _현금(uid) >= 100_000_000,
        "뛰어난 내구성": k("버티기연속_최대") >= 10,
        "호그 라이더!": k("처치_호그장착") >= 100 and min(_호그레벨(uid)) >= 30,
    }


def _호그레벨(uid):
    cursor.execute("SELECT hp_lv, skill_lv FROM rpg_pets WHERE user_id = ? AND pet = '라이딩 호그'", (uid,))
    r = cursor.fetchone()
    return (r[0], r[1]) if r else (0, 0)


def 업적진행(uid):
    """{업적 이름: [(항목, 현재, 목표), ...]} — 업적 화면에 진행도를 보여준다"""
    k = lambda 키: 카운트(uid, 키)
    def 봇조회(sql):
        try:
            cursor.execute(sql, (uid,))
            return cursor.fetchone() is not None
        except sqlite3.OperationalError:
            return False
    주식 = 봇조회("SELECT 1 FROM portfolio p JOIN stocks s ON s.symbol = p.symbol "
               "WHERE p.user_id = ? AND s.is_premium IN (0, 1) AND CAST(p.quantity AS INTEGER) > 0")
    채굴 = 봇조회("SELECT 1 FROM user_rigs WHERE user_id = ? AND quantity > 0")
    투척, 총기, rpg = k("처치_투척"), k("처치_총기"), k("처치_RPG-7")
    길막 = [k("길막_가시철조망"), k("길막_지뢰"), k("길막_설치형 방패")]
    return {
        "첫 사냥": [("처치", k("처치"), 1)],
        "13일의 금요일": [("마체테 처치", k("처치_마체테"), 50)],
        "조금 더 강한 화력...": [("수류탄·화염병 처치", 투척, 15), ("총기 처치", 총기, 50)],
        "더 강한 화력!": [("RPG-7 강화", 강화수치(uid, "RPG-7"), 50), ("RPG-7 처치", rpg, 30),
                         ("수류탄·화염병 처치", 투척, 50), ("총기 처치", 총기, 100)],
        "관찰해온 신념만이 미래를 연다": [("연속 관찰 최고", k("관찰연속_최대"), 5)],
        "어쩌다 이지경까지": [("아드레날린 사용", k("아드레날린"), 20)],
        "길막": [("가시철조망", 길막[0], 1), ("지뢰", 길막[1], 1), ("설치형 방패", 길막[2], 1), ("합계", sum(길막), 15)],
        "신발보다 싼 무기의 위력": [("AK-47 처치", k("처치_AK-47"), 30)],
        "알라신의 마법의 알라봉": [("RPG-7 처치", rpg, 40)],
        "던전 탐험가": [("최고 층", k("최고층"), 10)],
        "심연을 들여다보는 자": [("최고 층", k("최고층"), 50)],
        "끝없는 탑": [("최고 층", k("최고층"), 100)],
        "강화 장인": [("최고 강화", k("최고강화"), 30)],
        "산산조각": [("무기 소멸", k("무기소멸"), 1)],
        "학살자": [("처치", k("처치"), 1000)],
        "개미": [("주식 보유", int(주식), 1)],
        "채굴꾼": [("채굴기 보유", int(채굴), 1)],
        "억만장자": [("현금(만원)", _현금(uid) // 10_000, 10_000)],
        "뛰어난 내구성": [("연속으로 버틴 최고", k("버티기연속_최대"), 10)],
        "호그 라이더!": [("호그와 함께 처치", k("처치_호그장착"), 100),
                        ("호그 체력 Lv", _호그레벨(uid)[0], 30), ("호그 능력 Lv", _호그레벨(uid)[1], 30)],
    }


def 업적확인(user_id):
    """새로 달성한 업적을 기록하고 보상을 준다. 새 업적 이름 목록을 돌려준다."""
    if 캐릭터(user_id) is None:
        return []
    새로 = []
    for 이름, 달성 in _업적조건(user_id).items():
        if 달성 and not 업적보유(user_id, 이름):
            cursor.execute("INSERT INTO rpg_achievements (user_id, name, at) VALUES (?, ?, ?)", (user_id, 이름, _지금()))
            골드변경(user_id, 업적[이름]["보상"], 커밋=False)
            if 업적[이름].get("보상무기"):
                가방추가(user_id, "weapon", 업적[이름]["보상무기"], 1, 커밋=False)
            새로.append(이름)
    conn.commit()
    return 새로


def 해금여부(user_id, 종류, 이름):
    """(해금됐는지, 안 됐으면 이유)"""
    표 = 무기 if 종류 == "weapon" else 갑옷
    d = 표[이름]
    if d.get("숨김"):
        return False, "???"
    if 관리자인가(user_id):
        return True, ""
    if d["ach"]:
        return (True, "") if 업적보유(user_id, d["ach"]) else (False, f"업적 '{d['ach']}' 필요")
    if d["lv"]:
        c = 캐릭터(user_id)
        return (True, "") if c and c["level"] >= d["lv"] else (False, f"Lv.{d['lv']} 필요")
    return True, ""


# ============================================================
# 이름 찾기 — 띄어쓰기·대소문자 무시, 앞부분만 쳐도 찾는다
# ============================================================

def _정리(s):
    return str(s or "").replace(" ", "").lower()


def 찾기(이름):
    """(종류, 정식이름) 또는 (None, None)"""
    q = _정리(이름)
    if not q:
        return None, None
    후보 = [("weapon", n) for n in 무기] + [("armor", n) for n in 갑옷] + [("item", n) for n in 아이템]
    for 종류, n in 후보:
        if _정리(n) == q:
            return 종류, n
    걸림 = [(종류, n) for 종류, n in 후보 if q in _정리(n)]
    return 걸림[0] if len(걸림) == 1 else (None, None)


아이템_판매상한 = 0.75            # 상점가의 75%를 넘으면 사서 되팔기로 돈이 복사된다 (상인 할인 최대 20%)


def 판매가치배율(user_id):
    """던전을 깊이 갈수록 물건 값이 오른다. 단, 판매가가 상점가의 75%를 넘지 않게 한다."""
    c = 캐릭터(user_id)
    return min(아이템_판매상한 / 판매_비율, 1 + (c["best"] if c else 0) / 100)


# ============================================================
# 상점 — 구매 / 판매 / 장착
# ============================================================

def 구매(user_id, 이름, 수량=1, 할인=0.0):
    c = 캐릭터(user_id)
    if c is None:
        return False, "캐릭터가 없습니다. `!RPG 생성 [이름]` 으로 먼저 만들어주세요."
    if 관리자인가(user_id):
        return False, "관리자는 모든 장비와 아이템을 이미 무한으로 가지고 있습니다."
    종류, n = 찾기(이름)
    if n is None:
        return False, f"'{이름}' 을(를) 찾을 수 없습니다. `!RPG 상점` 으로 이름을 확인해주세요."

    if 종류 in ("weapon", "armor"):
        if 보유(user_id, 종류, n):
            return False, f"{n}은(는) 이미 가지고 있습니다. `!RPG 장착 {n}` 으로 착용하세요."
        됨, 이유 = 해금여부(user_id, 종류, n)
        if not 됨:
            return False, f"{n}은(는) 아직 잠겨 있습니다. ({이유})"
        가격 = (무기 if 종류 == "weapon" else 갑옷)[n]["price"]
        개수 = 1
    else:
        try:
            개수 = int(수량)
        except (TypeError, ValueError):
            return False, "수량은 숫자로 입력해주세요."
        if 개수 <= 0:
            return False, "1개 이상 사야 합니다."
        가격 = 아이템[n]["price"] * 개수

    가격 = math.ceil(가격 * (1 - 할인))
    if c["gold"] < 가격:
        return False, f"골드가 부족합니다. (필요 {가격:,} / 보유 {c['gold']:,})"

    골드변경(user_id, -가격, 커밋=False)
    가방추가(user_id, 종류, n, 개수, 커밋=False)
    conn.commit()
    return True, {"이름": n, "종류": 종류, "개수": 개수, "가격": 가격, "골드": c["gold"] - 가격}


def 판매(user_id, 이름, 수량=1):
    c = 캐릭터(user_id)
    if c is None:
        return False, "캐릭터가 없습니다."
    if 관리자인가(user_id):
        return False, "관리자는 장비와 아이템이 무한이라 팔거나 환불할 수 없습니다."
    종류, n = 찾기(이름)
    if n is None:
        return False, f"'{이름}' 을(를) 찾을 수 없습니다."
    가진수 = 보유(user_id, 종류, n)
    if 가진수 <= 0:
        return False, f"{n}을(를) 가지고 있지 않습니다."

    if 종류 in ("weapon", "armor"):
        if n in ("나무막대기", "가죽옷"):
            return False, f"{n}은(는) 기본 장비라 팔 수 없습니다."
        if n in (c["weapon"], c["armor"]):
            return False, f"{n}은(는) 착용 중입니다. 다른 장비로 바꾼 뒤 팔아주세요."
        단가 = (무기 if 종류 == "weapon" else 갑옷)[n]["price"]
        if 단가 <= 0:
            return False, f"{n}은(는) 업적 보상이라 팔 수 없습니다."
        개수 = 1
        강화 = 강화수치(user_id, n) if 종류 == "weapon" else 0
        받는돈 = round(단가 * 장비_환불비율)
        cursor.execute("DELETE FROM rpg_inventory WHERE user_id = ? AND kind = ? AND name = ?", (user_id, 종류, n))
        cursor.execute("UPDATE rpg_characters SET pet_weapon = NULL WHERE user_id = ? AND pet_weapon = ?", (user_id, n))
    else:
        개수 = 가진수 if str(수량).strip() in ("전부", "다", "all") else int(수량)
        if 개수 <= 0 or 개수 > 가진수:
            return False, f"판매 수량이 올바르지 않습니다. (보유 {가진수}개)"
        받는돈 = round(아이템[n]["price"] * 판매_비율 * 판매가치배율(user_id) * 개수)
        가방사용(user_id, n, 개수, 커밋=False)

    골드변경(user_id, 받는돈, 커밋=False)
    conn.commit()
    return True, {"이름": n, "개수": 개수, "받은골드": 받는돈, "골드": c["gold"] + 받는돈}


def 장착(user_id, 이름):
    c = 캐릭터(user_id)
    if c is None:
        return False, "캐릭터가 없습니다."
    종류, n = 찾기(이름)
    if 종류 not in ("weapon", "armor"):
        return False, f"'{이름}' 은(는) 장착할 수 있는 무기나 갑옷이 아닙니다."
    if not 보유(user_id, 종류, n):
        return False, f"{n}을(를) 가지고 있지 않습니다. `!RPG 구매 {n}`"
    if 전투중(user_id):
        return False, "전투 중에는 장비를 바꿀 수 없습니다."
    컬럼 = "weapon" if 종류 == "weapon" else "armor"
    cursor.execute(f"UPDATE rpg_characters SET {컬럼} = ? WHERE user_id = ?", (n, user_id))
    if 종류 == "weapon":
        cursor.execute("UPDATE rpg_characters SET pet_weapon = NULL WHERE user_id = ? AND pet_weapon = ?", (user_id, n))
    conn.commit()
    return True, n


# ============================================================
# 강화
# ============================================================

최대강화 = 99
강화_골드배율 = 5            # +n 강화에 5 × n 골드 (예전 10 × n)


def 강화비용(현재):
    return 강화_골드배율 * (현재 + 1)


def 강화(user_id, 이름=None, 업적검사=True):
    """반환: (성공여부, 결과 dict 또는 오류문자열)"""
    c = 캐릭터(user_id)
    if c is None:
        return False, "캐릭터가 없습니다."
    n = c["weapon"] if not 이름 else 찾기(이름)[1]
    if n is None or n not in 무기:
        return False, f"'{이름}' 은(는) 강화할 수 있는 무기가 아닙니다."
    if not 보유(user_id, "weapon", n):
        return False, f"{n}을(를) 가지고 있지 않습니다."
    if 전투중(user_id):
        return False, "전투 중에는 강화할 수 없습니다."

    현재 = 강화수치(user_id, n)
    if 현재 >= 최대강화:
        return False, f"{n}은(는) 이미 최대 강화(+{최대강화})입니다."

    비용 = 0 if 관리자인가(user_id) else 강화비용(현재)
    if c["gold"] < 비용:
        return False, f"골드가 부족합니다. +{현재 + 1} 강화에 {비용:,}골드가 필요합니다. (보유 {c['gold']:,})"
    재료 = 무기[n]["탄약"]
    if 재료 and 보유(user_id, "item", 재료[0]) < 1:
        return False, f"{n} 강화에는 {재료[0]} 1개가 필요합니다."

    if 비용:
        골드변경(user_id, -비용, 커밋=False)
    if 재료:
        가방사용(user_id, 재료[0], 1, 커밋=False)

    전접두어 = 접두어(user_id, n, 현재)
    성공률 = max(0.01, (100 - 현재) / 100)
    결과 = {"_전접두어": 전접두어, "무기": n, "이전": 현재, "비용": 비용, "재료": 재료[0] if 재료 else None,
            "성공률": 성공률, "결과": "", "이후": 현재}

    if random.random() < 성공률:
        결과["결과"], 결과["이후"] = "성공", 현재 + 1
    else:
        결과["결과"] = "실패"
        실패율 = 1 - 성공률
        if n in ("노키아 3310", 신의노키아):
            pass                                   # 절대 부서지지 않는다
        elif 현재 >= 50 and random.random() < 실패율 / 20:
            if 보유(user_id, "item", "파괴방지권") > 0:
                가방사용(user_id, "파괴방지권", 1, 커밋=False)
                결과["결과"] = "파괴방지"
            else:
                결과["결과"] = "소멸"
        elif 현재 >= 30 and random.random() < 실패율 / 10:
            결과["결과"], 결과["이후"] = "하락", 현재 - 1

    if 결과["결과"] == "소멸":
        cursor.execute("DELETE FROM rpg_inventory WHERE user_id = ? AND kind = 'weapon' AND name = ?", (user_id, n))
        cursor.execute("UPDATE rpg_characters SET pet_weapon = NULL WHERE user_id = ? AND pet_weapon = ?", (user_id, n))
        if c["weapon"] == n:
            cursor.execute("UPDATE rpg_characters SET weapon = '나무막대기' WHERE user_id = ?", (user_id,))
        _기본장비(user_id)
        카운트(user_id, "무기소멸", 1)
    else:
        cursor.execute(
            "UPDATE rpg_inventory SET enhance = ? WHERE user_id = ? AND kind = 'weapon' AND name = ?",
            (결과["이후"], user_id, n),
        )
        카운트최대(user_id, "최고강화", 결과["이후"])
        if n == "노키아 3310" and 결과["이후"] >= 최대강화:
            cursor.execute("DELETE FROM rpg_inventory WHERE user_id = ? AND kind = 'weapon' AND name = '노키아 3310'", (user_id,))
            cursor.execute(
                "INSERT OR REPLACE INTO rpg_inventory (user_id, kind, name, qty, enhance) VALUES (?, 'weapon', ?, 1, ?)",
                (user_id, 신의노키아, 최대강화),
            )
            if c["weapon"] == "노키아 3310":
                cursor.execute("UPDATE rpg_characters SET weapon = ? WHERE user_id = ?", (신의노키아, user_id))
            cursor.execute("UPDATE rpg_characters SET pet_weapon = ? WHERE user_id = ? AND pet_weapon = '노키아 3310'", (신의노키아, user_id))
            결과["결과"], 결과["무기"] = "변신", 신의노키아
    if 결과["결과"] not in ("소멸", "변신"):
        전접두어 = 결과.get("_전접두어")
        결과["접두어"] = 접두어(user_id, n)
        결과["표시"] = " ".join(결과["접두어"] + [n])
        새것 = [w for w in 결과["접두어"] if w not in (전접두어 or [])]
        결과["새접두어"] = 새것[0] if 새것 and 결과["결과"] == "성공" else None
    else:
        결과["표시"] = 결과["무기"]
        결과["새접두어"] = None
    conn.commit()
    결과["새업적"] = 업적확인(user_id) if 업적검사 else []
    return True, 결과


