_시스템캐시 = {}


def 시스템켜짐(이름):
    저장 = _시스템캐시.get(이름)
    if 저장 and (datetime.now() - 저장[1]).total_seconds() < 3:
        return 저장[0]
    cursor.execute("SELECT value FROM bot_settings WHERE key = ?", (f"system:{이름}",))
    r = cursor.fetchone()
    켜짐 = not (r and r[0] == "off")
    _시스템캐시[이름] = (켜짐, datetime.now())
    return 켜짐


def RPG사용가능(user_id):
    """꺼져 있어도 관리자는 쓸 수 있다"""
    return 시스템켜짐("RPG") or 관리자인가(user_id)


