# ============================================================
# 하이퍼버닝 — 관리자가 기간 동안 획득량(골드·경험치·간식) 배율을 바꾼다
# ============================================================

def 하이퍼버닝():
    """(배율, 종료시각) — 꺼져 있으면 (1.0, None)"""
    cursor.execute("SELECT value FROM rpg_meta WHERE key = 'hyper'")
    r = cursor.fetchone()
    if not r or not r[0]:
        return 1.0, None
    try:
        배율, 끝 = r[0].split("|")
        끝 = datetime.fromisoformat(끝)
    except ValueError:
        return 1.0, None
    if datetime.now() >= 끝:
        return 1.0, None
    return float(배율), 끝


def 하이퍼버닝설정(배율, 분):
    if 배율 is None:
        cursor.execute("DELETE FROM rpg_meta WHERE key = 'hyper'")
    else:
        끝 = datetime.now() + timedelta(minutes=분)
        cursor.execute("INSERT OR REPLACE INTO rpg_meta (key, value) VALUES ('hyper', ?)",
                       (f"{배율}|{끝.isoformat(timespec='milliseconds')}",))
    conn.commit()


_기간단위 = {                                   # 1 단위가 몇 분인지
    "ms": 1 / 60000, "밀리초": 1 / 60000,
    "s": 1 / 60, "sec": 1 / 60, "초": 1 / 60,
    "m": 1, "min": 1, "분": 1,
    "h": 60, "시간": 60,
    "d": 1440, "일": 1440,
}


def 기간해석(글):
    """
    '500ms' '30s' '10초' '30m' '2h' '1d' '1h30m' '2분30초' '90'(단위 없으면 분) → 분 (소수 가능)
    """
    글 = str(글).strip().lower().replace(" ", "")
    if not 글:
        raise ValueError("기간이 비었습니다")
    단위목록 = "|".join(sorted(map(re.escape, _기간단위), key=len, reverse=True))
    조각 = re.findall(rf"(\d+(?:\.\d+)?)({단위목록})?", 글)
    if not 조각 or "".join(수 + 단위 for 수, 단위 in 조각) != 글:
        raise ValueError(f"기간을 알아볼 수 없습니다: {글}")
    return sum(float(수) * _기간단위.get(단위, 1) for 수, 단위 in 조각)


def 기간문구(분):
    초 = 분 * 60
    if 초 < 1:
        return f"{초 * 1000:g}밀리초"
    if 초 < 60:
        return f"{초:g}초"
    if 분 < 60:
        return f"{int(분)}분" + (f" {round(초 % 60)}초" if round(초 % 60) else "")
    시간 = 분 / 60
    return f"{시간:g}시간" if 시간 < 48 else f"{시간 / 24:g}일"


def 시각문구(끝, 분):
    """짧은 하이퍼버닝이면 초·밀리초까지 보여준다"""
    if 분 * 60 < 60:
        return 끝.strftime("%H:%M:%S.") + f"{끝.microsecond // 1000:03d}"
    if 분 < 60 * 24:
        return 끝.strftime("%H:%M:%S")
    return 끝.strftime("%m/%d %H:%M")


