# 악세서리
# ============================================================

def 내악세서리(user_id):
    cursor.execute("SELECT name, equipped FROM rpg_accessories WHERE user_id = ? ORDER BY at", (user_id,))
    return [{"이름": n, "장착": bool(장)} for (n, 장) in cursor.fetchall() if n in 악세서리]


def 착용악세(user_id):
    return [a["이름"] for a in 내악세서리(user_id) if a["장착"]]


def 악세지급(user_id, 이름):
    """새로 얻었으면 True. 빈 칸이 있으면 바로 착용한다."""
    cursor.execute("INSERT OR IGNORE INTO rpg_accessories (user_id, name, at) VALUES (?, ?, ?)", (user_id, 이름, _지금()))
    새로 = cursor.rowcount > 0
    if 새로 and 이름 not in 황금빛정신:     # 황금빛 정신은 목록에 안 보이는 수집품이라 착용 칸을 안 쓴다
        cursor.execute(
            "UPDATE rpg_accessories SET equipped = 1 WHERE user_id = ? AND name = ? "
            "AND (SELECT COUNT(*) FROM rpg_accessories WHERE user_id = ? AND equipped = 1) < ?",
            (user_id, 이름, user_id, 악세_최대),
        )
    conn.commit()
    return 새로


def _악세찾기(user_id, 이름, 목록=None):
    q = _정리(이름)
    후보 = [n for n in (목록 if 목록 is not None else [a["이름"] for a in 내악세서리(user_id)]) if q in _정리(n)]
    정확 = [n for n in 후보 if _정리(n) == q]
    return (정확 or 후보 or [None])[0]


def 악세장착(user_id, 이름, 해제=False):
    """착용: (True, 이름). 해제: (True, None) — 이름이 없으면 전부 뺀다."""
    if 전투중(user_id):
        return False, "전투 중에는 악세서리를 바꿀 수 없습니다."
    if 해제 or 이름 in (None, "", "해제"):
        if 이름 in (None, "", "해제"):
            cursor.execute("UPDATE rpg_accessories SET equipped = 0 WHERE user_id = ? AND equipped = 1", (user_id,))
        else:
            n = _악세찾기(user_id, 이름, 착용악세(user_id))
            if n is None:
                return False, f"'{이름}'은(는) 착용 중이 아닙니다."
            cursor.execute("UPDATE rpg_accessories SET equipped = 0 WHERE user_id = ? AND name = ?", (user_id, n))
        conn.commit()
        return True, None
    n = _악세찾기(user_id, 이름, [a["이름"] for a in 내악세서리(user_id) if a["이름"] not in 황금빛정신])
    if n is None:
        return False, f"'{이름}' 악세서리를 가지고 있지 않습니다."
    if n in 착용악세(user_id):
        return False, f"{n}은(는) 이미 착용 중입니다."
    cursor.execute(
        "UPDATE rpg_accessories SET equipped = 1 WHERE user_id = ? AND name = ? AND equipped = 0 "
        "AND (SELECT COUNT(*) FROM rpg_accessories WHERE user_id = ? AND equipped = 1) < ?",
        (user_id, n, user_id, 악세_최대),
    )
    if cursor.rowcount == 0:
        conn.rollback()
        return False, f"악세서리는 최대 {악세_최대}개까지 착용할 수 있습니다. 먼저 하나를 빼세요."
    conn.commit()
    return True, n


