def 간식(user_id):
    if 관리자인가(user_id):
        return 관리자_무한
    cursor.execute("SELECT COALESCE(snacks, 0) FROM rpg_characters WHERE user_id = ?", (user_id,))
    r = cursor.fetchone()
    return r[0] if r else 0


def 내펫들(user_id):
    """[{이름, 체력lv, 능력lv, 장착}]. 스탠드는 별명 = 스탠드 이름, 두 레벨 = 스탠드 레벨"""
    if 관리자인가(user_id):
        for n, d in 펫.items():
            if not d.get("숨김"):
                cursor.execute("INSERT OR IGNORE INTO rpg_pets (user_id, pet) VALUES (?, ?)", (user_id, n))
        conn.commit()
    cursor.execute("SELECT pet FROM rpg_characters WHERE user_id = ?", (user_id,))
    r = cursor.fetchone()
    장착 = r[0] if r else None
    cursor.execute("SELECT pet, hp_lv, skill_lv, nickname FROM rpg_pets WHERE user_id = ?", (user_id,))
    결과 = []
    for n, h, k, 별명 in cursor.fetchall():
        if n not in 펫:
            continue
        if n == "스탠드":
            st = 내스탠드(user_id)
            if st is None:
                continue
            h = k = st["레벨"]
            별명 = st["이름"]
        결과.append({"이름": n, "체력lv": h, "능력lv": k, "장착": n == 장착, "별명": 별명 or n})
    return 결과


def _펫찾기(이름, user_id=None):
    q = _정리(이름)
    if user_id and q:
        st = 내스탠드(user_id)
        if st and (q == _정리(st["이름"]) or q in _정리(st["이름"])):
            return "스탠드"
    for n in 펫:
        if _정리(n) == q or (q and q in _정리(n)):
            return n
    return None


# ============================================================
# 스탠드 (??? 스탠드 디스크 → 요청 → 관리자가 클로드 코드로 능력을 만들어 완성)
#   능력 형식: {"이름", "설명", "확률"(매 턴, 0~1), "쿨"(발동 뒤 쉬는 턴, 선택), "조건"(선택: {"체력이하": 0.3}),
#              "효과": [{"종류": ...}, ...]}
#   효과 종류 (수치는 스탠드_레벨배율을 곱한다 — 턴·횟수·확률은 안 곱함):
#     피해 {배율, 대상: 하나/전체, 치명: bool}  — 주인 무기피해 × 배율
#     상태 {이름: 구속/출혈/화상/혼란, 턴, 대상}   — 적에게
#     회복 {비율}                                — 주인 최대체력 × 비율
#     방패 {횟수}  회피 {턴}(연막 +40%)  해제 {}(내 상태이상 전부)
#     강화 {배율, 턴}(주인 무기피해 ×)  보호 {비율, 턴}(받는 피해 -비율, 최대 0.9)  반사 {턴}(가시철조망)
# ============================================================

def 내스탠드(user_id):
    cursor.execute("SELECT name, level, exp, abilities, created_at FROM rpg_stands WHERE user_id = ?", (user_id,))
    r = cursor.fetchone()
    if r is None:
        return None
    try:
        능력 = json.loads(r[3] or "[]")
    except ValueError:
        능력 = []
    return {"이름": r[0], "레벨": r[1], "경험": r[2], "능력들": 능력, "만든때": r[4],
            "다음": 스탠드_필요경험치(r[1]) if r[1] < 스탠드_최대레벨 else None}


def 스탠드디스크수(user_id):
    return 카운트(user_id, "스탠드디스크")


def 스탠드요청목록(user_id=None, 상태="대기"):
    조건, 값 = [], []
    if user_id:
        조건.append("user_id = ?"); 값.append(user_id)
    if 상태:
        조건.append("status = ?"); 값.append(상태)
    cursor.execute("SELECT id, user_id, kind, stand_name, request, status, note, created_at, done_at FROM rpg_stand_requests"
                   + (" WHERE " + " AND ".join(조건) if 조건 else "") + " ORDER BY id", 값)
    return [dict(zip(("id", "user_id", "종류", "이름", "내용", "상태", "메모", "요청때", "처리때"), r)) for r in cursor.fetchall()]


def 스탠드능력검사(a):
    """능력 dict 형식 확인. 문제 있으면 이유 문자열, 괜찮으면 None"""
    if not isinstance(a, dict) or not a.get("이름") or not isinstance(a.get("효과"), list) or not a["효과"]:
        return "이름과 효과 목록이 필요해요"
    if not 0 < float(a.get("확률", 1)) <= 1:
        return "확률은 0~1"
    for 효 in a["효과"]:
        if 효.get("종류") not in 스탠드_능력종류:
            return f"모르는 효과 종류: {효.get('종류')}"
        if 효["종류"] == "상태" and 효.get("이름") not in ("구속", "출혈", "화상", "혼란"):
            return f"적에게 거는 상태는 구속/출혈/화상/혼란만: {효.get('이름')}"
    return None


def 스탠드요청(user_id, 종류, 내용, 이름=None):
    """종류: 생성(디스크 1장 사용) / 능력(레벨 20마다 1칸). 반환 (성공, 문구)"""
    if 캐릭터(user_id) is None:
        return False, "캐릭터가 없습니다."
    내용 = (내용 or "").strip()
    if not 내용:
        return False, "스탠드 능력을 설명해 주세요."
    if len(내용) > 스탠드_요청최대:
        return False, f"능력 설명은 {스탠드_요청최대}자까지예요."
    대기 = 스탠드요청목록(user_id)
    st = 내스탠드(user_id)
    if 종류 == "생성":
        이름 = (이름 or "").strip()
        최소, 최대 = 스탠드_이름길이
        if not (최소 <= len(이름) <= 최대):
            return False, f"스탠드 이름은 {최소}~{최대}자예요."
        if any(ch in 이름 for ch in "@#`\n\r*_~|<>"):
            return False, "스탠드 이름에 특수문자(@ # ` * _ ~ | < >)는 쓸 수 없어요."
        if st:
            return False, f"이미 스탠드 **{st['이름']}**이(가) 있어요."
        if any(r["종류"] == "생성" for r in 대기):
            return False, "이미 만들고 있는 스탠드가 있어요. 완성될 때까지 기다려 주세요."
        cursor.execute("UPDATE rpg_counters SET value = value - 1 WHERE user_id = ? AND key = '스탠드디스크' AND value >= 1",
                       (user_id,))
        if cursor.rowcount == 0:
            conn.rollback()
            return False, f"{스탠드디스크}가 없어요. 엔리코 푸치를 쓰러뜨리면 얻을 수 있어요."
    elif 종류 == "능력":
        if st is None:
            return False, "스탠드가 아직 없어요."
        남은칸 = 스탠드능력칸(st["레벨"]) - len(st["능력들"]) - sum(1 for r in 대기 if r["종류"] == "능력")
        if 남은칸 <= 0:
            다음 = (st["레벨"] // 스탠드_능력간격 + 1) * 스탠드_능력간격
            return False, (f"지금은 새 능력을 만들 수 없어요. (Lv.{다음}에 한 칸 더)" if 다음 <= 스탠드_최대레벨
                           else "능력 칸이 가득 찼어요.")
        이름 = st["이름"]
    else:
        return False, "생성 또는 능력"
    cursor.execute("INSERT INTO rpg_stand_requests (user_id, kind, stand_name, request, created_at) VALUES (?, ?, ?, ?, ?)",
                   (user_id, 종류, 이름, 내용, _지금()))
    번호 = cursor.lastrowid
    conn.commit()
    print(f"[{datetime.now()}] RPG 스탠드 요청 #{번호} {user_id} {종류} {이름}: {내용}")
    return True, 번호


def 스탠드처리(요청id, 능력=None, 거절=None):
    """관리자(클로드 코드)가 요청을 처리한다. 능력 dict 를 주면 완성, 거절 문구를 주면 거절(생성이면 디스크 돌려줌).
    반환 (성공, 문구, 요청 dict)"""
    r = next((x for x in 스탠드요청목록(None, None) if x["id"] == 요청id), None)
    if r is None or r["상태"] != "대기":
        return False, "대기 중인 요청이 아니에요.", r
    uid = r["user_id"]
    if 거절 is not None:
        cursor.execute("UPDATE rpg_stand_requests SET status = '거절', note = ?, done_at = ? WHERE id = ?", (거절, _지금(), 요청id))
        if r["종류"] == "생성":
            카운트(uid, "스탠드디스크", 1)
        conn.commit()
        return True, "거절했어요" + (" (디스크 돌려줌)" if r["종류"] == "생성" else ""), r
    오류 = 스탠드능력검사(능력)
    if 오류:
        return False, 오류, r
    if r["종류"] == "생성":
        cursor.execute("INSERT INTO rpg_stands (user_id, name, abilities, created_at) VALUES (?, ?, ?, ?)",
                       (uid, r["이름"], json.dumps([능력], ensure_ascii=False), _지금()))
        cursor.execute("INSERT OR IGNORE INTO rpg_pets (user_id, pet) VALUES (?, '스탠드')", (uid,))
        cursor.execute("UPDATE rpg_characters SET pet = '스탠드' WHERE user_id = ? AND pet IS NULL", (uid,))
    else:
        st = 내스탠드(uid)
        cursor.execute("UPDATE rpg_stands SET abilities = ? WHERE user_id = ?",
                       (json.dumps(st["능력들"] + [능력], ensure_ascii=False), uid))
    cursor.execute("UPDATE rpg_stand_requests SET status = '완료', note = ?, done_at = ? WHERE id = ?",
                   (능력["이름"], _지금(), 요청id))
    conn.commit()
    return True, "완성", r


def 스탠드경험치(user_id, 양):
    """전투 경험치를 스탠드에도 넣는다. 반환 (새 레벨, 오른 레벨 수, 새 능력 칸이 생겼는지)"""
    st = 내스탠드(user_id)
    if st is None or 양 <= 0:
        return None, 0, False
    레벨, 경험 = st["레벨"], st["경험"] + int(양)
    오름 = 0
    while 레벨 < 스탠드_최대레벨 and 경험 >= 스탠드_필요경험치(레벨):
        경험 -= 스탠드_필요경험치(레벨)
        레벨 += 1
        오름 += 1
    if 레벨 >= 스탠드_최대레벨:
        경험 = 0
    cursor.execute("UPDATE rpg_stands SET level = ?, exp = ? WHERE user_id = ?", (레벨, 경험, user_id))
    return 레벨, 오름, 스탠드능력칸(레벨) > 스탠드능력칸(st["레벨"])


def 펫구매(user_id, 이름):
    c = 캐릭터(user_id)
    if c is None:
        return False, "캐릭터가 없습니다."
    n = _펫찾기(이름)
    if n is None or 펫[n].get("숨김"):
        return False, f"'{이름}' 은(는) 없는 펫입니다. ({' / '.join(k for k, d in 펫.items() if not d.get('숨김'))})"
    if any(p["이름"] == n for p in 내펫들(user_id)):
        return False, f"{n}은(는) 이미 키우고 있습니다."
    가격 = 펫[n]["price"]
    if c["gold"] < 가격:
        return False, f"골드가 부족합니다. (필요 {가격:,} / 보유 {c['gold']:,})"
    골드변경(user_id, -가격, 커밋=False)
    cursor.execute("INSERT INTO rpg_pets (user_id, pet) VALUES (?, ?)", (user_id, n))
    cursor.execute("SELECT pet FROM rpg_characters WHERE user_id = ?", (user_id,))
    if not cursor.fetchone()[0]:
        cursor.execute("UPDATE rpg_characters SET pet = ? WHERE user_id = ?", (n, user_id))
    conn.commit()
    return True, {"이름": n, "가격": 가격}


def 펫장착(user_id, 이름):
    if 전투중(user_id):
        return False, "전투 중에는 펫을 바꿀 수 없습니다."
    if 이름 in (None, "", "해제"):
        cursor.execute("UPDATE rpg_characters SET pet = NULL WHERE user_id = ?", (user_id,))
        conn.commit()
        return True, None
    n = _펫찾기(이름, user_id)
    if n is None or not any(p["이름"] == n for p in 내펫들(user_id)):
        return False, f"'{이름}' 펫을 가지고 있지 않습니다."
    cursor.execute("UPDATE rpg_characters SET pet = ? WHERE user_id = ?", (n, user_id))
    conn.commit()
    return True, n


def 펫무기(user_id):
    cursor.execute("SELECT pet_weapon FROM rpg_characters WHERE user_id = ?", (user_id,))
    r = cursor.fetchone()
    return r[0] if r else None


def 펫무기설정(user_id, 이름):
    """펫에게 쥐어줄 무기. 이름이 비었거나 '해제'면 맨손"""
    if 전투중(user_id):
        return False, "전투 중에는 펫 무기를 바꿀 수 없습니다."
    if 이름 in (None, "", "해제", "맨손"):
        cursor.execute("UPDATE rpg_characters SET pet_weapon = NULL WHERE user_id = ?", (user_id,))
        conn.commit()
        return True, None
    종류, n = 찾기(이름)
    if 종류 != "weapon":
        return False, f"'{이름}' 은(는) 무기가 아닙니다."
    if not 보유(user_id, "weapon", n):
        return False, f"{n}을(를) 가지고 있지 않습니다."
    if 캐릭터(user_id)["weapon"] == n:
        return False, f"{n}은(는) 내가 들고 있는 무기라 펫에게 줄 수 없습니다. 다른 무기를 골라주세요."
    cursor.execute("UPDATE rpg_characters SET pet_weapon = ? WHERE user_id = ?", (n, user_id))
    conn.commit()
    return True, n


def 펫이름설정(user_id, 종류, 새이름):
    """펫 별명 짓기. 새이름이 '초기화'면 원래 이름으로"""
    n = _펫찾기(종류, user_id)
    if n == "스탠드":
        return False, "스탠드 이름은 바꿀 수 없어요."
    if n is None or not any(p["이름"] == n for p in 내펫들(user_id)):
        return False, f"'{종류}' 펫을 가지고 있지 않습니다."
    새이름 = (새이름 or "").strip()
    if 새이름 in ("", "초기화", "원래대로"):
        cursor.execute("UPDATE rpg_pets SET nickname = NULL WHERE user_id = ? AND pet = ?", (user_id, n))
        conn.commit()
        return True, {"종류": n, "이름": n}
    if not (1 <= len(새이름) <= 12):
        return False, "펫 이름은 1~12자여야 합니다."
    if any(ch in 새이름 for ch in "@#`\n\r*_~|<>"):
        return False, "펫 이름에 특수문자(@ # ` * _ ~ | < >)는 쓸 수 없습니다."
    cursor.execute("UPDATE rpg_pets SET nickname = ? WHERE user_id = ? AND pet = ?", (새이름, user_id, n))
    conn.commit()
    return True, {"종류": n, "이름": 새이름}


def 펫강화(user_id, 이름, 종류):
    """종류: 체력 / 능력"""
    if 전투중(user_id):
        return False, "전투 중에는 펫을 키울 수 없습니다."
    n = _펫찾기(이름, user_id)
    if n == "스탠드":
        return False, "스탠드는 간식을 먹지 않아요. 데리고 싸우면 전투 경험치로 자라요."
    펫정보 = next((p for p in 내펫들(user_id) if p["이름"] == n), None)
    if 펫정보 is None:
        return False, f"'{이름}' 펫을 가지고 있지 않습니다."
    종류 = {"체력": "체력", "hp": "체력", "능력": "능력", "스킬": "능력", "skill": "능력"}.get(str(종류).strip().lower())
    if 종류 is None:
        return False, "체력 또는 능력 중에 골라주세요."
    현재 = 펫정보["체력lv" if 종류 == "체력" else "능력lv"]
    if 현재 >= 펫_최대레벨:
        return False, f"{n}의 {종류}은(는) 이미 최대({펫_최대레벨})입니다."
    비용 = 10 * (현재 + 1)
    관리 = 관리자인가(user_id)
    if not 관리 and 간식(user_id) < 비용:
        return False, f"간식이 부족합니다. {종류} Lv.{현재 + 1}에 {비용:,}개 필요 (보유 {간식(user_id):,})"
    if not 관리:
        cursor.execute("UPDATE rpg_characters SET snacks = snacks - ? WHERE user_id = ?", (비용, user_id))
    컬럼 = "hp_lv" if 종류 == "체력" else "skill_lv"
    cursor.execute(f"UPDATE rpg_pets SET {컬럼} = {컬럼} + 1 WHERE user_id = ? AND pet = ?", (user_id, n))
    conn.commit()
    return True, {"이름": n, "종류": 종류, "레벨": 현재 + 1, "비용": 0 if 관리 else 비용, "간식": 간식(user_id)}


# ============================================================
# 자동 강화
# ============================================================

자동강화_안전장치 = 100_000        # 무한 반복 방지용 (실제로는 골드가 먼저 떨어진다)


def 자동강화(user_id, 이름, 목표):
    """
    목표 강화 수치까지 반복한다. 골드·재료 부족, 무기 소멸, 목표 도달, 최대 시도에서 멈춘다.
    골드·재료가 모자라거나 목표에 닿거나 무기가 부서질 때까지 계속한다.
    반환: (성공, 요약 dict 또는 오류문자열)
    """
    c = 캐릭터(user_id)
    if c is None:
        return False, "캐릭터가 없습니다."
    n = c["weapon"] if not 이름 else 찾기(이름)[1]
    if n is None or n not in 무기 or not 보유(user_id, "weapon", n):
        return False, f"'{이름}' 무기를 가지고 있지 않습니다."
    try:
        목표 = int(목표)
    except (TypeError, ValueError):
        return False, "목표 강화 수치를 숫자로 입력해주세요. (예: 20)"
    시작 = 강화수치(user_id, n)
    목표 = min(목표, 최대강화)
    if 목표 <= 시작:
        return False, f"{n}은(는) 이미 +{시작}입니다. 더 높은 목표를 정해주세요."

    요약 = {"무기": n, "시작": 시작, "목표": 목표, "시도": 0, "골드": 0, "재료": 0,
            "성공": 0, "실패": 0, "하락": 0, "파괴방지": 0, "결과": "", "이후": 시작, "새업적": []}
    for _ in range(자동강화_안전장치):
        현재 = 강화수치(user_id, n)
        if 현재 >= 목표:
            요약["결과"] = "목표 달성"
            break
        성공, r = 강화(user_id, n, 업적검사=False)
        if not 성공:
            요약["결과"] = r
            break
        요약["시도"] += 1
        요약["골드"] += r["비용"]
        요약["재료"] += 1 if r["재료"] else 0
        요약["새업적"] += r["새업적"]
        if r["결과"] in 요약:
            요약[r["결과"]] += 1
        if r["결과"] == "소멸":
            요약["결과"] = "무기가 부서졌습니다"
            요약["이후"] = None
            요약["새업적"] += 업적확인(user_id)
            return True, 요약
        if r["결과"] == "변신":
            요약["결과"] = "노키아가 신의 노키아로 다시 태어났습니다!"
            요약["무기"] = r["무기"]
            요약["이후"] = 최대강화
            return True, 요약
    else:
        요약["결과"] = "너무 많이 시도해서 멈췄습니다"
    요약["이후"] = 강화수치(user_id, n)
    요약["표시"] = 무기표시(user_id, n)
    conn.commit()
    요약["새업적"] += 업적확인(user_id)
    return True, 요약


# ============================================================
# 전투 엔진 — 디스코드와 무관한 순수 계산
# ============================================================

# ------------------------------------------------------------
# 재시작해도 전투 이어 가기
#   진행 중인 전투는 행동할 때마다 rpg_battles 에 통째로(pickle) 적는다.
#   봇·웹이 다시 켜지면 전투복원() 이 자기 것(program)을 되살린다. 끝난 전투는 지운다.
# ------------------------------------------------------------
import pickle  # noqa: E402

프로그램 = "bot"          # 웹은 import 한 뒤 "web" 으로 바꾼다 (각자 자기 전투만 복원)
전투_복원한도 = 6 * 3600   # 이보다 오래 손대지 않은 전투는 이어 가지 않고 정산만 한다

cursor.execute("""
    CREATE TABLE IF NOT EXISTS rpg_battles (
        user_id TEXT PRIMARY KEY, program TEXT, data BLOB, updated TEXT
    )""")
conn.commit()


def 전투저장(b):
    """진행 중인 전투를 DB에 적는다. 끝났거나 목록에 없는 전투는 적지 않는다."""
    if 진행중.get(b.uid) is not b or b.상태 not in ("전투", "클리어"):
        return
    try:
        자료 = pickle.dumps(b.__dict__, protocol=pickle.HIGHEST_PROTOCOL)
    except Exception as e:
        print(f"[{datetime.now()}] RPG 전투 저장 실패 {b.uid}: {e}")
        return
    cursor.execute(
        "INSERT INTO rpg_battles (user_id, program, data, updated) VALUES (?, ?, ?, ?) "
        "ON CONFLICT(user_id) DO UPDATE SET program = excluded.program, data = excluded.data, updated = excluded.updated",
        (b.uid, 프로그램, 자료, _지금()),
    )
    conn.commit()


def _전투기록삭제(user_id, 커밋=True):
    cursor.execute("DELETE FROM rpg_battles WHERE user_id = ?", (user_id,))
    if 커밋:
        conn.commit()


class _전투목록(dict):
    """user_id → 전투. 넣으면 저장하고, 빼면 저장한 것도 지운다."""
    def __setitem__(self, uid, b):
        super().__setitem__(uid, b)
        전투저장(b)

    def pop(self, uid, *기본):
        있었음 = uid in self
        값 = super().pop(uid, *기본)
        if 있었음:
            _전투기록삭제(uid)
        return 값

    def __delitem__(self, uid):
        super().__delitem__(uid)
        _전투기록삭제(uid)


진행중 = _전투목록()          # user_id → 전투


def 전투복원():
    """
    이 프로그램이 저장해 둔 전투를 되살려 진행중 에 넣는다. 한 번만 부른다.
    돌려주는 값 = 이어 가는 전투 목록. 너무 오래됐거나 못 읽는 전투는 정산(철수)하고 지운다.
    """
    cursor.execute("SELECT user_id, data, updated FROM rpg_battles WHERE program = ?", (프로그램,))
    행들 = cursor.fetchall()
    살린것 = []
    for uid, 자료, 시각 in 행들:
        if uid in 진행중:
            continue
        try:
            b = 전투.__new__(전투)
            b.__dict__.update(pickle.loads(자료))
            b.uid
        except Exception as e:
            print(f"[{datetime.now()}] RPG 전투 복원 실패 {uid}: {e} — 기록을 지운다")
            _전투기록삭제(uid)
            continue
        try:
            오래됨 = (datetime.now() - datetime.fromisoformat(시각)).total_seconds() > 전투_복원한도
        except (TypeError, ValueError):
            오래됨 = True
        b.새로그, b.새업적, b._보류 = [], [], []
        b.마지막 = datetime.now()
        dict.__setitem__(진행중, uid, b)
        _잠금(uid)
        if 오래됨 or b.상태 not in ("전투", "클리어"):
            try:
                b.철수()                      # 그동안 모은 보상은 준다
            finally:
                진행중.pop(uid, None)
                _잠금(uid, False)
            print(f"[{datetime.now()}] RPG 전투 {uid}: 오래돼서 정산만 함")
            continue
        b.기록("🔄 봇이 다시 켜져서 전투를 이어서 불러왔다")
        b.새로그 = []
        전투저장(b)
        살린것.append(b)
    if 살린것:
        print(f"[{datetime.now()}] RPG 전투 {len(살린것)}개 복원 ({프로그램})")
    return 살린것


def _프로세스살아있음(pid):
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return False


def 전투중(user_id):
    """
    이 프로그램에서 싸우는 중이거나, 다른 프로그램(봇/웹)이 전투 잠금을 걸어뒀으면 True.
    잠금을 건 프로그램이 이미 꺼졌거나(재시작 등) 오래 방치됐으면 잠금은 무시한다.
    """
    if user_id in 진행중:
        return True
    cursor.execute("SELECT battle_lock FROM rpg_characters WHERE user_id = ?", (user_id,))
    r = cursor.fetchone()
    if not r or not r[0]:
        return False
    try:
        pid_문자, 시각 = r[0].split("|", 1) if "|" in r[0] else ("", r[0])
        if (datetime.now() - datetime.fromisoformat(시각)).total_seconds() >= 전투_제한시간:
            return False
        if not pid_문자:
            return False                    # 예전 버전이 남긴 잠금 — 누가 걸었는지 몰라 무시한다
        pid = int(pid_문자)
        if pid == os.getpid():
            return False                    # 내가 건 잠금인데 진행 중인 전투가 없다 = 이미 끝난 것
        return _프로세스살아있음(pid)
    except ValueError:
        return False


def _잠금(user_id, 켜기=True):
    cursor.execute(
        "UPDATE rpg_characters SET battle_lock = ? WHERE user_id = ?",
        (f"{os.getpid()}|{_지금()}" if 켜기 else None, user_id),
    )
    conn.commit()


class 전투:
    def __init__(self, user_id, 시작층):
        self.uid = user_id
        self.층 = 시작층
        self.상태 = "전투"           # 전투 / 클리어 / 사망 / 철수
        self.로그 = []
        self.획득골드 = 0
        self.획득경험치 = 0
        self.처치수 = 0
        self.레벨업 = 0
        self.새업적 = []
        self.상인 = []               # [(아이템, 할인율)]
        self.새로그 = []             # 이번 행동에서 새로 생긴 줄 (화면에서 한 줄씩 보여준다)
        self._보류 = []              # 처치 줄은 피해 줄 다음에 나오도록 잠시 모아둔다
        self._자동 = False           # 자동 모드로 행동 중인지

        c = 캐릭터(user_id)
        s = 전투능력(c)
        self.최대체력 = s["최대체력"]
        self.펫 = None
        for p in 내펫들(user_id):
            if p["장착"]:
                최대 = 펫최대체력(p["이름"], p["체력lv"])
                self.펫 = {"이름": p["이름"], "별명": p["별명"], "hp": 최대, "최대": 최대, "능력lv": p["능력lv"], "무기": None}
                if p["이름"] == "스탠드":
                    self.펫["능력들"] = (내스탠드(user_id) or {}).get("능력들", [])
                    self.펫["스탠드쿨"] = {}
                pw = 펫무기(user_id)
                if pw and 보유(user_id, "weapon", pw) and pw != c["weapon"] and pw in 무기:
                    self.펫["무기"] = pw
        # 펫이 무기를 쓸 때의 재장전·과열 등은 주인과 따로 센다
        self._펫상태 = {"쿨": {"무기": 0, "로드롤러": 0, "과열": 0}, "마체테": 0, "미니건연속": 0, "화염충전": 3}
        self.획득간식 = 0
        if self.펫:
            self.로그.append(f"{펫[self.펫['이름']]['이모지']} {self.펫['별명']}이(가) "
                            + (f"{self.펫['무기']}을(를) 들고 따라왔다" if self.펫["무기"] else "맨손으로 따라왔다"))
        self.체력 = self.최대체력
        self.효과 = {}               # 나에게 걸린 효과 {이름: 남은 턴 또는 횟수}
        self.독중첩 = 0
        self.버틴연속 = 0
        self.쿨 = {"무기": 0, "로드롤러": 0, "과열": 0}
        self.마체테 = 0
        self.미니건연속 = 0
        self.화염충전 = 3
        self.관찰연속 = 0
        self.약점 = False
        self.적들 = []
        self.비밀 = None              # 비밀공간 종류 (레이드·특수 던전 이름도 여기 들어간다)
        self.던전 = None              # 특수 던전 진행 상황 (_특수입장 에서 채운다)
        self.악세들 = 착용악세(user_id)
        self.악세효과 = 악세효과(self.악세들)
        self.부활남음 = self.악세효과["부활"]
        self.산데 = {"남은": 0, "쿨": 0}
        self.위기쿨 = 0
        self.최대체력 = max(1, self.최대체력 + self.악세효과["체력"])
        self.체력 = self.최대체력
        self.마지막 = datetime.now()
        _잠금(user_id)
        self._층생성()
        self._층힌트()
        if self.악세들:
            self.로그.append(" · ".join(f"{악세서리[n]['이모지']} {n}" for n in self.악세들) + "을(를) 착용했다"
                            + (" — 스커프가 기묘하게 빛난다…" if self.악세효과["숨김"] else ""))
        self._에러조우검사()

    # ---------- 비밀공간 ----------
    def _비밀입장(self, 종류):
        이름, 기준층, hp배, atk배, 패턴, 부가, _ = 비밀공간[종류]
        if 종류 in 비밀공간_고정:
            hp, atk = 비밀공간_고정[종류]
        else:
            기본hp, 기본atk, _, _ = 층수치(기준층 or self.층)
            hp, atk = 기본hp * hp배, 기본atk * atk배
        self.비밀 = 종류
        self.상태 = "전투"
        self.상인 = []
        self.적들 = [self._적(이름, hp, atk, "근접", None, 보스=True, 패턴=패턴, 부가=부가)]
        문구 = {
            "-1층": "바닥이 무너지며 떨어졌다… 여긴 존재하지 않아야 할 층이다.",
            "개발자의 방": "15층… 이 아니다. 모니터 불빛만 가득한 방이다.",
            "높은곳": "창밖으로 나가 구름 위에 섰다. 누군가 날개를 펼친다.",
            "나락": "천사에게 패배하고 끝없이 떨어졌다… 뜨거운 바닥에서 눈을 떴다.",
            "엣지러너의 방": "258층의 문을 열자 네온 불빛이 쏟아진다. 척추에 박힌 장치가 빛나는 누군가가 이미 너를 보고 있다.",
            "모리오초": "문을 열자 조용한 해변 마을이 펼쳐진다. 독특한 머리 모양의 고등학생이 이쪽을 노려본다.",
            "6.5층": "7층으로 가는 계단이 끊겨 있다… 층과 층 사이, 모두에게 잊혀진 공간이다.",
            "에러조우": "▒▒▒ 공간이 일그러진다. 3rR0r404가 나타났다. 도망칠 수 없다.",
            "돼지우리": "꾸이익!!! 외침이 921층에 메아리친다… 바닥이 흔들리더니 왕관을 쓴 거대한 돼지가 솟아오른다.",
            "죠스타 저택": "1888년, 영국. 불타는 저택 한가운데 푸른 눈의 신사가 서 있다. 호흡이 햇빛처럼 빛난다.",
            "파문 수련장": "에어 서플레나 섬. 입에 링을 문 청년이 클래커를 빙글빙글 돌리며 씩 웃는다.",
            "이집트": "카이로의 밤. 학생모를 쓴 남자 뒤로 보랏빛 거인이 주먹을 쥔다. \"야레야레다제.\"",
            "베네치아": "산타 루치아 역. 금발의 소년이 무당벌레 브로치를 매만진다. \"무다\"",
            "그린 돌핀 스트리트 교도소": "철창 너머, 실로 엮인 팔을 가진 여자가 이쪽을 노려본다.",
            "케이프 커내버럴": "6개의 황금빛 정신이 공명한다… 케이프 커내버럴. 신부복을 입은 남자가 하늘을 올려다본다. \"천국에 가는 방법…\"",
        }[종류]
        self.기록(f"{비밀공간_제목[종류]} — {문구}")
        self.기록(f"{이름}이(가) 나타났다!")

    # ---------- 레이드 ----------
    def _레이드입장(self, r, 연습=False):
        """r: 레이드현재() 결과. self.층 = 도전하는 사람 최고층 (체력·공격 기준)"""
        보스 = 레이드_보스[r["boss"] % len(레이드_보스)]
        기본hp, 기본atk, _, _ = 층수치(self.층)
        self.비밀 = "레이드"
        self.상태 = "전투"
        self.상인 = []
        self.레이드 = {"주": r["week"], "단위": 기본hp, "연습": 연습, "턴": 0, "점수": 0.0, "막타": False}
        e = self._적(보스["이름"], max(1, r["hp"] * 기본hp), 기본atk * 레이드_공격배율, 보스["종류"], None,
                    보스=True, 패턴=보스["패턴"], 부가=보스["부가"])
        e["최대"] = max(e["hp"], round(r["max_hp"] * 기본hp))
        e["레이드"] = True
        e["도트기준"] = 기본hp * 6          # 출혈·화상 피해는 일반 보스 체력 기준으로
        self.적들 = [e]
        self._레이드기준 = e["hp"]
        self.로그, self.새로그 = [], []
        self.기록(f"⚔️ 레이드 — {보스['설명']}")
        self.기록(f"{보스['이름']}이(가) 나타났다! 남은 체력 {r['hp'] / r['max_hp'] * 100:.1f}%"
                  + (" · 👑 연습 모드 (기록 안 됨)" if 연습 else f" · 행동 {레이드_턴제한}번"))

    def _레이드보스(self):
        return next((e for e in self.적들 if e.get("레이드")), None)

    # ---------- 특수 던전 (일일 / 로그라이크 / 보스 러시) ----------
    def _특수입장(self, 모드, 기준층, 최고층):
        """레이드처럼 전투를 만든 직후에 불러서 특수 던전으로 바꾼다"""
        self.비밀 = 모드
        self.상태 = "전투"
        self.상인 = []
        self.로그, self.새로그 = [], []
        self.던전 = {"모드": 모드, "기준층": 기준층, "최고층": 최고층, "기간": 특수기간(모드),
                   "단계": 1, "턴": 0, "점수": 0, "완료": False}
        d = self.던전
        제목 = 특수던전_정보[모드]["제목"]
        if 모드 == "일일":
            d["규칙"], d["층들"] = 일일구성(d["기간"])
            self.층 = 기준층                 # 적 세기·부가효과의 기준. 화면에는 단계(1~10)를 보여준다
            self.기록(f"{제목} — 오늘의 규칙 **{d['규칙']['이름']}**: {d['규칙']['설명']}")
        elif 모드 == "로그라이크":
            d["강화"], d["선택지"] = {}, []
            self.층 = 1
            self.구역 = 구역키(1)
            self.펫 = None
            self.악세들 = []
            self.악세효과 = 악세효과(None)
            self.부활남음 = 0
            self.최대체력 = self.능력()["최대체력"]
            self.체력 = self.최대체력
            self.기록(f"{제목} — 장비도 레벨도 내려놓고 목검 한 자루로 시작한다.")
        else:
            self.층 = 러시층(최고층, 1)
            self.기록(f"{제목} — 보스들이 줄지어 기다린다. 쉴 틈은 없다.")
        self._특수층생성()

    def _규칙(self, 키, 기본=None):
        """일일 던전의 오늘 규칙 값. 다른 던전에서는 기본값"""
        d = self.던전
        return d["규칙"].get(키, 기본) if d and d.get("규칙") else 기본

    def 아이템불가(self, 이름):
        """특수 던전 규칙 때문에 이 아이템을 못 쓰면 이유를, 쓸 수 있으면 None 을 돌려준다"""
        if self.비밀 == "로그라이크":
            return "로그라이크 던전에서는 아이템을 쓸 수 없다"
        if self.비밀 == "보스러시" and 이름 in 회복아이템:
            return "보스 러시에서는 회복 아이템을 쓸 수 없다"
        if self._규칙("아이템금지"):
            return "오늘의 규칙: 아이템을 쓸 수 없다"
        if self._규칙("회복금지") and 이름 in 회복아이템:
            return "오늘의 규칙: 회복 아이템을 쓸 수 없다"
        return None

    def _특수층생성(self):
        d = self.던전
        if self.비밀 == "로그라이크":
            self._층생성()
            배 = (1 + 로그_적성장) ** (self.층 - 1)
            for e in self.적들:
                체, 공 = 로그_보스 if e["보스"] else (1, 1)
                e["hp"] = e["최대"] = max(1, round(e["hp"] * 배 * 체))
                e["atk"] *= 배 * 공
        elif self.비밀 == "일일":
            기본hp, 기본atk, _, _ = 층수치(self.층)
            규칙 = d["규칙"]
            self.적들 = []
            for t in d["층들"][d["단계"] - 1]:
                패턴 = list(t["패턴"])
                if 규칙.get("패턴") and 규칙["패턴"] not in 패턴:
                    패턴.append(규칙["패턴"])
                self.적들.append(self._적(
                    t["이름"], 기본hp * t["hp"] * 규칙.get("적체력", 1.0), 기본atk * t["atk"] * 규칙.get("적공격", 1.0),
                    t["종류"], t["특수"], 보스=t["보스"], 패턴=패턴, 부가=t["부가"]))
            self.기록(f"— {d['단계']}/{일일_층수}층 — 적 {len(self.적들)}명이 나타났다!")
        else:
            보스 = self._보스적(self.층)
            self.적들 = [보스]
            self.기록(f"— {d['단계']}번째 보스 ({self.층}층급) — {보스['이름']}이(가) 나타났다!")

    def _로그선택지(self):
        g = self.던전["강화"]
        후보 = [k for k, v in 로그_강화.items() if v["최대"] is None or g.get(k, 0) < v["최대"]]
        if self.체력 >= self.최대체력:
            후보.remove("회복")
        return random.sample(후보, 3)

    def 강화선택(self, 번호):
        """로그라이크: 층을 깬 뒤 강화 하나를 고르면 바로 다음 층으로 간다"""
        if self.비밀 != "로그라이크" or self.상태 != "클리어":
            return False
        선택지 = self.던전["선택지"]
        if not 0 <= 번호 < len(선택지):
            return False
        키 = 선택지[번호]
        정보 = 로그_강화[키]
        g = self.던전["강화"]
        if 키 == "회복":
            self.체력 = min(self.최대체력, self.체력 + round(self.최대체력 * 정보["수치"]))
        else:
            g[키] = g.get(키, 0) + 1
        if 키 == "체력":
            새 = self.능력()["최대체력"]
            self.체력 += 새 - self.최대체력
            self.최대체력 = 새
        self.던전["선택지"] = []
        self.새로그 = []
        self.기록(f"{정보['이모지']} **{정보['이름']}** — {정보['설명']}")
        self.다음층(_로그유지=True)
        return True

    def _로그추가타(self, e):
        """로그라이크 강화: 휩쓸기(다른 적에게 번지는 피해)와 2회 공격"""
        g = self.던전["강화"]
        s = self.능력()
        if g.get("휩쓸기"):
            for x in self.살아있는적():
                if x is not e:
                    준 = self._적에게(x, s["무기피해"] * 로그_강화["휩쓸기"]["수치"] * g["휩쓸기"], "목검", 치명가능=False)
                    self.기록(f"   🌪️ {x['이름']}에게 {준}")
                    self._보류출력()
        살아 = self.살아있는적()
        if g.get("연타") and 살아 and random.random() < 로그_강화["연타"]["수치"] * g["연타"]:
            self.기록("⚡ 한 번 더!")
            self._공격(next((i for i, x in enumerate(살아) if x is e), 0))

    def _특수클리어(self):
        d = self.던전
        if self.비밀 == "일일":
            if d["단계"] >= 일일_층수:
                d["완료"] = True
                self.기록(f"🏆 일일 던전을 {d['턴']}턴 만에 돌파했다!")
                self.상태 = "철수"
                self._정산()
                return
            self.기록(f"🏆 {d['단계']}/{일일_층수}층 클리어!")
        elif self.비밀 == "로그라이크":
            d["점수"] = self.층
            self.기록(f"🏆 {self.층}층 클리어! 강화를 하나 고르자")
            d["선택지"] = self._로그선택지()
        else:
            d["점수"] = d["단계"]
            self.기록(f"🏆 보스 {d['단계']}마리째 처치!")
        self.상태 = "클리어"
        self.상인 = []
        conn.commit()

    def _특수정산(self):
        """기록을 남기고 보상을 획득골드·획득경험치에 얹는다 (지급과 커밋은 _정산 이 한다)"""
        d = self.던전
        d["정산됨"] = True
        모드 = self.비밀
        _, _, 골드, 경험치 = 층수치(d["기준층"])
        if 모드 == "일일":
            if not d["완료"]:
                self.기록(f"📅 {d['단계']}/{일일_층수}층에서 끝났다. 끝까지 깨야 기록과 보상이 남는다.")
                return
            처음 = 특수기록(모드, d["기간"], self.uid) is None
            특수기록저장(모드, d["기간"], self.uid, d["턴"])
            if 처음:
                배 = 일일_보상 * d["규칙"].get("보상", 1.0)
                self.획득골드 += 골드 * 배
                self.획득경험치 += 경험치 * 배
                self.기록("🎁 오늘의 첫 클리어 보상을 받았다!")
            else:
                self.기록("📅 오늘 보상은 이미 받았다. 더 적은 턴이면 기록만 바뀐다.")
        elif 모드 == "로그라이크":
            if d["점수"]:
                특수기록저장(모드, d["기간"], self.uid, d["점수"])
            self.획득골드 += 골드 * 로그_층당보상 * d["점수"]
            self.획득경험치 += 경험치 * 로그_층당보상 * d["점수"]
            self.기록(f"🎲 {d['점수']}층까지 돌파했다.")
        else:
            if d["점수"]:
                특수기록저장(모드, d["기간"], self.uid, d["점수"])
            self.기록(f"👑 보스 {d['점수']}마리를 쓰러뜨렸다.")

    def _레이드반영(self):
        """이번 턴에 레이드 보스에게 준 피해를 공유 체력에 반영하고, 다른 사람이 깎은 만큼 내 화면도 맞춘다"""
        e = self._레이드보스()
        if e is None:
            return
        r = self.레이드
        피해 = max(0, self._레이드기준 - e["hp"])
        if r["연습"]:
            r["점수"] += 피해 / r["단위"]
            self._레이드기준 = e["hp"]
            return
        if 피해 <= 0:
            남음 = 레이드남은체력(r["주"])
            e["hp"] = 0 if 남음 <= 0 else min(e["hp"], max(1, round(남음 * r["단위"])))
            self._레이드기준 = e["hp"]
            return
        # 내 화면에서 보스를 쓰러뜨렸으면 반올림 오차와 상관없이 남은 체력을 전부 깎는다
        실제, 남음, 막타 = 레이드피해(r["주"], self.uid, 피해 / r["단위"], 끝까지=e["hp"] <= 0)
        r["점수"] += 실제
        r["막타"] = r["막타"] or 막타
        e["hp"] = 0 if 남음 <= 0 else max(1, round(남음 * r["단위"]))
        self._레이드기준 = e["hp"]

    def _레이드끝(self, 이유):
        """레이드 도전을 끝낸다 (이유: 처치 / 시간 / 사망 / 철수)"""
        e = self._레이드보스()
        r = self.레이드
        if 이유 == "처치":
            self.기록(f"🏆 {e['이름'] if e else '레이드 보스'}이(가) 쓰러졌다!")
            if r["막타"]:
                self.기록("🗡️ 마지막 일격을 넣었다! 보상이 정산됐다 — `!RPG 레이드` 에서 확인")
        elif 이유 == "시간":
            self.기록(f"⏰ 행동 {레이드_턴제한}번을 다 썼다. 레이드에서 물러난다.")
        self.기록(f"⚔️ 이번 도전 점수 {r['점수']:,.1f}" + (" (연습 — 기록 안 됨)" if r["연습"] else ""))
        self.레이드점수 = r["점수"]

    def _에러조우검사(self):
        if self.악세효과["에러조우"] and not self.비밀 and random.random() < 0.05:
            self._비밀입장("에러조우")

    def _재단(self):
        self.기록(f"{비밀공간_제목['재단']} — 이상한 문양이 새겨진 돌 제단이 있다.")
        가진 = {a["이름"] for a in 내악세서리(self.uid)}
        if {"개발자의 빛", "3rR0r 스커프"} <= 가진:
            cursor.execute("DELETE FROM rpg_accessories WHERE user_id = ? AND name IN ('개발자의 빛', '3rR0r 스커프')", (self.uid,))
            악세지급(self.uid, "3rR0r의 빛나는 스커프")
            self.기록("💡 + 🧣 개발자의 빛과 3rR0r 스커프가 제단 위에서 녹아 하나가 되었다…")
            self.기록("✨ **3rR0r의 빛나는 스커프**를 얻었다!")
            self.보상악세 = "3rR0r의 빛나는 스커프"
        else:
            self.기록("제단은 아무 반응이 없다. 무언가 두 개가 필요한 것 같다…")
        self.상태 = "철수"
        self._정산()

    def 외침(self, 말):
        """채팅으로 외친 말이 지금 층의 대사(외침_비밀)면 그 비밀공간으로. 들어간 방 이름, 아니면 None"""
        if self.비밀 or self.상태 not in ("전투", "클리어"):
            return None
        글 = _외침정리(말)
        방 = next((방 for 방, (층, 대사) in 외침_비밀.items() if 층 == self.층 and _외침정리(대사) in 글), None)
        if 방 is None:
            return None
        self.새로그 = []
        self.마지막 = datetime.now()
        self.기록(f"📣 \"{말.strip()[:40]}\"")
        self._비밀입장(방)
        conn.commit()
        return 방

    def _층힌트(self):
        """대사로 들어가는 비밀공간 층이면 힌트를 띄운다 (그 방 보상을 아직 다 못 가졌을 때만)"""
        if self.비밀:
            return
        가진 = None
        for 방, 문구 in 층힌트.items():
            if 외침_비밀[방][0] != self.층:
                continue
            if 가진 is None:
                가진 = {a["이름"] for a in 내악세서리(self.uid)}
            보상 = 비밀공간[방][6]
            보상 = [보상] if isinstance(보상, str) else list(보상)
            if not all(n in 가진 for n in 보상):
                self.기록(문구)
                self.기록("   💬 디스코드 아무 채널이나 웹 전투 화면의 📣 외치기 칸에 그 말을 외쳐 보자")
        if self.층 == 푸치_층 and 가진 is not None and "죠린의 황금빛 정신" in 가진:
            n = sum(1 for x in 황금빛정신 if x in 가진)
            self.기록(f"✝️ 품속의 황금빛 정신이 희미하게 떨린다… ({n}/{len(황금빛정신)}) 다 모이면 이곳에서 무언가가 일어날 것 같다")

    def _정신다모음(self):
        가진 = {a["이름"] for a in 내악세서리(self.uid)}
        return set(황금빛정신) <= 가진

    def 창밖(self):
        """50층을 깬 뒤에만 고를 수 있다"""
        if self.상태 == "클리어" and self.층 == 50 and not self.비밀:
            self.새로그 = []
            self.마지막 = datetime.now()
            self._비밀입장("높은곳")
            return True
        return False

    # ---------- 상태 ----------
    def _c(self):
        """전투에 쓰는 캐릭터. 로그라이크는 모두 같은 캐릭터로 싸운다 (이름·골드만 진짜)"""
        c = 캐릭터(self.uid)
        if self.비밀 == "로그라이크":
            return dict(로그_캐릭터, name=c["name"], gold=c["gold"])
        return c

    def 능력(self):
        c = self._c()
        s = 전투능력(c)
        p = getattr(self, "펫", None)
        if p and p["이름"] == "라이딩 호그" and p["hp"] > 0:
            s["회피"] += c["속도"] * 속도당_회피 * 호그_속도      # 속도에서 오는 회피가 1.5배
            s["무기피해"] *= 1 + 호그_공격
            s["공격력"] = round(s["공격력"] * (1 + 호그_공격))
        if self.비밀 == "로그라이크":
            g = self.던전["강화"]
            배 = 1 + 로그_강화["힘"]["수치"] * g.get("힘", 0)
            s["무기피해"] *= 배
            s["공격력"] = round(s["공격력"] * 배)
            s["최대체력"] = round(s["최대체력"] * (1 + 로그_강화["체력"]["수치"] * g.get("체력", 0)))
            s["방어력"] += 로그_강화["방어"]["수치"] * g.get("방어", 0)
            s["회피"] += 로그_강화["회피"]["수치"] * g.get("회피", 0)
            s["치명"] += 로그_강화["치명"]["수치"] * g.get("치명", 0)
        elif self._규칙("회피없음"):
            s["회피"] = 0
        s["회피"] += getattr(self, "악세효과", {}).get("회피", 0)      # 베이컨 -15%p (옛 전투엔 키가 없다)
        if getattr(self, "효과", {}).get("스탠드강화"):
            배 = getattr(self, "스탠드강화배율", 1.0)
            s["무기피해"] *= 배
            s["공격력"] = round(s["공격력"] * 배)
        return s

    def 살아있는적(self):
        return [e for e in self.적들 if e["hp"] > 0]

    def 기록(self, 줄):
        self.로그.append(줄)
        self.로그 = self.로그[-10:]
        self.새로그.append(줄)

    # ---------- 층 만들기 ----------
    def _층생성(self):
        층 = self.층
        기본hp, 기본atk, _, _ = 층수치(층)
        가능 = [t for t in 적종류 if t["층"] <= 층]
        키 = 구역키(층)
        z = 구역[키]
        환경 = z["환경"] or {}
        전용 = [t for t in 구역적 if t["구역"] == 키]
        if getattr(self, "구역", None) != 키:
            self.구역 = 키
            self.기록(f"{구역이름(층)}에 들어섰다 — {z['설명']}")
        최대 = min(적수_최대, 1 + (층 - 1) // 적수_간격)
        수 = random.randint(max(1, 최대 - 1), 최대)
        self.적들 = []
        for _ in range(수):
            t = random.choice(전용 if 전용 and random.random() < 구역_전용적확률 else 가능)
            패턴 = list(t["패턴"])
            if 환경.get("패턴추가"):
                후보 = [p for p in 공허_추가패턴 if p not in 패턴]
                if 후보 and random.random() < 0.5:
                    패턴.append(random.choice(후보))
            self.적들.append(self._적(t["이름"], 기본hp * t["hp"], 기본atk * t["atk"] * self._환경공격(t["종류"]),
                                     t["종류"], t["특수"], 패턴=패턴, 부가=t["부가"]))
        if 층 % 10 == 0:
            self.적들.insert(0, self._보스적(층))
        self.기록(f"— {층}층 — 적 {len(self.적들)}명이 나타났다!")

    def _보스적(self, 층):
        """그 층(10의 배수)의 구역 보스"""
        기본hp, 기본atk, _, _ = 층수치(층)
        종류 = random.choice(구역[구역키(층)]["보스종류"] if 층 >= 25 else ["근접"])
        보스패턴 = []
        if 층 >= 30:
            보스패턴 = random.sample(["광폭", "치유", "조준", "흡혈", "소환"], 2 if 층 >= 60 else 1)
        _, 부가후보 = 층부가(층)
        보스부가 = [(random.choice(부가후보), 0.25)] if 부가후보 else []
        return self._적(f"👑 {구역보스(층)}", 기본hp * 6, 기본atk * 2.2 * self._환경공격(종류), 종류, None, 보스=True,
                       패턴=보스패턴, 부가=보스부가)

    def _환경(self):
        """지금 적용되는 구역 환경 (비밀공간·레이드에서는 없다)"""
        if self.비밀:
            return {}
        return 구역[구역키(self.층)]["환경"] or {}

    def _환경공격(self, 종류):
        환경 = self._환경()
        return 환경.get("강화", 1.0) if 종류 in 환경.get("강화종류", ()) else 1.0

    def _환경턴(self):
        """턴이 끝날 때 구역 환경이 상태이상을 건다"""
        환경 = self._환경()
        if 환경.get("상태") and self.살아있는적() and self.체력 > 0 and random.random() < 환경["확률"]:
            self.기록(구역[구역키(self.층)]["문구"])
            self._상태부여(random.choice(환경["상태"]))

    def _적(self, 이름, hp, atk, 종류, 특수, 보스=False, 패턴=(), 부가=()):
        return {"이름": 이름, "hp": round(hp), "최대": round(hp), "atk": atk, "종류": 종류,
                "특수": 특수, "방패": bool(특수 and 특수[0] == "방패"), "효과": {}, "보스": 보스,
                "패턴": list(패턴), "부가": list(부가), "턴": 0, "조준": False, "광폭": False,
                "산데": {"남은": 0, "쿨": 0}}

    # ---------- 피해 계산 ----------
    def _적에게(self, e, 피해, 출처, 치명가능=True):
        """적에게 피해를 주고 실제 피해를 돌려준다. 죽으면 처치를 기록한다."""
        if e["hp"] <= 0:
            return 0
        if e.get("무적", 0) > 0:
            self.기록(f"🐞 {e['이름']}에게 닿은 공격이 '0'으로 되돌아갔다")
            return 0
        if 출처 is not None and e.get("산데", {}).get("남은", 0) > 0:
            self.기록(f"⏱️ {e['이름']}이(가) 느려진 시간 속에서 가볍게 피했다")
            return 0
        s = self.능력()
        치명 = 치명가능 and random.random() < s["치명"]
        if 치명:
            피해 *= 치명_배율
        if e["방패"]:
            피해 *= 0.5
        피해 = max(1, round(피해))
        if 출처 is not None and e.get("튕기기"):
            if random.random() < 0.3:
                반사 = max(1, round(피해 * 100 / (100 + s["방어력"] * (0.5 if self.효과.get("방어파괴") else 1))
                                  * self.악세효과["피해배율"]))
                self.체력 -= 반사
                self.기록(f"🐷 {e['이름']}이(가) 공격을 튕겨냈다! 튕겨 나온 공격에 {반사} 피해")
                return 0
            self.기록(f"🐷 {e['이름']}이(가) 튕겨내려 했지만 그대로 맞았다")
        e["hp"] = max(0, e["hp"] - 피해)
        if self.비밀 == "로그라이크" and 출처 is not None and self.체력 > 0 and self.던전["강화"].get("흡혈"):
            self.체력 = min(self.최대체력, self.체력 + max(1, round(피해 * 로그_강화["흡혈"]["수치"] * self.던전["강화"]["흡혈"])))
        if 치명:
            self.기록(f"💥 치명타! {e['이름']}에게 {피해}")
        if e["hp"] == 0:
            self._처치(e, 출처)
        return 피해

    def _처치(self, e, 출처):
        self.처치수 += 1
        _, _, 골드, 경험치 = 층수치(self.층)
        배율 = (5 if e["보스"] else 1) * (자동_효율 if self._자동 else 1) * 하이퍼버닝()[0]
        if self.비밀 and self.비밀 != "보스러시":
            배율 = 0                        # 비밀공간 보스는 악세서리를, 레이드·일일·로그라이크는 끝날 때 따로 보상을 준다
        self.획득골드 += 골드 * 배율
        self.획득경험치 += 경험치 * 배율
        self.획득간식 += 간식드롭(self.층) * 배율
        카운트(self.uid, "처치", 1)
        if self.펫 and self.펫["이름"] == "라이딩 호그":
            카운트(self.uid, "처치_호그장착", 1)
        if 출처:
            카운트(self.uid, f"처치_{출처}", 1)
        if 출처 in ("AK-47", "미니건"):
            카운트(self.uid, "처치_총기", 1)
        if 출처 in ("수류탄", "화염병"):
            카운트(self.uid, "처치_투척", 1)
        self._보류.append(f"☠️ {e['이름']} 처치!")

    def _보류출력(self):
        보류, self._보류 = self._보류, []
        for 줄 in 보류:
            self.기록(줄)

    # ---------- 행동 ----------
    def 행동(self, 종류, 대상=0, 아이템이름=None):
        """종류: 공격 / 아이템 / 관찰 / 휴식 / 도망"""
        if self.상태 == "클리어" and 종류 == "아이템" and 아이템이름 in 회복아이템:
            # 층을 깬 뒤에는 적이 없으니 턴 소모 없이 회복만 한다
            self.마지막 = datetime.now()
            self.새로그 = []
            쓴것 = self._아이템(아이템이름)
            conn.commit()
            return 쓴것
        if self.상태 != "전투":
            return False
        self.마지막 = datetime.now()
        self.새로그 = []
        _잠금(self.uid)
        if self.효과.get("기절"):
            self.기록("😵 기절해서 움직일 수 없다!")
            if self.던전:
                self.던전["턴"] += 1
            self._적턴()
            self._턴끝()
            conn.commit()
            if self.상태 == "전투":
                self.새업적 += 업적확인(self.uid)
            return True
        if 종류 == "공격" and self.효과.get("혼란") and random.random() < 0.5:
            종류 = "헛손질"                  # 혼란: 아래 어느 행동에도 안 걸리고 적 턴으로 넘어간다
            self.기록("🌀 혼란에 빠져 엉뚱한 곳을 휘둘렀다!")
        if 종류 != "관찰":
            self.관찰연속 = 0
        if 종류 != "공격":
            self.미니건연속 = 0

        if 종류 == "공격":
            if self.악세효과["랜덤대상"] and self.살아있는적():
                대상 = random.randrange(len(self.살아있는적()))
            맞을적 = None
            if self.비밀 == "로그라이크":
                살아 = self.살아있는적()
                맞을적 = 살아[대상] if 0 <= 대상 < len(살아) else (살아[0] if 살아 else None)
            if not self._공격(대상):
                return False               # 공격 불가 (탄약 없음 등) — 턴을 쓰지 않는다
            if 맞을적 is not None:
                self._로그추가타(맞을적)
        elif 종류 == "아이템":
            if not self._아이템(아이템이름):
                return False
        elif 종류 == "관찰":
            self.관찰연속 += 1
            카운트최대(self.uid, "관찰연속_최대", self.관찰연속)
            self.약점 = True
            self.기록(f"👁️ 적을 관찰했다. 다음 공격 피해 +25% (연속 {self.관찰연속}회)")
            for e in self.살아있는적():
                특징 = [f"{p}: {패턴설명[p]}" for p in e["패턴"]]
                특징 += [f"{n} {int(확률 * 100)}%" for n, 확률 in e["부가"]]
                if e["특수"] and e["특수"][0] in ("출혈", "화상"):
                    특징.append(f"{e['특수'][0]} {int(e['특수'][1] * 100)}%")
                if 특징:
                    self.기록(f"   · {e['이름']} — {', '.join(특징)}")
        elif 종류 == "휴식":
            회복 = 0 if self.비밀 == "보스러시" else round(self.최대체력 * 0.15)
            self.체력 = min(self.최대체력, self.체력 + 회복)
            if self.화염충전 < 3:
                self.화염충전 += 1
            if self._펫상태["화염충전"] < 3:
                self._펫상태["화염충전"] += 1
            self.기록(f"💤 숨을 골랐다. 체력 +{회복}" if 회복 else "💤 숨을 골랐다. (보스 러시에서는 체력이 돌아오지 않는다)")
        elif 종류 == "도망" and self.비밀 == "에러조우":
            self.기록("🏃 ▒▒▒ 도망칠 수 없다.")
        elif 종류 == "도망" and self.비밀 == "레이드":
            self.상태 = "철수"
            self.기록("🏃 레이드에서 물러났다.")
            self._정산()
            return True
        elif 종류 == "도망" and self.비밀 in 특수던전:
            self.상태 = "철수"
            self.기록("🏃 던전에서 물러났다.")
            self._정산()
            return True
        elif 종류 == "도망":
            성공 = random.random() < 0.6
            if 성공 and self.층 == 1 and not self.비밀:
                운 = random.random()
                if 운 < 0.01:
                    self.기록("🏃 도망치다 길을 잃었다…")
                    self._재단()
                    return True
                if 운 < 0.06:
                    self.기록("🏃 도망치다 발밑이 꺼졌다!")
                    self._비밀입장("-1층")
                    conn.commit()
                    return True
                self.상태 = "철수"
                self.기록("🏃 도망쳤다!")
                self._정산()
                return True
            if 성공:
                self.상태 = "철수"
                self.기록("🏃 도망쳤다!")
                self._정산()
                return True
            self.기록("🏃 도망치지 못했다!")

        if self.던전:
            self.던전["턴"] += 1
        self._보류출력()
        if not self.살아있는적():
            self._층클리어()
        else:
            self._적턴()
            self._턴끝()
        conn.commit()
        if self.상태 == "전투":          # 클리어·사망·철수 때는 정산에서 이미 확인한다
            self.새업적 += 업적확인(self.uid)
        return True

    def _공격(self, 대상, 무기이름=None, 기본피해=None):
        c = self._c()
        w이름 = 무기이름 or c["weapon"]
        w = 무기[w이름]
        s = self.능력()
        적 = self.살아있는적()
        대상 = 적[대상] if 0 <= 대상 < len(적) else 적[0]
        펫공격 = 기본피해 is not None

        if self.쿨["무기"] > 0:
            self.기록(f"⏳ {w이름}을(를) 아직 쓸 수 없다 ({self.쿨['무기']}턴 남음)")
            return False
        if w이름 == "미니건" and self.쿨["과열"] > 0:
            self.기록(f"🔥 미니건 과열 중 ({self.쿨['과열']}턴 남음)")
            return False
        if w이름 == "화염방사기" and self.화염충전 <= 0:
            self.기록("⛽ 화염방사기 충전이 없다. 휴식으로 충전하자")
            return False
        if w["탄약"]:
            재료, 양 = w["탄약"]
            if w이름 == "AK-47":
                양 = random.randint(1, 3)
            if not 가방사용(self.uid, 재료, 양, 커밋=False):
                if 보유(self.uid, "item", 재료) > 0 and w이름 == "AK-47":
                    양 = 보유(self.uid, "item", 재료)
                    가방사용(self.uid, 재료, 양, 커밋=False)
                else:
                    self.기록(f"❌ {재료}이(가) 부족하다 ({w['탄약'][1]}개 필요)")
                    return False
            self._발수 = 양

        피해 = 기본피해 if 펫공격 else s["무기피해"]
        if not 펫공격:
            피해 *= self.악세효과["공격배율"] * self._규칙("주는피해", 1.0)
            if self.산데["남은"] > 0:
                피해 *= 1.2
            if self.효과.get("약화"):
                피해 *= 0.75
            if self.효과.get("아드레날린"):
                피해 *= 1.5
            if self.약점:
                피해 *= 1.25
                self.약점 = False

        def 명중(e):
            return random.random() >= 기본_회피

        이름 = w이름
        if 이름 in ("나무막대기", "목검", "낡은 철검"):
            self._단일(대상, 피해, 이름, 명중)
        elif 이름 == 신의노키아:
            self.기록("📱✨ 신의 노키아가 빛난다!")
            기절 = random.random() < 0.5
            for e in 적:
                self._단일(e, 피해, 이름, lambda _: True, 효과=("구속", 1) if 기절 else None)
        elif 이름 == "호그 라이더의 망치":
            p = self.펫
            if p and p["이름"] == "라이딩 호그" and p["hp"] > 0 and not 펫공격:
                피해 *= 1.25
            if random.random() < 0.2:
                self.기록("🔨 망치를 힘껏 내려찍었다!")
                self._단일(대상, 피해 * 1.5, 이름, lambda _: True, 효과=("구속", 1))
            else:
                self._단일(대상, 피해, 이름, 명중)
        elif 이름 == "노키아 3310":
            if random.random() < 0.25:
                self.기록(f"📱 노키아 3310을 {대상['이름']}의 머리에 던졌다!")
                self._단일(대상, 피해 * 1.3, 이름, lambda _: True, 효과=("구속", 1))
            else:
                self._단일(대상, 피해, 이름, 명중)
        elif 이름 == "돌창":
            self._연속공격(대상, random.randint(1, 3), 피해, 이름, 명중)
        elif 이름 in ("기사의 검", "다이아몬드 검"):
            for e in 적[:3 if 이름 == "기사의 검" else 5]:
                self._단일(e, 피해, 이름, 명중)
        elif 이름 == "쌍도끼":
            for e in (적[:3] if random.random() < 0.25 else [대상]):
                self._단일(e, 피해, 이름, 명중)
        elif 이름 == "마체테":
            if random.random() < 0.2:
                self._단일(대상, 피해 * 1.5, 이름, 명중, 효과=("출혈", 3))
            else:
                self._단일(대상, 피해, 이름, 명중)
            self.마체테 += 1
            if self.마체테 >= 3:
                self.마체테, self.쿨["무기"] = 0, 2      # 다음 1턴 공격 불가 (턴끝에서 1 감소)
        elif 이름 == "화염방사기":
            self.화염충전 -= 1
            for e in 적:
                self._단일(e, 피해, 이름, lambda _: True, 효과=("화상", 3))
        elif 이름 == "로드롤러":
            if self.쿨["로드롤러"] == 0 and random.random() < 0.2:
                self._단일(대상, 피해 * 1.5, 이름, lambda _: True, 효과=("구속", 1))
                self.기록("🚜 로드롤러다!")
                self.쿨["로드롤러"] = 4
            else:
                self._단일(대상, 피해, 이름, 명중)
        elif 이름 == "전기톱":
            if random.random() < 0.02 and not 대상.get("레이드"):
                대상["hp"] = 0
                self._처치(대상, 이름)
                self.기록(f"🪚 {대상['이름']}을(를) 단숨에 썰었다!")
            elif random.random() < 0.25:
                for e in 적:
                    self._단일(e, 피해 * 1.5, 이름, lambda _: True, 효과=("출혈", 3))
            else:
                self._단일(대상, 피해, 이름, 명중)
        elif 이름 == "엔더막대기":
            if random.random() < max(0, s["회피"] - 0.05):
                self._단일(대상, 피해 * 2.5, 이름, lambda _: True, 효과=("혼란", 2))
                self.기록("🟣 순간이동해 뒤를 찔렀다!")
            else:
                self._단일(대상, 피해, 이름, 명중)
        elif 이름 in ("RPG-7", "ICBM"):
            for e in 적:
                self._단일(e, 피해, 이름, lambda _: True, 치명=False)
            self.쿨["무기"] = 2 if 이름 == "RPG-7" else 6
        elif 이름 == "AK-47":
            self._연속공격(대상, self._발수, 피해, 이름, 명중)
        elif 이름 == "미니건":
            # 고른 적에게 집중 사격하고, 쓰러지면 남은 적 중 다음 적을 조준해 이어서 쏜다
            맞음, 조준 = 0, 대상
            for _ in range(10):
                if 조준["hp"] <= 0:
                    살아 = self.살아있는적()
                    if not 살아:
                        break
                    조준 = 살아[0]
                if random.random() < 0.75:
                    self._적에게(조준, 피해, 이름)
                    맞음 += 1
            self.기록(f"🔫 미니건 난사! {맞음}/10발 명중")
            self.미니건연속 += 1
            if self.미니건연속 >= 3:
                self.미니건연속, self.쿨["과열"] = 0, 3
                self.기록("🔥 미니건이 과열됐다!")
        return True

    def _연속공격(self, 대상, 횟수, 피해, 출처, 명중):
        """한 적에게 여러 번 공격하다가 쓰러지면 남은 공격은 다음 적에게 이어서 한다"""
        조준 = 대상
        for _ in range(횟수):
            if 조준["hp"] <= 0:
                살아 = self.살아있는적()
                if not 살아:
                    break
                조준 = 살아[0]
            self._단일(조준, 피해, 출처, 명중)

    def _단일(self, e, 피해, 출처, 명중, 효과=None, 치명=True):
        if e["hp"] <= 0:
            return
        if not 명중(e):
            self.기록(f"💨 {e['이름']}이(가) 피했다")
            return
        준피해 = self._적에게(e, 피해, 출처, 치명가능=치명)
        if 준피해 == 0 and e.get("산데", {}).get("남은", 0) > 0:
            return                               # 산데비스탄으로 피함 — 로그는 _적에게 에서 남겼다
        if e["hp"] > 0 and 효과:
            e["효과"][효과[0]] = max(e["효과"].get(효과[0], 0), 효과[1])
        self.기록(f"⚔️ {e['이름']}에게 {준피해}" + (f" + {효과[0]}" if 효과 and e['hp'] > 0 else ""))
        self._보류출력()

    def _아이템(self, 이름):
        if not 이름 or 이름 not in 아이템 or not 아이템[이름]["전투"]:
            self.기록("❌ 전투에서 쓸 수 없는 아이템이다")
            return False
        막힘 = self.아이템불가(이름)
        if 막힘:
            self.기록(f"🚫 {막힘}")
            return False
        풀상태 = {"응급 조치": ("출혈", "화상", "독"), "붕대": ("출혈",)}.get(이름, ())
        if 이름 in 회복아이템 and self.체력 >= self.최대체력 and not any(self.효과.get(x) for x in 풀상태):
            self.기록("❤️ 체력이 이미 가득 차 있다")
            return False
        if not 가방사용(self.uid, 이름, 1, 커밋=False):
            self.기록(f"❌ {이름}이(가) 없다")
            return False
        s = self.능력()
        적 = self.살아있는적()
        if 이름 == "수류탄":
            self.기록("💣 수류탄 폭발!")
            for e in 적:
                self.기록(f"   ↳ {e['이름']}에게 {self._적에게(e, s['공격력'] * 1.5, '수류탄', 치명가능=False)}")
                self._보류출력()
        elif 이름 == "화염병":
            self.기록("🔥 화염병을 던졌다!")
            for e in 적:
                self.기록(f"   ↳ {e['이름']}에게 {self._적에게(e, s['공격력'] * 0.8, '화염병', 치명가능=False)}")
                if e["hp"] > 0:
                    e["효과"]["화상"] = 3
                self._보류출력()
        elif 이름 == "가시철조망":
            self.효과["가시철조망"] = 3
            self.기록("🪤 가시철조망을 깔았다")
        elif 이름 == "지뢰":
            self.효과["지뢰"] = 1
            self.기록("💥 지뢰를 묻었다")
        elif 이름 == "샌드비치":
            전 = self.체력
            self.체력 = min(self.최대체력, self.체력 + round(self.최대체력 * 0.3))
            self.기록(f"🥪 샌드비치를 먹었다. 체력 +{self.체력 - 전} ({전} → {self.체력})")
        elif 이름 == "연막탄":
            self.효과["연막"] = 2
            self.기록("🌫️ 연막을 펼쳤다. 회피 +40%")
        elif 이름 == "섬광탄":
            for e in 적:
                e["효과"]["구속"] = max(e["효과"].get("구속", 0), 1)
            self.기록("⚡ 섬광탄! 적들이 움직이지 못한다")
        elif 이름 == "아드레날린 부스터":
            self.체력 = max(1, self.체력 - round(self.최대체력 * 0.1))
            self.효과["아드레날린"] = 3
            카운트(self.uid, "아드레날린", 1)
            self.기록("💉 아드레날린! 3턴 동안 공격력 1.5배")
        elif 이름 == "응급 조치":
            전 = self.체력
            self.체력 = min(self.최대체력, self.체력 + round(self.최대체력 * 0.5))
            self.효과.pop("출혈", None)
            self.효과.pop("화상", None)
            self.효과.pop("독", None)
            self.독중첩 = 0
            self.기록(f"🩹 응급 조치를 했다. 체력 +{self.체력 - 전} ({전} → {self.체력}), 출혈·화상·독 해제")
        elif 이름 == "붕대":
            전 = self.체력
            self.체력 = min(self.최대체력, self.체력 + round(self.최대체력 * 0.15))
            self.효과.pop("출혈", None)
            if self.상태 == "전투":
                self.효과["재생"] = 2
            self.기록(f"🩹 붕대를 감았다. 체력 +{self.체력 - 전} ({전} → {self.체력}), 출혈 해제"
                      + (" · 2턴 재생" if self.상태 == "전투" else ""))
        elif 이름 == "설치형 방패":
            self.효과["방패"] = 2
            self.기록("🛡️ 방패를 세웠다")
        elif 이름 == "방패 브레이커":
            for e in 적:
                e["방패"] = False
            self.기록("🔨 적들의 방패를 부쉈다")
        return True

    # ---------- 적의 차례 ----------
    def _상태부여(self, 이름, 턴=None):
        if self.악세효과["면역"]:
            self.기록(f"   ↳ 💡 {이름}에 걸리지 않았다")
            return
        기본턴 = {"약화": 2, "둔화": 2, "독": 3, "방어파괴": 2, "기절": 1, "출혈": 3, "화상": 3}
        if 이름 == "독":
            self.독중첩 = min(5, self.독중첩 + 1)
        self.효과[이름] = max(self.효과.get(이름, 0), 턴 or 기본턴.get(이름, 2))
        표시 = f"독 {self.독중첩}중첩" if 이름 == "독" else 이름
        self.기록(f"   ↳ {표시}에 걸렸다 ({상태설명.get(이름, '')})")

    def _펫분담(self, 피해):
        """주인이 받을 피해 중 일부를 펫이 대신 받는다. 주인이 실제로 받을 피해를 돌려준다."""
        p = self.펫
        if not p or p["hp"] <= 0 or 피해 <= 0:
            return 피해
        몫 = min(p["hp"], round(피해 * 펫[p["이름"]]["분담"]))
        if 몫 <= 0:
            return 피해
        p["hp"] -= 몫
        self.기록(f"   {펫[p['이름']]['이모지']} {p['별명']}이(가) {몫} 대신 맞았다 ({p['hp']}/{p['최대']})")
        if p["hp"] <= 0:
            if self.악세효과["펫부활"]:
                p["hp"] = p["최대"]
                self.기록(f"   💎 {p['별명']}이(가) 쓰러졌지만 다이아몬드의 힘으로 바로 다시 일어났다!")
            else:
                p["hp"] = 0
                self.기록(f"   💔 {p['별명']}이(가) 쓰러졌다… 이번 전투에서는 더 이상 돕지 못한다")
        return 피해 - 몫

    def _내가받는피해(self, e, 배율=1.0, 방어무시=False):
        s = self.능력()
        저항 = 갑옷.get(self._c()["armor"], 갑옷["가죽옷"])["저항"]
        방어 = 0 if 방어무시 else s["방어력"] * (0.5 if self.효과.get("방어파괴") else 1)
        피해 = e["atk"] * 배율 * 100 / (100 + 방어) * (1 - 저항.get(e["종류"], 0)) * self.악세효과["피해배율"]
        피해 *= self._규칙("받는피해", 1.0)
        if self.효과.get("스탠드보호"):
            피해 *= 1 - getattr(self, "스탠드보호비율", 0)
        return max(1, round(피해 * random.uniform(0.85, 1.15)))

    def _회피확률(self, s):
        회피 = (s["회피"] + (0.4 if self.효과.get("연막") else 0) - (0.2 if self.효과.get("둔화") else 0)
                - (덫_회피감소 if self.효과.get("지뢰") or self.효과.get("가시철조망") else 0)
                - self._환경().get("회피", 0))
        if self.산데["남은"] > 0:
            회피 = 1.0                       # 산데비스탄: 느려진 시간 속에서는 전부 피한다
        return 회피

    def _피해받기(self, 피해):
        """적 공격 피해를 체력에서 뺀다 (펫 분담 뒤). 생명 주입 중 크게 맞으면 쇼크사. 실제로 받은 피해"""
        실제 = self._펫분담(피해)
        self.체력 -= 실제
        if self.효과.get("생명주입") and self.체력 > 0 and 실제 >= self.최대체력 * 생명주입_쇼크:
            self.체력 = 0
            self.기록("🐞 감각이 폭주한 몸이 고통을 견디지 못했다… 쇼크사!")
        return 실제

    # ---------- 죠스타 보스 ----------
    def _보스타격(self, e, 배율, 기술, 횟수=1, 방어무시=False, 피할수있음=True):
        """보스 기술. 방패·회피·펫분담·생명주입 쇼크를 거친다. 준 피해 합계"""
        s = self.능력()
        합, 맞음, 막음, 피함 = 0, 0, 0, 0
        for _ in range(횟수):
            if self.체력 <= 0:
                break
            if self.효과.get("방패"):
                self.효과["방패"] -= 1
                카운트(self.uid, "길막_설치형 방패", 1)
                막음 += 1
                continue
            회피 = self._회피확률(s)
            if 피할수있음 and 회피 > 0 and random.random() < 회피:
                피함 += 1
                continue
            피해 = self._내가받는피해(e, 배율, 방어무시=방어무시)
            합 += 피해
            맞음 += 1
            self._피해받기(피해)
        덧 = [f"{횟수}연타 중 {맞음}대"] if 횟수 > 1 else []
        덧 += [f"방패 {막음}"] if 막음 else []
        덧 += [f"회피 {피함}"] if 피함 else []
        self.기록(f"{기술}! " + (f"{합:,} 피해" if 맞음 else "막아냈다") + (f" ({', '.join(덧)})" if 덧 else "")
                 + (" — 방어 무시" if 방어무시 and 맞음 else ""))
        return 합

    def _기절시키기(self, 턴, 이유, 면역무시=False):
        """나를 턴만큼 못 움직이게 한다. 효과는 그 턴 끝에 한 번 줄어드니 +1 해서 넣는다"""
        if self.악세효과["면역"] and not 면역무시:
            self.기록(f"   ↳ 💡 {이유}… 하지만 몸은 멀쩡히 움직인다")
            return
        self.효과["기절"] = max(self.효과.get("기절", 0), 턴 + 1)
        self.기록(f"   ↳ ⏸️ {이유} — {턴}턴 동안 움직일 수 없다")

    def _보스패턴(self, e):
        """죠스타 보스 기술. 이번 턴 행동을 썼으면 True (일반 공격을 안 한다)"""
        p, t = e["패턴"], e["턴"]
        if "화이트스네이크" in p:
            return self._푸치(e)
        if "레퀴엠" in p and not e.get("레퀴엠") and e["hp"] <= e["최대"] * 0.5:
            e["레퀴엠"] = True
            e["무적"] = 4                    # 그 턴 끝에 한 번 줄어서 3턴
            self.기록("🐞 **골드 익스피리언스 레퀴엠!** \"너는 결코 진실에 도달할 수 없다\" — 3턴 동안 모든 공격이 '0'으로 되돌아간다")
            return True
        if "죠타로디스크" in p and not e.get("디스크") and e["hp"] <= e["최대"] * 0.5:
            e["디스크"] = True
            e["패턴"] += ["스타핑거", "더월드"]
            e["월드"] = 0
            self.기록("💿 **죠타로의 디스크!** 죠린이 아버지의 기억 디스크를 꽂았다 — 스타 플래티나의 힘이 깃든다")
            return True
        if "선라이트" in p and t % 5 in (4, 0):
            if t % 5 == 4:
                self.기록(f"{e['이름']}이(가) 호흡을 가다듬는다… 손끝에 햇빛 같은 파문이 모인다 (다음 턴 궁극기!)")
                return True
            self._보스타격(e, 3.0, "🌞 **선라이트 옐로 오버드라이브**", 방어무시=True)
            if self.체력 > 0:
                self._상태부여("화상", 4)
            return True
        if "크레커볼레" in p and t % 5 in (4, 0):
            if t % 5 == 4:
                self.기록(f"{e['이름']}이(가) 클래커를 빙빙 돌린다… 파문이 실린다 (다음 턴 궁극기!)")
                return True
            self._보스타격(e, 1.6, "🎩 **크레커 볼레**", 횟수=2)
            if self.체력 > 0:
                self._기절시키기(1, "클래커에 머리를 맞았다")
            return True
        if "더월드" in p:
            e["월드"] = e.get("월드", 0) + 1
            if e["월드"] >= 6:
                e["월드"] = 0
                self.기록("⭐ **스타 플래티나 더 월드!** 시간이 멈췄다…")
                self._기절시키기(3, "멈춘 시간 속", 면역무시=True)
                return True
            if e["월드"] == 5:
                self.기록("⭐ 스타 플래티나가 주먹을 꽉 쥔다… (다음 턴 더 월드!)")
        if "스타핑거" in p and random.random() < 0.2:
            self._보스타격(e, 1.5, "⭐ 스타 핑거")
            if self.체력 > 0:
                self._기절시키기(1, "손가락에 꿰뚫렸다")
            return True
        for 패턴, 소리 in (("오라러쉬", "👊 오라오라오라오라"), ("무다러쉬", "👊 무다무다무다무다")):
            if 패턴 in p and random.random() < 0.3:
                self._보스타격(e, 0.45, 소리, 횟수=random.randint(4, 7))
                return True
        if "실구속" in p and random.random() < 0.2:
            self._보스타격(e, 1.0, "🧵 스톤 프리")
            if self.체력 > 0:
                self._기절시키기(1, "실에 꽁꽁 묶였다")
            return True
        if "생명주입" in p and not self.효과.get("생명주입") and random.random() < 0.25:
            피해 = self._내가받는피해(e, 1.8)
            self.고통 = [피해 // 3 + (1 if i < 피해 % 3 else 0) for i in range(3)]
            self.효과["생명주입"] = 4
            self.기록(f"🐞 **생명 주입!** 감각이 폭주한다 — {피해:,} 피해가 3턴에 나뉘어 들어온다 "
                     f"(그동안 한 번에 최대체력 {생명주입_쇼크 * 100:.0f}% 넘게 맞으면 쇼크사)")
            return True
        if "다음에네놈은" in p and random.random() < 0.25:
            self.기록(f"🎩 \"다음에 네놈은 '{random.choice(죠셉_대사)}'라고 말한다!\"")
            self._상태부여("혼란", 3)
            return True
        if "파문" in p and random.random() < 0.25:
            self._보스타격(e, 1.3, "🌊 파문 공격", 방어무시=True)
            return True
        return False

    def _푸치(self, e):
        단계 = e.setdefault("단계", "화이트 스네이크")
        if 단계 == "화이트 스네이크":
            i = e.get("단어", 0)
            self.기록(f"✝️ 푸치: \"{푸치_단어[i]}\" ({i + 1}/{len(푸치_단어)})")
            e["단어"] = i + 1
            if e["단어"] >= len(푸치_단어):
                e["단계"], e["단계턴"] = "C-MOON", 0
                self.기록("🌑 14개의 단어가 모였다… 화이트 스네이크가 **C-MOON**으로 진화했다! 중력이 뒤집힌다")
                return True
            if random.random() < 0.25:
                self._보스타격(e, 1.0, "💿 화이트 스네이크")
                if self.체력 > 0:
                    self._기절시키기(1, "능력이 디스크로 뽑혔다")
                return True
            return False
        if 단계 == "C-MOON":
            e["단계턴"] += 1
            if e["단계턴"] > 5:
                e["단계"], e["가속"] = "메이드 인 헤븐", -1        # 가속은 _턴끝에서 매 턴(구속돼도) 센다
                self.기록("⏩ C-MOON이 **메이드 인 헤븐**으로 진화했다! 시간이 가속되기 시작한다… 3턴 안에 쓰러뜨리지 못하면 끝이다")
                return True
            if random.random() < 0.3:
                self._보스타격(e, 2.0, "🌑 **중력 반전**", 방어무시=True)
                if self.체력 > 0:
                    self._상태부여("혼란", 3)
            else:
                self._보스타격(e, 1.0, "🌑 뒤집힌 중력", 방어무시=True)
            return True
        self._보스타격(e, 1.0, "⏩ 가속된 시간 속 연타", 횟수=2)
        return True

    def _적턴(self):
        s = self.능력()
        층확률, 층효과 = 층부가(self.층)
        for e in list(self.살아있는적()):
            self._보류출력()
            if self.체력 <= 0:
                break
            if e["hp"] <= 0:
                continue
            e["턴"] += 1

            if e["효과"].get("구속"):
                self.기록(f"⛓️ {e['이름']}은(는) 움직이지 못한다")
                continue
            if e["효과"].get("혼란") and random.random() < 0.5:
                동료 = [x for x in self.살아있는적() if x is not e]
                if 동료:
                    피해 = max(1, round(e["atk"]))
                    x = random.choice(동료)
                    x["hp"] = max(0, x["hp"] - 피해)
                    self.기록(f"🌀 {e['이름']}이(가) 혼란에 빠져 {x['이름']}을(를) 때렸다 ({피해})")
                    if x["hp"] == 0:
                        self._처치(x, "엔더막대기")
                    continue

            # ----- 패턴 -----
            if "광폭" in e["패턴"] and not e["광폭"] and e["hp"] <= e["최대"] / 2:
                e["광폭"] = True
                e["atk"] *= 1.6
                self.기록(f"😡 {e['이름']}이(가) 광폭해졌다! (공격력 1.6배)")

            if "꿀꿀" in e["패턴"] and random.random() < 0.75:
                self.기록(f"🐷 {e['이름']}: 꿀꿀")
            if "살찌기" in e["패턴"] and random.random() < 0.20 and e["hp"] < e["최대"]:
                회복 = e["최대"] - e["hp"]
                e["hp"] = e["최대"]
                self.기록(f"🐷 {e['이름']}이(가) 살이 쪘다! 체력 +{회복:,} (가득 찼다)")

            if e["보스"] and self._보스패턴(e):
                continue

            if "자폭" in e["패턴"] and e["턴"] >= 3:
                e["hp"] = 0
                if self.효과.get("방패"):
                    self.효과["방패"] -= 1
                    카운트(self.uid, "길막_설치형 방패", 1)
                    self.기록(f"💥 {e['이름']}이(가) 자폭했지만 방패가 막았다!")
                else:
                    피해 = self._내가받는피해(e, 3.0)
                    self.기록(f"💥 {e['이름']}이(가) 자폭했다! {피해} 피해")
                    self._피해받기(피해)
                self._처치(e, None)
                continue

            if "소환" in e["패턴"] and e["턴"] % 3 == 0 and len(self.살아있는적()) < 6:
                기본hp, 기본atk, _, _ = 층수치(self.층)
                self.적들.append(self._적("해골병사", 기본hp * 1.0, 기본atk * 1.0, "근접", None, 부가=[("약화", 0.15)]))
                self.기록(f"💀 {e['이름']}이(가) 해골병사를 불러냈다!")
                continue

            if "치유" in e["패턴"] and random.random() < 0.4:
                다친 = [x for x in self.살아있는적() if x["hp"] < x["최대"]]
                if 다친:
                    x = min(다친, key=lambda y: y["hp"] / y["최대"])
                    회복 = max(1, round(x.get("도트기준", x["최대"]) * (보스_치유비율 if x["보스"] else 0.2)))
                    x["hp"] = min(x["최대"], x["hp"] + 회복)
                    self.기록(f"✨ {e['이름']}이(가) {x['이름']}을(를) {회복} 치료했다")
                    continue

            배율 = 1.0
            if "조준" in e["패턴"]:
                if not e["조준"]:
                    e["조준"] = True
                    self.기록(f"🎯 {e['이름']}이(가) 조준하고 있다… (다음 공격 2.5배)")
                    continue
                e["조준"] = False
                배율 = 2.5

            # ----- 공격 -----
            if self.효과.get("방패"):
                self.효과["방패"] -= 1
                카운트(self.uid, "길막_설치형 방패", 1)
                self.기록(f"🛡️ 방패가 {e['이름']}의 공격을 막았다")
                continue
            회피 = self._회피확률(s)
            if 회피 > 0 and random.random() < 회피:
                self.기록(f"💨 {e['이름']}의 공격을 피했다")
                continue

            피해 = self._내가받는피해(e, 배율 * (1.2 if e.get("산데", {}).get("남은", 0) > 0 else 1))
            self.기록(f"🩸 {e['이름']}에게 {피해} 피해 ({e['종류']})" + (" 🎯저격!" if 배율 > 1 else ""))
            self._피해받기(피해)
            if self.체력 > 0:
                self.버틴연속 += 1
                카운트최대(self.uid, "버티기연속_최대", self.버틴연속)
            else:
                self.버틴연속 = 0

            if "흡혈" in e["패턴"]:
                회복 = max(1, round(피해 * (보스_흡혈비율 if e["보스"] else 0.5)))
                e["hp"] = min(e["최대"], e["hp"] + 회복)
                self.기록(f"🧛 {e['이름']}이(가) {회복} 흡혈했다")

            # ----- 부가효과 -----
            if e["특수"] and e["특수"][0] in ("출혈", "화상") and random.random() < e["특수"][1]:
                self._상태부여(e["특수"][0])
            for 이름, 확률 in e["부가"]:
                if random.random() < 확률:
                    self._상태부여(이름)
            if 층효과 and random.random() < 층확률:
                self._상태부여(random.choice(층효과))

            if self.효과.get("가시철조망"):
                반사 = max(1, round(피해 * 0.4))
                self._적에게(e, 반사, "가시철조망", 치명가능=False)
                카운트(self.uid, "길막_가시철조망", 1)
                self.기록(f"🪤 가시철조망이 {반사} 돌려줬다")
            if self.효과.get("지뢰") and e["hp"] > 0:
                self.효과.pop("지뢰")
                self._적에게(e, s["공격력"] * 1.5, "지뢰", 치명가능=False)
                카운트(self.uid, "길막_지뢰", 1)
                self.기록(f"💥 {e['이름']}이(가) 지뢰를 밟았다!")

    # ---------- 턴 마무리 ----------
    def _펫공격(self):
        p = self.펫
        적 = self.살아있는적()
        if not 적 or random.random() >= self._규칙("펫확률", 펫_공격확률):
            return
        이모지 = 펫[p["이름"]]["이모지"]
        대상 = random.randrange(len(적))
        기본 = 펫공격력(p["이름"], p["능력lv"])
        w = p["무기"]
        ps = self._펫상태
        재장전 = w and (ps["쿨"]["무기"] > 0 or (w == "미니건" and ps["쿨"]["과열"] > 0)
                     or (w == "화염방사기" and ps["화염충전"] <= 0))
        if not w or 재장전:
            self.기록(f"{이모지} {p['별명']}이(가) 달려들었다!" + (f" ({w} 재장전 중)" if 재장전 else ""))
            self._단일(적[대상], 기본, None, lambda e: random.random() >= 기본_회피)
            return
        강화 = 강화수치(self.uid, w)
        피해 = (기본 + 무기[w]["atk"]) * 무기[w].get("배율", 1.0) * (1 + 강화 * 강화당_공격력)
        self.기록(f"{이모지} {p['별명']}이(가) {w}" + (f" +{강화}" if 강화 else "") + "(으)로 공격!")

        # 주인의 무기 상태를 잠시 비켜두고 펫의 상태로 공격한다
        주인상태 = {"쿨": self.쿨, "마체테": self.마체테, "미니건연속": self.미니건연속, "화염충전": self.화염충전}
        ps = self._펫상태
        self.쿨, self.마체테, self.미니건연속, self.화염충전 = ps["쿨"], ps["마체테"], ps["미니건연속"], ps["화염충전"]
        try:
            if not self._공격(대상, 무기이름=w, 기본피해=피해):
                self.미니건연속 = 0
        finally:
            ps.update(쿨=self.쿨, 마체테=self.마체테, 미니건연속=self.미니건연속, 화염충전=self.화염충전)
            self.쿨, self.마체테, self.미니건연속, self.화염충전 = (
                주인상태["쿨"], 주인상태["마체테"], 주인상태["미니건연속"], 주인상태["화염충전"])
        self._보류출력()

    def _펫행동(self):
        p = self.펫
        if not p or p["hp"] <= 0 or self.체력 <= 0:
            return
        self._펫공격()
        if self.체력 <= 0:
            return
        lv, 이모지 = p["능력lv"], 펫[p["이름"]]["이모지"]
        if p["이름"] == "강아지":
            if random.random() < 강아지_확률(lv):
                회복 = max(1, round(self.최대체력 * 강아지_회복(lv)))
                전 = self.체력
                self.체력 = min(self.최대체력, self.체력 + 회복)
                self.기록(f"{이모지} {p['별명']}이(가) 핥아줬다! 체력 +{self.체력 - 전}")
        elif p["이름"] == "고양이":
            적 = self.살아있는적()
            if 적 and random.random() < 고양이_확률:
                e = random.choice(적)
                턴 = 고양이_출혈(lv)
                준 = self._적에게(e, 고양이_피해(lv), "고양이", 치명가능=False)
                if e["hp"] > 0:
                    e["효과"]["출혈"] = max(e["효과"].get("출혈", 0), 턴)
                self.기록(f"{이모지} {p['별명']}이(가) {e['이름']}을(를) 할퀴었다! {준} 피해" + (f" + 출혈 {턴}턴" if e["hp"] > 0 else ""))
                self._보류출력()
        elif p["이름"] == "라이딩 호그":
            적 = self.살아있는적()
            if 적 and random.random() < 호그_확률:
                e = random.choice(적)
                준 = self._적에게(e, 호그_피해(lv), "라이딩 호그", 치명가능=False)
                if e["hp"] > 0:
                    e["효과"]["구속"] = max(e["효과"].get("구속", 0), 1)
                self.기록(f"{이모지} {p['별명']}이(가) {e['이름']}에게 몸통 박치기! {준} 피해" + (" + 기절" if e["hp"] > 0 else ""))
                self._보류출력()
        elif p["이름"] == "스탠드":
            self._스탠드능력()
        elif p["이름"] == "돼지":
            if p["hp"] < p["최대"] and random.random() < 0.10:
                전 = p["hp"]
                p["hp"] = min(p["최대"], p["hp"] + 돼지_회복(lv))
                self.기록(f"{이모지} {p['별명']}이(가) 밥을 먹었다. 체력 +{p['hp'] - 전}")

    def _스탠드능력(self):
        p = self.펫
        배 = 스탠드_레벨배율(p["능력lv"])
        쿨 = p.setdefault("스탠드쿨", {})
        for i, a in enumerate(p.get("능력들") or []):
            k = str(i)
            if 쿨.get(k, 0) > 0:
                쿨[k] -= 1
                continue
            조건 = a.get("조건") or {}
            if "체력이하" in 조건 and self.체력 > self.최대체력 * 조건["체력이하"]:
                continue
            적쪽 = any(효.get("종류") in ("피해", "상태") for 효 in a.get("효과", []))
            if 적쪽 and not self.살아있는적():
                continue
            if random.random() >= float(a.get("확률", 1.0)):
                continue
            쿨[k] = int(a.get("쿨", 0))
            self.기록(f"👤 {p['별명']}: 「{a['이름']}」")
            for 효 in a.get("효과", []):
                self._스탠드효과(효, 배)
            self._보류출력()
            if self.체력 <= 0:
                return

    def _스탠드효과(self, 효, 배):
        종 = 효.get("종류")
        적 = self.살아있는적()
        대상들 = 적 if 효.get("대상") == "전체" else ([random.choice(적)] if 적 else [])
        턴 = int(효.get("턴", 1))
        if 종 == "피해":
            기본 = self.능력()["무기피해"] * float(효.get("배율", 0.2)) * 배
            for e in 대상들:
                준 = self._적에게(e, 기본, "스탠드", 치명가능=bool(효.get("치명", True)))
                self.기록(f"   ↳ {e['이름']}에게 {준:,} 피해")
        elif 종 == "상태":
            이름 = 효.get("이름")
            for e in 대상들:
                if e["hp"] > 0:
                    e["효과"][이름] = max(e["효과"].get(이름, 0), 턴 + 1)     # 이 턴 끝에 한 번 준다
                    self.기록(f"   ↳ {e['이름']} {이름} {턴}턴")
        elif 종 == "회복":
            전 = self.체력
            self.체력 = min(self.최대체력, self.체력 + max(1, round(self.최대체력 * float(효.get("비율", 0.1)) * 배)))
            self.기록(f"   ↳ 체력 +{self.체력 - 전}")
        elif 종 == "방패":
            self.효과["방패"] = self.효과.get("방패", 0) + int(효.get("횟수", 1))
            self.기록(f"   ↳ 🛡️ 다음 공격 {효.get('횟수', 1)}번을 막는다")
        elif 종 == "회피":
            self.효과["연막"] = max(self.효과.get("연막", 0), 턴 + 1)
            self.기록(f"   ↳ 💨 {턴}턴 동안 회피 +40%")
        elif 종 == "해제":
            for k in ("출혈", "화상", "독", "기절", "혼란", "약화", "둔화", "방어파괴"):
                self.효과.pop(k, None)
            self.독중첩 = 0
            self.기록("   ↳ ✨ 상태이상이 모두 풀렸다")
        elif 종 == "강화":
            self.스탠드강화배율 = 1 + (float(효.get("배율", 1.3)) - 1) * 배
            self.효과["스탠드강화"] = max(self.효과.get("스탠드강화", 0), 턴 + 1)
            self.기록(f"   ↳ ⚔️ {턴}턴 동안 무기 피해 ×{self.스탠드강화배율:.2f}")
        elif 종 == "보호":
            self.스탠드보호비율 = min(0.9, float(효.get("비율", 0.2)) * 배)
            self.효과["스탠드보호"] = max(self.효과.get("스탠드보호", 0), 턴 + 1)
            self.기록(f"   ↳ 🛡️ {턴}턴 동안 받는 피해 -{self.스탠드보호비율 * 100:.0f}%")
        elif 종 == "반사":
            self.효과["가시철조망"] = max(self.효과.get("가시철조망", 0), 턴 + 1)
            self.기록(f"   ↳ 🪤 {턴}턴 동안 맞은 피해의 40%를 돌려준다")

    def _악세행동(self):
        e = self.악세효과
        if self.체력 <= 0:
            return
        if e["위기회복"]:
            if self.위기쿨 > 0:
                self.위기쿨 -= 1
            elif self.체력 <= self.최대체력 * 0.2:
                전 = self.체력
                self.체력 = min(self.최대체력, self.체력 + round(self.최대체력 * 0.5))
                self.위기쿨 = 5
                self.기록(f"💎 다이아몬드가 상처를 고쳤다! 체력 +{self.체력 - 전} (5턴 대기)")
        if e["산데"]:
            산 = self.산데
            if 산["남은"] > 0:
                산["남은"] -= 1
                if 산["남은"] == 0:
                    산["쿨"] = 3
                    self.기록("⏱️ 시간이 다시 흐르기 시작했다… (3턴 재사용 대기)")
            elif 산["쿨"] > 0:
                산["쿨"] -= 1
            elif self.살아있는적() and random.random() < 0.30:
                산["남은"] = 3
                self.기록("⏱️ 산데비스탄 가동! 3턴 동안 세상이 느려진다 (피해 +20% · 회피 100%)")
        if e.get("턴회복") and self.체력 < self.최대체력:
            전 = self.체력
            self.체력 = min(self.최대체력, self.체력 + max(1, round(self.최대체력 * e["턴회복"])))
            self.기록(f"🥓 체력 +{self.체력 - 전}")
        for 확률, 양, 이모지 in e["회복"]:
            if random.random() < 확률:
                전 = self.체력
                self.체력 = min(self.최대체력, self.체력 + 양)
                if self.체력 > 전:
                    self.기록(f"{이모지} 체력 +{self.체력 - 전}")
        if e["꼬리"] and random.random() < 0.10:
            후보 = [x for x in self.살아있는적() if not x["보스"]]
            if 후보:
                x = random.choice(후보)
                x["hp"] = 0
                self.기록(f"😈 꼬리가 {x['이름']}을(를) 꿰뚫었다!")
                self._처치(x, "악마의 꼬리")
                self._보류출력()
        if e["숨김"] and random.random() < 0.15:
            self.기록(random.choice(하트비트))

    def _적산데(self):
        for e in self.살아있는적():
            if "산데비스탄" not in e["패턴"]:
                continue
            산 = e["산데"]
            if 산["남은"] > 0:
                산["남은"] -= 1
                if 산["남은"] == 0:
                    산["쿨"] = 3
                    self.기록(f"⏱️ {e['이름']}의 시간이 다시 흐른다")
            elif 산["쿨"] > 0:
                산["쿨"] -= 1
            elif random.random() < 0.30:
                산["남은"] = 3
                self.기록(f"⏱️ {e['이름']}의 산데비스탄 가동! 3턴 동안 모든 공격을 피한다")

    def _턴끝(self):
        self._적산데()
        self._펫행동()
        self._악세행동()
        self._환경턴()
        for 이름, 비율 in (("출혈", 0.05), ("화상", 0.06)):
            if self.효과.get(이름):
                피해 = max(1, round(self.최대체력 * 비율))
                self.체력 -= 피해
                self.기록(f"{'🩸' if 이름 == '출혈' else '🔥'} {이름}으로 {피해} 피해")
        if self.효과.get("독") and self.독중첩:
            피해 = max(1, round(self.최대체력 * 0.03 * self.독중첩))
            self.체력 -= 피해
            self.기록(f"🟢 독({self.독중첩}중첩)으로 {피해} 피해")
        고통 = getattr(self, "고통", None)
        if 고통:
            피해 = 고통.pop(0)
            self.체력 -= 피해
            self.기록(f"🐞 뒤늦게 고통이 밀려온다… {피해:,} 피해")
        if self.효과.get("재생") and self.체력 > 0:
            회복 = max(1, round(self.최대체력 * 0.07))
            self.체력 = min(self.최대체력, self.체력 + 회복)
            self.기록(f"💚 재생 +{회복}")
        if self.비밀 == "로그라이크" and self.던전["강화"].get("재생") and 0 < self.체력 < self.최대체력:
            회복 = max(1, round(self.최대체력 * 로그_강화["재생"]["수치"] * self.던전["강화"]["재생"]))
            self.체력 = min(self.최대체력, self.체력 + 회복)
            self.기록(f"💚 재생 +{회복}")

        self._보류출력()
        for e in self.살아있는적():
            for 이름, 비율 in (("출혈", 0.05), ("화상", 0.06)):
                if e["효과"].get(이름):
                    self._적에게(e, e.get("도트기준", e["최대"]) * 비율 + 2, None, 치명가능=False)
                    self._보류출력()
            for k in list(e["효과"]):
                e["효과"][k] -= 1
                if e["효과"][k] <= 0:
                    del e["효과"][k]
            if e.get("단계") == "메이드 인 헤븐" and self.체력 > 0:
                e["가속"] += 1
                if e["가속"] >= 3:
                    self.기록("⏩ 시간이 끝까지 가속됐다… 우주가 한 바퀴 돌았다. 너는 이미 패배해 있었다")
                    self.부활남음 = 0
                    self.체력 = 0
                elif e["가속"] > 0:
                    self.기록(f"⏩ 시간 가속 {e['가속']}/3")
            if e.get("무적", 0) > 0:
                e["무적"] -= 1
                if e["무적"] == 0:
                    self.기록(f"🐞 레퀴엠이 멈췄다. 이제 {e['이름']}에게 공격이 닿는다")
            if "튕기기" in e["패턴"]:
                e["튕기기"] = random.random() < 0.30          # 다음 내 행동(펫 포함) 동안
                if e["튕기기"]:
                    self.기록(f"🐷 {e['이름']}이(가) 몸을 잔뜩 부풀렸다… 다음 공격을 튕겨낼 것 같다")

        for k in list(self.효과):
            if k in ("방패", "지뢰"):
                continue                     # 횟수형 — 쓰일 때만 줄어든다
            self.효과[k] -= 1
            if self.효과[k] <= 0:
                del self.효과[k]
                if k == "독":
                    self.독중첩 = 0
        for k in self.쿨:
            self.쿨[k] = max(0, self.쿨[k] - 1)
        for k in self._펫상태["쿨"]:
            self._펫상태["쿨"][k] = max(0, self._펫상태["쿨"][k] - 1)

        if self.비밀 == "레이드":
            self._레이드반영()
            self.레이드["턴"] += 1
            보스 = self._레이드보스()
            if 보스 is None or 보스["hp"] <= 0:
                for x in self.적들:          # 보스가 쓰러지면 졸개도 같이 사라진다
                    x["hp"] = 0

        if self.체력 <= 0 and self.부활남음 > 0:
            비율, 부활이모지 = self.악세효과["부활목록"][len(self.악세효과["부활목록"]) - self.부활남음]
            self.부활남음 -= 1
            self.체력 = max(1, round(self.최대체력 * 비율))
            for k in ("출혈", "화상", "독", "기절", "약화", "둔화", "방어파괴"):
                self.효과.pop(k, None)
            self.독중첩 = 0
            self.기록(f"🥓 꾸이익!! 꾸이익거리며 다시 일어났다! (남은 부활 {self.부활남음}회)" if 부활이모지 == "🥓"
                     else f"{부활이모지} 쓰러졌지만 다시 일어났다! (남은 부활 {self.부활남음}회)")
        if self.체력 <= 0 and self.비밀 == "높은곳":
            self.체력 = self.최대체력
            self.효과 = {}
            self.기록("😇 천사에게 패배했다…")
            self._비밀입장("나락")
            return
        if self.체력 <= 0:
            self.체력 = 0
            self.상태 = "사망"
            self.기록("💀 쓰러졌다...")
            self._정산()
        elif not self.살아있는적():
            self._층클리어()
        elif self.비밀 == "레이드" and self.레이드["턴"] >= 레이드_턴제한:
            self.상태 = "철수"
            self._정산()

    # ---------- 층 클리어 / 정산 ----------
    def _층클리어(self):
        if self.비밀 in 특수던전:
            self._특수클리어()
            return
        if self.비밀 == "레이드":
            self._레이드반영()
            self.상태 = "철수"
            self._정산()
            return
        if self.비밀 and self.비밀 != "에러조우":
            보상들 = 비밀공간[self.비밀][6]
            보상들 = [보상들] if isinstance(보상들, str) else list(보상들 or [])
            self.기록(f"🏆 {비밀공간[self.비밀][0]}을(를) 쓰러뜨렸다!")
            새것 = []
            for 보상 in 보상들:
                if 보상 == 스탠드디스크:
                    if 내스탠드(self.uid) or 스탠드디스크수(self.uid) > 0 or any(
                            r["종류"] == "생성" for r in 스탠드요청목록(self.uid)):
                        self.기록(f"🎁 💿 {보상}… 이미 스탠드를 가지고 있다.")
                        continue
                    카운트(self.uid, "스탠드디스크", 1)
                    self.기록(f"🎁 💿 **{보상}**을(를) 얻었다! `!RPG 스탠드` 로 나만의 스탠드를 만들 수 있다")
                    새것.append(보상)
                elif 악세지급(self.uid, 보상):
                    self.기록(f"🎁 {악세서리[보상]['이모지']} **{보상}**을(를) 얻었다!")
                    새것.append(보상)
                else:
                    self.기록(f"🎁 {보상}은(는) 이미 가지고 있다.")
            if 새것:
                self.보상악세 = " · ".join(새것)
            self.기록("던전이 끝났다.")
            self.상태 = "철수"
            self._정산()
            return
        if self.비밀 == "에러조우":
            self.기록("👾 3rR0r404가 ▒▒▒ 사라졌다. 아무것도 남지 않았다.")
            self.비밀 = None
        self.상태 = "클리어"
        self.기록(f"🏆 {self.층}층 클리어!")
        cursor.execute(
            "UPDATE rpg_characters SET best_floor = MAX(COALESCE(best_floor, 0), ?) WHERE user_id = ?",
            (self.층, self.uid),
        )
        카운트최대(self.uid, "최고층", self.층)
        self._보상지급()
        if self.층 % 10 == 0:
            후보 = [n for n, d in 아이템.items() if d["price"] > 0]
            self.상인 = [(n, random.randint(5, 20) / 100) for n in random.sample(후보, 3)]
        else:
            self.상인 = []
        conn.commit()

    def _보상지급(self):
        """이번 층까지 모은 골드·경험치를 캐릭터에 넣는다"""
        # 소수점은 버리지 않고 다음 정산으로 넘긴다 (자동 25% 때문에 생기는 1골드 미만 조각)
        골드합 = self.획득골드 + getattr(self, "_골드조각", 0)
        경험합 = self.획득경험치 + getattr(self, "_경험조각", 0)
        self.획득골드, self._골드조각 = int(골드합), 골드합 - int(골드합)
        간식합 = self.획득간식 + getattr(self, "_간식조각", 0)
        지급간식, self._간식조각 = int(간식합), 간식합 - int(간식합)
        if 지급간식 and not 관리자인가(self.uid):
            cursor.execute("UPDATE rpg_characters SET snacks = MAX(0, COALESCE(snacks, 0) + ?) WHERE user_id = ?", (지급간식, self.uid))
        self.누적간식 = getattr(self, "누적간식", 0) + 지급간식
        self.획득간식 = 0
        self.획득경험치, self._경험조각 = int(경험합), 경험합 - int(경험합)
        if self.획득골드 < 0:
            self.획득골드 = -min(-self.획득골드, 캐릭터(self.uid)["gold"])
        if self.획득골드:
            골드변경(self.uid, self.획득골드, 커밋=False)
        if self.획득경험치:
            c = 캐릭터(self.uid)
            레벨, 경험 = c["level"], max(0, c["exp"] + self.획득경험치)
            오름 = 0
            while 경험 >= 필요경험치(레벨):
                경험 -= 필요경험치(레벨)
                레벨 += 1
                오름 += 1
            cursor.execute(
                "UPDATE rpg_characters SET level = ?, exp = ?, skill_points = skill_points + ? WHERE user_id = ?",
                (레벨, 경험, 오름 * 레벨업_포인트, self.uid),
            )
            if 오름:
                self.레벨업 += 오름
                self.최대체력 = max(1, self.능력()["최대체력"] + self.악세효과["체력"])
                self.체력 = self.최대체력
                self.기록(f"⬆️ 레벨 업! Lv.{레벨} (체력 회복, 스킬포인트 +{오름 * 레벨업_포인트})")
        p = getattr(self, "펫", None)
        if self.획득경험치 > 0 and p and p["이름"] == "스탠드":
            새레벨, 스오름, 새칸 = 스탠드경험치(self.uid, self.획득경험치)
            if 스오름:
                self.기록(f"👤 {p['별명']} Lv.{새레벨}!" + (" — 새 능력을 만들 수 있다 (`!RPG 스탠드 능력`)" if 새칸 else ""))
        self.누적골드 = getattr(self, "누적골드", 0) + self.획득골드
        self.누적경험치 = getattr(self, "누적경험치", 0) + self.획득경험치
        self.획득골드 = self.획득경험치 = 0
        self.새업적 += 업적확인(self.uid)

    def 자동행동(self, 풀오토=False):
        self._자동 = True
        try:
            return self._자동한걸음(풀오토)
        finally:
            self._자동 = False

    def _자동한걸음(self, 풀오토=False):
        """
        자동 모드의 한 걸음. 반환: "행동" / "다음층" / "정지:이유" / "끝"
        - 체력 40% 미만이면 회복 아이템 (출혈이면 붕대, 위급하면 응급 조치 우선)
        - 아니면 체력이 가장 적은 적을 공격, 공격할 수 없으면 휴식
        - 층을 깨면 다음 층으로. 상인 층이거나 체력이 부족한데 회복 아이템이 없으면 멈춘다
        """
        def 회복고르기(급함):
            순서 = ["붕대"] if self.효과.get("출혈") else []
            순서 += ["응급 조치", "샌드비치", "붕대"] if 급함 else ["샌드비치", "붕대", "응급 조치"]
            if self.효과.get("독") or self.효과.get("화상"):
                순서.insert(0, "응급 조치")
            return next((n for n in 순서 if not self.아이템불가(n) and 보유(self.uid, "item", n) > 0), None)

        if self.상태 == "클리어":
            if self.비밀 == "로그라이크" and self.던전["선택지"]:
                return "정지:강화를 하나 골라주세요"
            if self.체력 < self.최대체력 * 0.6:
                템 = 회복고르기(self.체력 < self.최대체력 * 0.3)
                if 템 and self.행동("아이템", 아이템이름=템):
                    return "행동"
            if self.상인 and not 풀오토:
                return "정지:상인이 왔어요. 물건을 살지 고른 뒤 다시 자동을 켜주세요"
            if self.체력 < self.최대체력 * 0.4 and not self.아이템불가("붕대"):      # 회복이 막힌 던전은 그냥 간다
                return "정지:체력이 부족한데 회복 아이템이 없어요"
            self.다음층()
            return "다음층"

        if self.상태 != "전투":
            return "끝"

        if self.체력 < self.최대체력 * 0.4:
            템 = 회복고르기(self.체력 < self.최대체력 * 0.25)
            if 템 and self.행동("아이템", 아이템이름=템):
                return "행동"

        적 = self.살아있는적()
        대상 = min(range(len(적)), key=lambda i: 적[i]["hp"]) if 적 else 0
        if not self.행동("공격", 대상=대상):
            self.행동("휴식")
        return "행동"

    def 다음층(self, _로그유지=False):
        if self.상태 != "클리어":
            return
        특수 = self.비밀 in 특수던전
        if 특수 and self.던전.get("선택지"):
            return                           # 로그라이크: 강화를 먼저 골라야 한다 (강화선택)
        if not _로그유지:
            self.새로그 = []
        if 특수:
            self.던전["단계"] += 1
            if self.비밀 == "로그라이크":
                self.층 += 1
            elif self.비밀 == "보스러시":
                self.층 = 러시층(self.던전["최고층"], self.던전["단계"])
        else:
            self.층 += 1
        self.상태 = "전투"
        self.마지막 = datetime.now()
        _잠금(self.uid)
        self.상인 = []
        self.쿨 = {k: 0 for k in self.쿨}
        self._펫상태["쿨"] = {k: 0 for k in self._펫상태["쿨"]}
        self.효과 = {k: v for k, v in self.효과.items() if k in ("방패",)}
        self.독중첩 = 0
        self.고통 = []
        if 특수:
            self._특수층생성()
            return
        if self.층 == 999 and random.random() < 0.10:
            self._비밀입장("모리오초")
            return
        if self.층 == 258 and random.random() < 0.05:
            self._비밀입장("엣지러너의 방")
            return
        if self.층 == 7 and random.random() < 0.10:
            self._비밀입장("6.5층")
            return
        if self.층 == 15 and random.random() < 0.01:
            self._비밀입장("개발자의 방")
            return
        if self.층 == 푸치_층 and self._정신다모음():
            self._비밀입장("케이프 커내버럴")
            return
        self._층생성()
        self._층힌트()
        self._에러조우검사()

    def 철수(self):
        self.새로그 = []
        if self.상태 in ("전투", "클리어"):
            self.상태 = "철수"
            self._정산()

    def _정산(self):
        if self.비밀 == "레이드" and not hasattr(self, "레이드점수"):
            self._레이드반영()
            보스 = self._레이드보스()
            if 보스 is None or 보스["hp"] <= 0:
                이유 = "처치"
            elif self.상태 == "철수" and self.레이드["턴"] >= 레이드_턴제한:
                이유 = "시간"
            else:
                이유 = self.상태
            self._레이드끝(이유)
        if self.비밀 in 특수던전 and not self.던전.get("정산됨"):
            self._특수정산()
        self._보상지급()
        _전투기록삭제(self.uid, 커밋=False)     # 보상을 준 것과 같은 커밋에서 지운다 (두 번 받지 않게)
        conn.commit()
        진행중.pop(self.uid, None)
        _잠금(self.uid, False)

    def 방치됨(self):
        return (datetime.now() - self.마지막).total_seconds() > 전투_제한시간


def _행동후저장(함수):
    """전투 행동이 끝나면 저장한다. 행동 안에서 다른 행동을 부르면 맨 바깥에서 한 번만."""
    import functools

    @functools.wraps(함수)
    def 감싼것(self, *a, **k):
        self.__dict__["_저장깊이"] = self.__dict__.get("_저장깊이", 0) + 1
        try:
            return 함수(self, *a, **k)
        finally:
            self.__dict__["_저장깊이"] -= 1
            if self.__dict__["_저장깊이"] == 0:
                전투저장(self)
    return 감싼것


for _이름 in ("행동", "자동행동", "다음층", "강화선택", "창밖", "외침", "기록"):
    setattr(전투, _이름, _행동후저장(getattr(전투, _이름)))


# 관리자용: 비밀공간 바로 입장 (방 이름 → 들어갈 때 기준으로 삼을 층)
비밀공간_바로가기 = {
    "-1층": 1, "6.5층": 7, "모리오초": 999, "돼지우리": 돼지우리_층, "개발자의 방": 15, "높은곳": 50, "나락": 50, "엣지러너의 방": 258, "재단": 1,
    **{방: 외침_비밀[방][0] for 방 in ("죠스타 저택", "파문 수련장", "이집트", "베네치아", "그린 돌핀 스트리트 교도소")},
    "케이프 커내버럴": 푸치_층,
}


def 비밀공간바로입장(user_id, 방):
    """관리자만. 반환: (성공, 전투 또는 오류문자열)"""
    if not 관리자인가(user_id):
        return False, "관리자만 쓸 수 있어요."
    if 방 not in 비밀공간_바로가기:
        return False, f"없는 비밀공간이에요. ({' / '.join(비밀공간_바로가기)})"
    if 전투중(user_id) or 친선전진행중(user_id):
        return False, "이미 전투 중이에요. 진행 중인 전투를 마치고 오세요."
    b = 전투(user_id, 비밀공간_바로가기[방])
    진행중[user_id] = b
    b.로그 = [f"👑 관리자 권한으로 {비밀공간_제목.get(방, 방)}에 들어왔다"]
    b.새로그 = []
    if 방 == "재단":
        b._재단()
    else:
        b._비밀입장(방)
    return True, b


def 시작층(user_id):
    """최고 기록 기준 10층 단위 체크포인트에서 시작한다"""
    c = 캐릭터(user_id)
    return max(1, (c["best"] // 10) * 10 + 1) if c else 1


# ============================================================
# 레이드 — 주간 공유 체력 보스
# ============================================================

def _이번주(지금=None):
    """이번 주 월요일 날짜 (레이드 키)"""
    d = (지금 or datetime.now()).date()
    return (d - timedelta(days=d.weekday())).isoformat()


def 레이드끝시각(주):
    return datetime.fromisoformat(주) + timedelta(days=7)


def _레이드행(주):
    cursor.execute("SELECT week, boss, max_hp, hp, killed_by, killed_at, settled FROM rpg_raids WHERE week = ?", (주,))
    r = cursor.fetchone()
    if r is None:
        return None
    return {"week": r[0], "boss": r[1], "max_hp": r[2], "hp": max(0.0, r[3]), "killed_by": r[4],
            "killed_at": r[5], "settled": r[6], "ends": 레이드끝시각(r[0])}


def 레이드현재():
    """이번 주 레이드. 없으면 만든다. 지난 주 레이드가 정산 안 됐으면 먼저 정산한다."""
    주 = _이번주()
    cursor.execute("SELECT week FROM rpg_raids WHERE week < ? AND settled = 0", (주,))
    for (지난주,) in cursor.fetchall():
        레이드정산(지난주)
    r = _레이드행(주)
    if r is None:
        cursor.execute(
            "SELECT COUNT(*) FROM rpg_characters")
        인원 = cursor.fetchone()[0]
        체력 = float(max(레이드_최소체력, 인원 * 레이드_인원당체력))
        보스 = datetime.fromisoformat(주).isocalendar()[1] % len(레이드_보스)
        cursor.execute("INSERT OR IGNORE INTO rpg_raids (week, boss, max_hp, hp) VALUES (?, ?, ?, ?)",
                       (주, 보스, 체력, 체력))
        conn.commit()
        r = _레이드행(주)
    return r


def 레이드남은체력(주):
    cursor.execute("SELECT hp FROM rpg_raids WHERE week = ?", (주,))
    r = cursor.fetchone()
    return max(0.0, r[0]) if r else 0.0


def 레이드피해(주, user_id, 점수, 끝까지=False):
    """
    공유 체력을 점수만큼 깎고 내 기록에 더한다. 끝까지=True 면 남은 체력을 전부 깎는다.
    반환: (실제로 깎은 점수, 남은 체력, 내가 마지막 일격을 넣었나)
    """
    남음 = 레이드남은체력(주)
    if 주 != _이번주() or 남음 <= 0:          # 주가 바뀌었거나 이미 쓰러졌다
        return 0.0, 0.0 if 남음 <= 0 else 남음, False
    실제 = 남음 if (끝까지 or 남음 - 점수 < 0.01) else 점수
    cursor.execute("UPDATE rpg_raids SET hp = MAX(0, hp - ?) WHERE week = ? AND hp > 0", (실제, 주))
    if cursor.rowcount == 0:
        conn.rollback()
        return 0.0, 0.0, False
    cursor.execute(
        "INSERT INTO rpg_raid_damage (week, user_id, damage) VALUES (?, ?, ?) "
        "ON CONFLICT(week, user_id) DO UPDATE SET damage = damage + excluded.damage",
        (주, user_id, 실제),
    )
    막타 = False
    if 레이드남은체력(주) <= 0:
        cursor.execute("UPDATE rpg_raids SET hp = 0, killed_by = ?, killed_at = ? WHERE week = ? AND killed_by IS NULL",
                       (user_id, _지금(), 주))
        막타 = cursor.rowcount == 1
    conn.commit()
    if 막타:
        레이드정산(주)
    return 실제, 레이드남은체력(주), 막타


def 레이드정산(주):
    """보상을 나눠준다. 한 번만 된다. 반환: [(user_id, 점수, 보상골드)]"""
    cursor.execute("UPDATE rpg_raids SET settled = 1 WHERE week = ? AND settled = 0", (주,))
    if cursor.rowcount != 1:
        conn.rollback()
        return []
    r = _레이드행(주)
    처치 = r["hp"] <= 0
    cursor.execute("SELECT user_id, damage FROM rpg_raid_damage WHERE week = ? AND damage > 0 ORDER BY damage DESC", (주,))
    결과 = []
    for uid, 점수 in cursor.fetchall():
        c = 캐릭터(uid)
        if c is None:
            continue
        단가 = 층수치(max(1, c["best"]))[2]
        보상 = 단가 * (레이드_참가보상 + 점수 * (레이드_처치보상 if 처치 else 레이드_실패보상))
        if 처치 and uid == r["killed_by"]:
            보상 += 단가 * 레이드_막타보상
        보상 = round(보상)
        골드변경(uid, 보상, 커밋=False)
        cursor.execute("UPDATE rpg_raid_damage SET reward = ? WHERE week = ? AND user_id = ?", (보상, 주, uid))
        결과.append((uid, 점수, 보상))
    conn.commit()
    if 처치 and 결과:
        악세지급(결과[0][0], "정복자의 훈장")
    return 결과


def 레이드오늘도전(user_id):
    cursor.execute("SELECT n FROM rpg_raid_tries WHERE user_id = ? AND day = ?", (user_id, datetime.now().date().isoformat()))
    r = cursor.fetchone()
    return r[0] if r else 0


def 레이드순위(주, 개수=10):
    """[(순위, user_id, 이름, 점수, 보상)]"""
    cursor.execute(
        "SELECT d.user_id, COALESCE(c.name, '?'), d.damage, d.reward FROM rpg_raid_damage d "
        "LEFT JOIN rpg_characters c ON c.user_id = d.user_id WHERE d.week = ? AND d.damage > 0 "
        "ORDER BY d.damage DESC", (주,))
    전체 = [(i + 1, u, n, dmg, rw) for i, (u, n, dmg, rw) in enumerate(cursor.fetchall())]
    return 전체[:개수] if 개수 else 전체


def 레이드상태(user_id):
    """화면에 보여줄 레이드 정보 (디스코드·웹 공용)"""
    r = 레이드현재()
    보스 = 레이드_보스[r["boss"] % len(레이드_보스)]
    전체 = 레이드순위(r["week"], None)
    내 = next((x for x in 전체 if x[1] == user_id), None)
    cursor.execute("SELECT week FROM rpg_raids WHERE week < ? ORDER BY week DESC LIMIT 1", (r["week"],))
    지난 = cursor.fetchone()
    지난결과 = None
    if 지난:
        p = _레이드행(지난[0])
        지난결과 = {"boss": 레이드_보스[p["boss"] % len(레이드_보스)]["이름"], "killed": p["hp"] <= 0,
                   "top": [(n, dmg, rw) for _, _, n, dmg, rw in 레이드순위(p["week"], 3)],
                   "mine": next(((dmg, rw) for _, u, _, dmg, rw in 레이드순위(p["week"], None) if u == user_id), None)}
    킬러 = 캐릭터(r["killed_by"]) if r["killed_by"] else None
    return {
        "week": r["week"], "boss": 보스["이름"], "desc": 보스["설명"], "type": 보스["종류"],
        "patterns": 보스["패턴"], "hp": r["hp"], "max": r["max_hp"], "killed": r["hp"] <= 0,
        "killer": 킬러["name"] if 킬러 else None, "ends": r["ends"],
        "tries": 레이드오늘도전(user_id), "maxTries": 레이드_도전횟수, "turns": 레이드_턴제한,
        "practice": 레이드_관리자연습 and 관리자인가(user_id),
        "rank": [(i, n, dmg, rw) for i, _, n, dmg, rw in 전체[:10]],
        "mine": (내[0], 내[3], 내[4]) if 내 else None, "people": len(전체),
        "last": 지난결과,
    }


def 레이드입장(user_id):
    """반환: (성공, 전투 또는 오류문자열)"""
    c = 캐릭터(user_id)
    if c is None:
        return False, "캐릭터가 없어요. `!RPG 생성 [이름]` 으로 먼저 만들어주세요."
    if 전투중(user_id) or 친선전진행중(user_id):
        return False, "이미 전투 중이에요. 진행 중인 전투를 마치고 오세요."
    r = 레이드현재()
    if r["hp"] <= 0:
        return False, "이번 주 레이드 보스는 이미 쓰러졌어요. 월요일 0시에 새 보스가 나와요."
    연습 = 레이드_관리자연습 and 관리자인가(user_id)
    if not 연습:
        cursor.execute(
            "INSERT INTO rpg_raid_tries (user_id, day, n) VALUES (?, ?, 1) "
            "ON CONFLICT(user_id, day) DO UPDATE SET n = n + 1 WHERE n < ?",
            (user_id, datetime.now().date().isoformat(), 레이드_도전횟수),
        )
        if cursor.rowcount == 0:
            conn.rollback()
            return False, f"오늘 도전 {레이드_도전횟수}번을 다 썼어요. 내일 다시 도전해주세요."
        conn.commit()
    b = 전투(user_id, max(1, c["best"]))
    b._레이드입장(r, 연습)
    진행중[user_id] = b
    return True, b


# ============================================================
# 특수 던전 (일일 / 로그라이크 / 보스 러시)
# ============================================================

def 특수기간(모드, 지금=None):
    """기록이 묶이는 기간 키: 일일 = 오늘 날짜, 나머지 = 이번 주 월요일"""
    지금 = 지금 or datetime.now()
    return 지금.date().isoformat() if 특수던전_정보[모드]["기간"] == "일" else _이번주(지금)


def 특수오늘도전(user_id, 모드):
    cursor.execute("SELECT n FROM rpg_dungeon_tries WHERE user_id = ? AND mode = ? AND day = ?",
                   (user_id, 모드, datetime.now().date().isoformat()))
    r = cursor.fetchone()
    return r[0] if r else 0


def 특수기록(모드, 기간, user_id):
    cursor.execute("SELECT score FROM rpg_dungeon_records WHERE mode = ? AND period = ? AND user_id = ?", (모드, 기간, user_id))
    r = cursor.fetchone()
    return r[0] if r else None


def 특수기록저장(모드, 기간, user_id, 점수):
    """그 기간의 내 기록보다 좋을 때만 바꾼다. 커밋은 부르는 쪽(_정산)이 한다"""
    전 = 특수기록(모드, 기간, user_id)
    if 전 is not None and (점수 <= 전 if 특수던전_정보[모드]["큰점수"] else 점수 >= 전):
        return False
    cursor.execute(
        "INSERT INTO rpg_dungeon_records (mode, period, user_id, score, at) VALUES (?, ?, ?, ?, ?) "
        "ON CONFLICT(mode, period, user_id) DO UPDATE SET score = excluded.score, at = excluded.at",
        (모드, 기간, user_id, int(점수), _지금()))
    return True


def 특수순위(모드, 기간=None, 개수=10):
    """[(순위, user_id, 이름, 점수)] — 점수가 같으면 먼저 세운 사람이 위"""
    정렬 = "DESC" if 특수던전_정보[모드]["큰점수"] else "ASC"
    cursor.execute(
        "SELECT r.user_id, COALESCE(c.name, '?'), r.score FROM rpg_dungeon_records r "
        "LEFT JOIN rpg_characters c ON c.user_id = r.user_id WHERE r.mode = ? AND r.period = ? "
        f"ORDER BY r.score {정렬}, r.at ASC", (모드, 기간 or 특수기간(모드)))
    전체 = [(i + 1, u, n, 점수) for i, (u, n, 점수) in enumerate(cursor.fetchall())]
    return 전체[:개수] if 개수 else 전체


def 특수상태(user_id, 모드):
    """화면에 보여줄 특수 던전 정보 (디스코드·웹 공용)"""
    정보 = 특수던전_정보[모드]
    기간 = 특수기간(모드)
    전체 = 특수순위(모드, 기간, None)
    내 = next((x for x in 전체 if x[1] == user_id), None)
    s = {
        "mode": 모드, "title": 정보["제목"], "desc": 정보["설명"], "unit": 정보["단위"], "weekly": 정보["기간"] == "주",
        "tries": 특수오늘도전(user_id, 모드), "maxTries": 정보["횟수"],
        "rank": [(i, n, 점수) for i, _, n, 점수 in 전체[:10]],
        "mine": (내[0], 내[3]) if 내 else None, "people": len(전체),
    }
    if 모드 == "일일":
        규칙, 층들 = 일일구성(기간)
        s["rule"] = {"name": 규칙["이름"], "desc": 규칙["설명"]}
        s["boss"] = 층들[-1][0]["이름"]
        s["rewarded"] = 내 is not None
    return s


def 특수입장(user_id, 모드):
    """반환: (성공, 전투 또는 오류문자열)"""
    정보 = 특수던전_정보[모드]
    c = 캐릭터(user_id)
    if c is None:
        return False, "캐릭터가 없어요. `!RPG 생성 [이름]` 으로 먼저 만들어주세요."
    if 전투중(user_id) or 친선전진행중(user_id):
        return False, "이미 전투 중이에요. 진행 중인 전투를 마치고 오세요."
    cursor.execute(
        "INSERT INTO rpg_dungeon_tries (user_id, mode, day, n) VALUES (?, ?, ?, 1) "
        "ON CONFLICT(user_id, mode, day) DO UPDATE SET n = n + 1 WHERE n < ?",
        (user_id, 모드, datetime.now().date().isoformat(), 정보["횟수"]),
    )
    if cursor.rowcount == 0:
        conn.rollback()
        return False, f"오늘 {정보['제목']} 도전 {정보['횟수']}번을 다 썼어요. 내일 다시 도전해주세요."
    conn.commit()
    기준층 = max(1, int(c["best"] * 일일_기준층))
    시작 = {"일일": 기준층, "로그라이크": 1, "보스러시": 러시층(c["best"], 1)}[모드]
    b = 전투(user_id, 시작)
    b._특수입장(모드, 기준층, c["best"])
    진행중[user_id] = b
    return True, b


def 특수제목(b):
    """전투 화면 제목 (디스코드·웹 공용)"""
    d = b.던전
    if b.비밀 == "일일":
        return f"📅 일일 던전 {d['단계']}/{일일_층수}층 · {d['턴']}턴 · 규칙: {d['규칙']['이름']}"
    if b.비밀 == "로그라이크":
        return f"🎲 로그라이크 던전 {b.층}층"
    return f"👑 보스 러시 {d['단계']}번째 보스 · {b.층}층급"


def 강화문구(b):
    """로그라이크에서 지금까지 고른 강화"""
    return " ".join(f"{로그_강화[k]['이모지']}×{n}" for k, n in b.던전["강화"].items())


def 특수결과문구(b):
    if b.비밀 not in 특수던전:
        return ""
    d = b.던전
    if b.비밀 == "일일":
        return "📅 일일 던전 " + (f"클리어 — {d['턴']}턴" if d["완료"] else f"실패 ({d['단계']}/{일일_층수}층)")
    if b.비밀 == "로그라이크":
        return f"🎲 로그라이크 {d['점수']}층 돌파"
    return f"👑 보스 {d['점수']}마리 처치"


# ============================================================
# 친선전 — 유저끼리 1:1. 전투력 차이만큼 약한 쪽은 버프, 강한 쪽은 너프
# ============================================================

친선전_체력배율 = 8          # 한 방에 끝나지 않게 체력을 늘린다
친선전_모드 = "체력"          # "체력": 공격력은 그대로, 보정은 전부 체력으로 (약하면 체력↑, 강하면 체력↓)
                              # "공격체력": 공격과 체력을 같은 비율로 보정
친선전_보정강도 = 0.95       # 격차를 얼마나 메울지 (0 = 보정 없음, 1 = 완전히 같게). 로그 비율 기준
친선전_최대턴 = 60
친선전_목표타수 = 8          # 보정 후 평균 8대쯤 맞아야 쓰러지도록 양쪽 체력을 같은 배율로 맞춘다
친선전_한방상한 = 0.4        # 한 번에 상대 최대 체력의 40%까지만 (치명타 포함)
친선전_신청유효초 = 180      # 신청은 3분 안에 수락해야 한다 (DM 보고 올 시간)
친선전_턴제한초 = 90         # 차례에서 90초 동안 아무것도 안 하면 기권
웹_RPG_주소 = "https://example.com/stock/rpg"

cursor.execute("""
    CREATE TABLE IF NOT EXISTS rpg_duels (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        a TEXT, b TEXT, status TEXT, data TEXT,
        created TEXT, updated TEXT, turn_at TEXT,
        msgs TEXT DEFAULT '[]', notified INTEGER DEFAULT 0, rendered TEXT
    )
""")
conn.commit()


def 친선전능력(user_id):
    """친선전에서 쓰는 수치와 전투력"""
    c = 캐릭터(user_id)
    s = 전투능력(c)
    악세 = None                                  # 친선전에서는 악세서리를 쓰지 않는다
    e = 악세효과(None)
    최대 = max(1, (s["최대체력"] + e["체력"]) * 친선전_체력배율)
    피해 = s["무기피해"] * e["공격배율"]
    회피 = s["회피"]
    받는배율 = e["피해배율"]
    한턴 = 피해 * (1 + s["치명"] * (치명_배율 - 1)) * (1 - 기본_회피)
    버팀 = 최대 * (100 + s["방어력"]) / 100 / max(0.05, 1 - max(0.0, 회피)) / max(0.05, 받는배율)
    return {
        "uid": user_id, "이름": c["name"], "무기": 무기표시(user_id, c["weapon"]), "강화": s["강화"], "악세": 악세,
        "최대": 최대, "hp": 최대, "피해": 피해, "방어": s["방어력"], "회피": 회피, "치명": s["치명"],
        "받는배율": 받는배율, "관찰": False, "휴식연속": 0,
        "전투력": round(math.sqrt(한턴 * 버팀)),
    }


class 친선전:
    def __init__(self, 도전자=None, 상대=None, 저장=None):
        if 저장 is not None:                 # DB 에서 불러오기
            self.__dict__.update(저장)
            self.승자 = self.p[저장["승자idx"]] if 저장.get("승자idx") is not None else None
            return
        self.p = [친선전능력(도전자), 친선전능력(상대)]
        a, b = self.p
        # 1:1 승부는 (피해 × 체력)으로 정해진다. 전투력 = √(피해 × 체력) 이므로
        # 양쪽의 (피해 × 체력) = 전투력² 을 맞추고, 센 쪽에 작은 우위만 남긴다.
        ca, cb = max(1, a["전투력"]), max(1, b["전투력"])
        원래 = (ca / cb) ** 2                                    # 보정 전 a/b 의 (피해×체력) 비율
        목표 = 원래 ** (1 - 친선전_보정강도)                     # 격차의 일부만 남긴다
        k = (목표 * cb * cb / (ca * ca)) ** 0.25               # a 의 피해·체력에 곱할 배율 (b 는 1/k)
        for x, k in ((a, k), (b, 1 / k)):
            if 친선전_모드 == "체력":
                # (피해 × 체력)을 맞추는 배율 k² 를 전부 체력에 싣는다. 공격력은 원래 그대로
                x["보정"] = k * k
                x["최대"] = max(1.0, x["최대"] * k * k)
            else:
                x["보정"] = k
                x["피해"] *= k
                x["최대"] = max(1.0, x["최대"] * k)
        # 체력 스케일: 피해에 비해 체력이 너무 작으면 한 방에 끝나므로, 양쪽 체력에 같은 배율을 곱해
        # 평균 목표 타수만큼 버티게 한다 (같은 배율이라 유불리는 그대로)
        def 타수(공, 방):
            한방 = 공["피해"] * (1 + 공["치명"] * (치명_배율 - 1)) * 100 / (100 + 방["방어"]) * 방["받는배율"]
            return 방["최대"] / max(1e-9, 한방)
        평균타수 = math.sqrt(타수(a, b) * 타수(b, a))
        배율 = 친선전_목표타수 / max(1e-9, 평균타수)
        for x in (a, b):
            x["최대"] = x["hp"] = max(1, round(x["최대"] * 배율))
        # 속도(회피)가 높은 쪽이 먼저, 같으면 도전자
        self.차례 = 0 if a["회피"] >= b["회피"] else 1
        self.턴 = 0
        self.로그 = [f"⚔️ {a['이름']} vs {b['이름']} 친선전 시작!",
                    f"{self.p[self.차례]['이름']}의 선공 (속도가 더 빠름)" if a["회피"] != b["회피"] else f"{a['이름']}의 선공"]
        self.승자 = None
        self.끝 = False

    def 저장값(self):
        return {"p": self.p, "차례": self.차례, "턴": self.턴, "로그": self.로그, "끝": self.끝,
                "승자idx": None if self.승자 is None else self.p.index(self.승자)}

    def 기록(self, 줄):
        self.로그 = (self.로그 + [줄])[-12:]

    def 지금(self):
        return self.p[self.차례]

    def 행동(self, uid, 종류):
        if self.끝 or self.지금()["uid"] != uid:
            return False
        나, 상대 = self.p[self.차례], self.p[1 - self.차례]
        if 종류 == "항복":
            self.기록(f"🏳️ {나['이름']}이(가) 항복했다")
            self._종료(상대)
            return True
        if 종류 == "관찰":
            나["관찰"] = True
            self.기록(f"👁️ {나['이름']}이(가) 빈틈을 노린다 (다음 공격 +25%)")
        elif 종류 == "휴식":
            if 나["휴식연속"] >= 2:
                self.기록(f"💤 {나['이름']}은(는) 연속으로 더 쉴 수 없다")
                return False
            회복 = round(나["최대"] * 0.10)
            나["hp"] = min(나["최대"], 나["hp"] + 회복)
            self.기록(f"💤 {나['이름']}이(가) 숨을 골랐다 (+{회복})")
        else:
            회피 = 상대["회피"]
            if 회피 > 0 and random.random() < 회피:
                self.기록(f"💨 {상대['이름']}이(가) 피했다!")
            else:
                피해 = 나["피해"] * (1.25 if 나["관찰"] else 1)
                치명 = random.random() < 나["치명"]
                if 치명:
                    피해 *= 치명_배율
                피해 = 피해 * 100 / (100 + 상대["방어"]) * 상대["받는배율"] * random.uniform(0.9, 1.1)
                피해 = max(1, min(round(피해), round(상대["최대"] * 친선전_한방상한)))
                상대["hp"] = max(0, 상대["hp"] - 피해)
                self.기록(f"{'💥 치명타! ' if 치명 else '⚔️ '}{나['이름']} → {상대['이름']} {피해:,}")
            나["관찰"] = False
        나["휴식연속"] = 나["휴식연속"] + 1 if 종류 == "휴식" else 0

        if 상대["hp"] <= 0:
            self.기록(f"🏆 {나['이름']}의 승리!")
            self._종료(나)
            return True
        self.턴 += 1
        if self.턴 >= 친선전_최대턴:
            a, b = self.p
            비 = (a["hp"] / a["최대"], b["hp"] / b["최대"])
            self.기록(f"⏱️ {친선전_최대턴}턴이 지났다. 남은 체력 비율로 판정")
            self._종료(a if 비[0] > 비[1] else b if 비[1] > 비[0] else None)
            return True
        self.차례 = 1 - self.차례
        return True

    def _종료(self, 승자):
        self.끝 = True
        self.승자 = 승자
        for x in self.p:
            if 승자 is None:
                카운트(x["uid"], "친선전_무", 1)
            else:
                카운트(x["uid"], "친선전_승" if x is 승자 else "친선전_패", 1)
        conn.commit()


def _결투(duel_id):
    cursor.execute("SELECT id, a, b, status, data, created, updated, turn_at, msgs, notified, rendered FROM rpg_duels WHERE id = ?", (duel_id,))
    r = cursor.fetchone()
    if r is None:
        return None
    키 = ("id", "a", "b", "status", "data", "created", "updated", "turn_at", "msgs", "notified", "rendered")
    d = dict(zip(키, r))
    d["msgs"] = json.loads(d["msgs"] or "[]")
    d["game"] = 친선전(저장=json.loads(d["data"])) if d["data"] else None
    return d


def _결투저장(d, 상태=None, 턴시작=False):
    지금 = datetime.now().isoformat()
    cursor.execute(
        "UPDATE rpg_duels SET status = ?, data = ?, updated = ?, turn_at = COALESCE(?, turn_at) WHERE id = ?",
        (상태 or d["status"], json.dumps(d["game"].저장값(), ensure_ascii=False) if d["game"] else None,
         지금, 지금 if 턴시작 else None, d["id"]),
    )
    conn.commit()


def _결투시간처리(d):
    """신청 만료, 차례 시간 초과를 반영한다"""
    if d is None:
        return None
    지금 = datetime.now()
    if d["status"] == "pending" and (지금 - datetime.fromisoformat(d["created"])).total_seconds() > 친선전_신청유효초:
        _결투저장(d, "expired")
        return _결투(d["id"])
    if d["status"] == "active" and d["game"] and not d["game"].끝:
        if (지금 - datetime.fromisoformat(d["turn_at"])).total_seconds() > 친선전_턴제한초:
            g = d["game"]
            g.기록(f"⏰ {g.지금()['이름']}이(가) 시간 안에 행동하지 않아 기권했다")
            g._종료(g.p[1 - g.차례])
            _결투저장(d, "done")
            return _결투(d["id"])
    return d


def 친선전찾기(duel_id):
    return _결투시간처리(_결투(duel_id))


def 친선전진행중(user_id):
    """지금 싸우고 있는 친선전 id (없으면 None)"""
    cursor.execute("SELECT id FROM rpg_duels WHERE status = 'active' AND (a = ? OR b = ?) ORDER BY id DESC", (user_id, user_id))
    for (i,) in cursor.fetchall():
        d = 친선전찾기(i)
        if d and d["status"] == "active":
            return i
    return None


def 친선전신청(도전자, 상대):
    if 도전자 == 상대:
        return False, "자기 자신에게는 신청할 수 없어요."
    for uid in (도전자, 상대):
        if 캐릭터(uid) is None:
            return False, ("아직 캐릭터가 없어요." if uid == 도전자 else "상대가 아직 캐릭터가 없어요.")
        if 전투중(uid) or 친선전진행중(uid):
            return False, ("지금 전투 중이에요." if uid == 도전자 else f"{캐릭터(uid)['name']}님이 지금 전투 중이에요.")
    cursor.execute("SELECT id FROM rpg_duels WHERE status = 'pending' AND a = ? AND b = ?", (도전자, 상대))
    for (i,) in cursor.fetchall():
        if 친선전찾기(i)["status"] == "pending":
            return False, "이미 이 상대에게 보낸 신청이 있어요."
    지금 = datetime.now().isoformat()
    cursor.execute("INSERT INTO rpg_duels (a, b, status, created, updated) VALUES (?, ?, 'pending', ?, ?)", (도전자, 상대, 지금, 지금))
    conn.commit()
    return True, cursor.lastrowid


def 친선전수락(duel_id, uid):
    d = 친선전찾기(duel_id)
    if d is None or d["status"] != "pending":
        return False, "이미 끝났거나 만료된 신청이에요."
    if uid != d["b"]:
        return False, "신청받은 사람만 수락할 수 있어요."
    for x in (d["a"], d["b"]):
        if 전투중(x) or 친선전진행중(x):
            return False, f"{캐릭터(x)['name']}님이 지금 전투 중이라 시작할 수 없어요."
    d["game"] = 친선전(d["a"], d["b"])
    _결투저장(d, "active", 턴시작=True)
    return True, duel_id


def 친선전거절(duel_id, uid):
    d = 친선전찾기(duel_id)
    if d is None or d["status"] != "pending":
        return False, "이미 끝났거나 만료된 신청이에요."
    if uid not in (d["a"], d["b"]):
        return False, "관련 없는 신청이에요."
    _결투저장(d, "declined" if uid == d["b"] else "canceled")
    return True, duel_id


def 친선전행동(duel_id, uid, 종류):
    cursor.execute("BEGIN IMMEDIATE")          # 봇과 웹이 동시에 누르지 못하게
    try:
        d = 친선전찾기(duel_id)
        if d is None or d["status"] != "active":
            conn.rollback()
            return False, "진행 중인 친선전이 아니에요."
        g = d["game"]
        if g.지금()["uid"] != uid:
            conn.rollback()
            return False, f"지금은 {g.지금()['이름']}의 차례예요."
        if not g.행동(uid, 종류):
            conn.rollback()
            return False, "지금은 그 행동을 할 수 없어요."
        _결투저장(d, "done" if g.끝 else "active", 턴시작=True)
    except Exception:
        conn.rollback()
        raise
    return True, duel_id


def 친선전메시지추가(duel_id, channel_id, message_id):
    d = _결투(duel_id)
    if d is None:
        return
    d["msgs"].append([str(channel_id), str(message_id)])
    cursor.execute("UPDATE rpg_duels SET msgs = ? WHERE id = ?", (json.dumps(d["msgs"]), duel_id))
    conn.commit()


def 내친선전(uid):
    """웹 화면용: 받은 신청, 보낸 신청, 진행 중인 대결"""
    cursor.execute("SELECT id FROM rpg_duels WHERE status IN ('pending', 'active') AND (a = ? OR b = ?)", (uid, uid))
    받음, 보냄, 진행 = [], [], None
    for (i,) in cursor.fetchall():
        d = 친선전찾기(i)
        if d["status"] == "pending":
            남은 = 친선전_신청유효초 - (datetime.now() - datetime.fromisoformat(d["created"])).total_seconds()
            상대 = d["a"] if d["b"] == uid else d["b"]
            항목 = {"id": i, "name": 캐릭터(상대)["name"], "left": max(0, int(남은))}
            (받음 if d["b"] == uid else 보냄).append(항목)
        elif d["status"] == "active":
            진행 = i
    return {"incoming": 받음, "outgoing": 보냄, "active": 진행}


def 랭킹(개수=10):
    """[(순위, user_id, 이름, 최고층, 레벨)] — 관리자 포함. 최고층 → 레벨 → 경험치 순"""
    cursor.execute(
        "SELECT user_id, name, COALESCE(best_floor, 0), level FROM rpg_characters "
        "ORDER BY COALESCE(best_floor, 0) DESC, level DESC, exp DESC"
    )
    전체 = [(i + 1, u, n, f, lv) for i, (u, n, f, lv) in enumerate(cursor.fetchall())]
    return 전체[:개수] if 개수 else 전체


def 이름으로찾기(이름):
    cursor.execute("SELECT user_id FROM rpg_characters WHERE LOWER(name) = LOWER(?)", (str(이름).strip(),))
    r = cursor.fetchone()
    return r[0] if r else None


