# 디스코드 화면 — 공통
# ============================================================

def 막대(현재, 최대, 칸=10):
    if 최대 <= 0:
        return "░" * 칸
    찬 = max(0, min(칸, round(칸 * 현재 / 최대)))
    return "█" * 찬 + "░" * (칸 - 찬)


def 캐릭터카드(c, 주인, 제목=None):
    s = 전투능력(c)
    관리 = 관리자인가(c["_uid"])
    embed = discord.Embed(
        title=제목 or f"⚔️ {c['name']}",
        description=(
            (f"👑 관리자 · Lv.∞ · 최고 {c['best']}층\n" if 관리 else
             f"Lv.{c['level']} · 경험치 {c['exp']:,}/{필요경험치(c['level']):,} · 최고 {c['best']}층\n")
            + f"🗡️ {무기표시(c['_uid'], c['weapon'])}" + (f" +{s['강화']}" if s["강화"] else "") + f" · 🛡️ {c['armor']}"
        ),
        color=0x8E5CF6,
    )
    효과 = {
        "힘": f"공격력 {s['공격력']} (무기 포함 {s['무기피해']:.0f})",
        "체력": f"체력 {s['최대체력']}",
        "속도": f"회피 {s['회피'] * 100:.0f}%",
        "지능": f"치명타 {s['치명'] * 100:.0f}%",
    }
    for 키, (한글, 이모지, _) in 능력치.items():
        최대표시 = " (MAX)" if c[키] >= 능력치_최대 else ""
        embed.add_field(name=f"{이모지} {한글} {c[키]}/{능력치_최대}{최대표시}", value=효과[키], inline=True)
    embed.add_field(name="🪙 골드", value=f"**{c['gold']:,}**", inline=True)
    착용 = 착용악세(c["_uid"])
    if 착용:
        embed.add_field(name=f"💍 악세서리 ({len(착용)}/{악세_최대})",
                        value="\n".join(f"{악세서리[n]['이모지']} {n}" for n in 착용), inline=True)
    embed.add_field(
        name="✨ 스킬포인트",
        value=f"**{c['points']}**" + (" · 아래 버튼으로 올려보세요" if c["points"] else ""),
        inline=False,
    )
    embed.set_footer(text=f"{주인.display_name}의 캐릭터")
    return embed


class 스탯버튼(discord.ui.View):
    def __init__(self, 주인):
        super().__init__(timeout=180)
        self.주인 = 주인
        효과 = {"힘": f"공격 +{힘당_공격력}", "체력": f"체력 +{체력당_체력}",
                "속도": f"회피 +{속도당_회피 * 100:.0f}%", "지능": f"치명 +{지능당_치명 * 100:.0f}%"}
        for 키, (한글, 이모지, _) in 능력치.items():
            버튼 = discord.ui.Button(label=f"{한글} ({효과[키]})", emoji=이모지, style=discord.ButtonStyle.secondary)
            버튼.callback = self._콜백(키)
            self.add_item(버튼)
        self._버튼상태()

    def _버튼상태(self):
        c = 캐릭터(str(self.주인.id))
        for 키, item in zip(능력치, self.children):
            item.disabled = not c or c["points"] <= 0 or c[키] >= 능력치_최대

    async def interaction_check(self, interaction):
        if interaction.user.id != self.주인.id:
            await interaction.response.send_message("자기 캐릭터만 올릴 수 있어요.", ephemeral=True)
            return False
        return True

    def _콜백(self, 키):
        async def 콜백(interaction):
            성공, 결과 = 포인트사용(str(self.주인.id), 키, 1)
            if not 성공:
                await interaction.response.send_message(결과, ephemeral=True)
                return
            self._버튼상태()
            await interaction.response.edit_message(embed=캐릭터카드(결과, self.주인), view=self)
        return 콜백


def 업적보상문구(n):
    d = 업적[n]
    if d.get("보상무기"):
        return f"🎁 {d['보상무기']}"
    return f"+{d['보상']:,}골드"


def 업적알림(이름들):
    return "\n".join(f"🏅 업적 달성: **{n}** ({업적보상문구(n)})" for n in 이름들)


# ============================================================
# 메시지 수정 차례 — 같은 채널의 메시지 수정은 디스코드가 5초에 5번 정도로 막는다(429 → 4초씩 멈춤).
# 자동전투 여러 개가 한 채널에서 돌면 넘치니, 채널마다 수정 차례를 나눠 줘서 한도를 아예 안 넘게 한다.
# ============================================================
수정_간격 = 1.35          # 같은 채널에서 수정과 수정 사이 최소 간격(초). 5초에 4번 이하
메시지_교체분 = 55        # 디스코드는 만든 지 1시간 넘은 메시지의 수정을 훨씬 세게 막는다(429 가 몇 초마다).
                          # 자동전투 화면이 이만큼 오래되면 새 메시지로 옮기고 옛 메시지는 지운다
_수정차례표 = {}          # 채널 id -> 다음 수정이 가능한 시각(monotonic)


async def 수정차례(채널id):
    지금 = _time.monotonic()
    차례 = max(지금, _수정차례표.get(채널id, 0.0))
    _수정차례표[채널id] = 차례 + 수정_간격
    if 차례 > 지금:
        await asyncio.sleep(차례 - 지금)


