def 전투화면(b: 전투, 주인, 보일로그=None):
    c = b._c()
    s = 전투능력(c)
    로그라 = b.비밀 == "로그라이크"
    보스층 = b.층 % 10 == 0
    색 = {"전투": 0xC0392B, "클리어": 0x27AE60, "사망": 0x2C2C2C, "철수": 0x7F8C8D}[b.상태]
    if b.비밀 == "레이드":
        r = b.레이드
        제목 = (f"⚔️ 레이드 · 행동 {min(r['턴'], 레이드_턴제한)}/{레이드_턴제한} · 점수 {r['점수']:,.1f}"
                + (" (연습)" if r["연습"] else ""))
    elif b.비밀 in 특수던전:
        제목 = 특수제목(b)
    elif b.비밀:
        제목 = 비밀공간_제목[b.비밀]
    else:
        제목 = f"{'👑' if 보스층 else '🗼'} 무한 던전 {b.층}층 · {구역이름(b.층)}"
    embed = discord.Embed(
        title=제목,
        description="\n".join((보일로그 if 보일로그 is not None else b.로그)[-8:]) or "…",
        color=색,
    )
    if b.상태 == "전투":
        줄 = []
        for i, e in enumerate(b.살아있는적(), 1):
            꼬리 = []
            if e["방패"]:
                꼬리.append("🛡️")
            if e["조준"]:
                꼬리.append("🎯조준중")
            if e["광폭"]:
                꼬리.append("😡광폭")
            if e.get("튕기기"):
                꼬리.append("🐷튕기기 준비")
            꼬리 += e["패턴"] if not (e["조준"] or e["광폭"]) else []
            꼬리 += [f"{k}{v}" for k, v in e["효과"].items()]
            줄.append(f"`{i}` {e['이름']} {막대(e['hp'], e['최대'], 8)} {e['hp']:,}/{e['최대']:,}"
                      + (f" · {' '.join(꼬리)}" if 꼬리 else ""))
        embed.add_field(name="적", value="\n".join(줄)[:1024] or "없음", inline=False)

    w = 무기[c["weapon"]]
    탄 = ""
    if w["탄약"]:
        q = 보유(b.uid, 'item', w['탄약'][0])
        탄 = f" · {w['탄약'][0]} {'∞' if q >= 관리자_무한 else f'{q:,}'}"
    if c["weapon"] == "화염방사기":
        탄 += f" · 충전 {b.화염충전}/3"
    상태 = [(f"독{b.독중첩}중첩·{v}" if k == "독" else f"{k}{v}") for k, v in b.효과.items()]
    if b.산데["남은"]:
        상태.append(f"⏱️산데비스탄{b.산데['남은']}")
    for k, v in b.쿨.items():
        if v:
            상태.append({"무기": "재장전", "로드롤러": "롤러충전", "과열": "과열"}[k] + str(v))
    embed.add_field(
        name=f"{c['name']}  " + (
            ("⚠️ 체력이 위험하다!" if b.체력 < b.최대체력 * 0.15 else "❓ ▒▒▒/▒▒▒") if b.악세효과["숨김"]
            else f"{막대(b.체력, b.최대체력)} {b.체력}/{b.최대체력}"),
        value=(f"🗡️ 목검 · 강화 {강화문구(b) or '없음'}" if 로그라
               else f"🗡️ {무기표시(b.uid, c['weapon'])}" + (f" +{s['강화']}" if s["강화"] else "") + 탄)
              + (f"\n{' '.join(상태)}" if 상태 else ""),
        inline=False,
    )
    if b.펫:
        p = b.펫
        embed.add_field(
            name=f"{펫[p['이름']]['이모지']} {p.get('별명', p['이름'])}  {막대(p['hp'], p['최대'], 8)} {p['hp']:,}/{p['최대']:,}",
            value="💔 쓰러짐" if p["hp"] <= 0 else (f"🗡️ {p['무기'] or '맨손'} · " + 펫능력문구(p["이름"], p["능력lv"])),
            inline=False,
        )
    누적 = round(getattr(b, "누적골드", 0) + b.획득골드)
    환경 = "" if b.비밀 else f"{구역이름(b.층)}: {구역[구역키(b.층)]['설명']}\n"
    embed.set_footer(text=f"{환경}이번 탐험: 🪙 {누적:,}골드 · 처치 {b.처치수}명 · 보유 골드 {c['gold']:,}")
    return embed


_열린뷰 = {}          # user_id → 가장 최근에 연 전투뷰


async def _외침듣기(message):
    """전투 중인 사람이 아무 채널에나 채팅으로 외친 말 (외침_비밀의 대사)"""
    if message.author.bot or message.guild is None:
        return
    글 = _외침정리(message.content)
    if not 글 or not any(_외침정리(대사) in 글 for _, 대사 in 외침_비밀.values()):
        return
    uid = str(message.author.id)
    b = 진행중.get(uid)
    if b is None or not RPG사용가능(uid):
        return
    try:
        방 = b.외침(message.content)
        if not 방:
            return
    except Exception as e:
        print(f"[{datetime.now()}] RPG 외침 오류 {uid}: {e}")
        return
    try:
        await message.add_reaction(비밀공간[방][0].split()[0])
    except discord.HTTPException:
        pass
    뷰 = _열린뷰.get(uid)
    if 뷰 is not None and 뷰.b is b and 뷰.message is not None and not 뷰.is_finished():
        뷰._구성()
        try:
            await 뷰._화면수정(embed=전투화면(b, 뷰.주인), view=뷰)
        except discord.HTTPException:
            pass


class 전투뷰(discord.ui.View):
    def __init__(self, 주인, 전투객체):
        super().__init__(timeout=전투_제한시간)
        self.주인 = 주인
        self.b = 전투객체
        self.대상 = 0
        self._message = None
        self.재생중 = False
        self.자동 = False
        self._자동작업 = None
        _열린뷰[str(주인.id)] = self          # 채팅 외침(꾸이익)이 이 화면을 고칠 수 있게
        self._구성()

    def _구성(self):
        """버튼을 다시 짠다. custom_id 를 이름으로 고정하고 바로 다시 등록해서, 화면 수정이 아직 안 끝난
        옛 버튼을 눌러도(자동 중엔 매 걸음 다시 짠다) 같은 버튼으로 받는다 — 안 그러면 discord.py 가
        떨어진 옛 버튼이라며 버리고 '애플리케이션이 응답하지 않았어요'가 뜬다"""
        self._구성하기()
        본 = {}
        for item in self.children:
            if not hasattr(item, "custom_id") or getattr(item, "url", None):
                continue
            이름 = "select" if isinstance(item, discord.ui.Select) else (getattr(item, "label", None) or type(item).__name__)
            이름 = f"{이름}|{getattr(item, 'emoji', '') or ''}"[:80]
            본[이름] = 본.get(이름, -1) + 1
            item.custom_id = f"rpg:{이름}:{본[이름]}"
        m, 봇 = getattr(self, "_message", None), _봇.get("bot")
        if m is not None and 봇 is not None and not self.is_finished():
            try:
                봇._connection.store_view(self, m.id)
            except Exception as e:
                print(f"[{datetime.now()}] RPG 버튼 등록 실패: {e}")

    def _구성하기(self):
        self.clear_items()
        b = self.b
        if self.자동 and b.상태 in ("전투", "클리어"):
            정지 = discord.ui.Button(label="자동 정지", emoji="⏹️", style=discord.ButtonStyle.danger, row=0)
            정지.callback = self._자동끄기
            self.add_item(정지)
            return
        if b.상태 in ("전투", "클리어"):
            고르는중 = b.비밀 == "로그라이크" and b.상태 == "클리어" and b.던전["선택지"]
            # 레이드·일일·로그라이크는 잡을 때 골드를 안 주니 자동 효율이 상관없다
            레이드 = b.비밀 == "레이드" or b.비밀 in 특수던전
            자동 = discord.ui.Button(label="자동" if b.비밀 in ("레이드", "일일", "로그라이크") else f"자동 (보상 {int(자동_효율 * 100)}%)",
                                     emoji="🤖", style=discord.ButtonStyle.primary, row=3)
            자동.callback = self._자동켜기
            if not 고르는중:
                self.add_item(자동)
            if not 레이드:
                풀 = discord.ui.Button(label="풀오토 (상인 건너뜀)", emoji="⏩", style=discord.ButtonStyle.primary, row=3)
                풀.callback = self._풀오토켜기
                self.add_item(풀)
        if b.상태 == "전투":
            for 라벨, 이모지, 종류, 스타일 in (
                ("공격", "⚔️", "공격", discord.ButtonStyle.danger),
                ("관찰", "👁️", "관찰", discord.ButtonStyle.secondary),
                ("휴식", "💤", "휴식", discord.ButtonStyle.secondary),
                ("도망", "🏃", "도망", discord.ButtonStyle.secondary),
            ):
                버튼 = discord.ui.Button(label=라벨, emoji=이모지, style=스타일, row=0)
                버튼.callback = self._행동(종류)
                self.add_item(버튼)

            적 = b.살아있는적()
            if len(적) > 1:
                sel = discord.ui.Select(
                    placeholder=f"공격 대상: {적[min(self.대상, len(적) - 1)]['이름']}",
                    options=[discord.SelectOption(label=f"{i + 1}. {e['이름']}"[:100], value=str(i),
                                                  description=f"HP {e['hp']:,}/{e['최대']:,}")
                             for i, e in enumerate(적[:25])],
                    row=1,
                )
                sel.callback = self._대상선택
                self.add_item(sel)

            가진것 = [(n, 보유(b.uid, "item", n)) for n, d in 아이템.items() if d["전투"] and not b.아이템불가(n)]
            가진것 = [(n, q) for n, q in 가진것 if q > 0]
            if 가진것:
                sel = discord.ui.Select(
                    placeholder="🎒 아이템 사용",
                    options=[discord.SelectOption(label=f"{n} ×{'∞' if q >= 관리자_무한 else q}"[:100], value=n,
                                                  description=아이템[n]["설명"][:100]) for n, q in 가진것[:25]],
                    row=2,
                )
                sel.callback = self._아이템
                self.add_item(sel)

        elif b.상태 == "클리어" and b.비밀 == "로그라이크" and b.던전["선택지"]:
            for i, 키 in enumerate(b.던전["선택지"]):
                g = 로그_강화[키]
                버튼 = discord.ui.Button(label=f"{g['이름']} — {g['설명']}"[:80], emoji=g["이모지"],
                                         style=discord.ButtonStyle.success, row=i)
                버튼.callback = self._강화(i)
                self.add_item(버튼)
            철수 = discord.ui.Button(label="여기서 끝내기", emoji="🏳️", style=discord.ButtonStyle.secondary, row=3)
            철수.callback = self._철수
            self.add_item(철수)

        elif b.상태 == "클리어":
            for 이름, 할인 in b.상인:
                가격 = math.ceil(아이템[이름]["price"] * (1 - 할인))
                버튼 = discord.ui.Button(label=f"{이름} {가격}골드 (-{할인 * 100:.0f}%)", emoji="🛒",
                                         style=discord.ButtonStyle.primary, row=0)
                버튼.callback = self._상인구매(이름, 할인)
                self.add_item(버튼)
            회복 = [(n, 보유(b.uid, "item", n)) for n in 회복아이템 if not b.아이템불가(n)]
            회복 = [(n, q) for n, q in 회복 if q > 0]
            if 회복 and b.체력 < b.최대체력:
                sel = discord.ui.Select(
                    placeholder=f"🩹 다음 층 가기 전 회복 (체력 {b.체력}/{b.최대체력})",
                    options=[discord.SelectOption(label=f"{n} ×{'∞' if q >= 관리자_무한 else q}", value=n, description=아이템[n]["설명"][:100]) for n, q in 회복],
                    row=2,
                )
                sel.callback = self._아이템
                self.add_item(sel)
            if b.층 == 50 and not b.비밀:
                창 = discord.ui.Button(label="창밖으로 나간다", emoji="🪟", style=discord.ButtonStyle.secondary, row=2)
                창.callback = self._창밖
                self.add_item(창)
            다음라벨 = {"일일": f"{b.던전['단계'] + 1}/{일일_층수}층으로", "보스러시": "다음 보스"}.get(b.비밀) if b.던전 else None
            다음 = discord.ui.Button(label=다음라벨 or f"{b.층 + 1}층으로", emoji="▶️", style=discord.ButtonStyle.success, row=1)
            다음.callback = self._다음층
            self.add_item(다음)
            철수 = discord.ui.Button(label="철수", emoji="🏳️", style=discord.ButtonStyle.secondary, row=1)
            철수.callback = self._철수
            self.add_item(철수)

    @property
    def message(self):
        return self._message

    @message.setter
    def message(self, m):
        """전투 화면 메시지가 정해지면 위치를 전투에 적어 둔다 (재시작 뒤 이 메시지에 버튼을 다시 단다)"""
        if m is not None and isinstance(m, discord.InteractionMessage):
            # 버튼 응답으로 받은 메시지는 15분 뒤 수정 권한(인터랙션 토큰)이 끝난다. 봇 권한으로 고치게 바꿔 둔다
            try:
                m = m.channel.get_partial_message(m.id)
            except Exception:
                pass
        self._message = m
        if m is not None:
            self.b._화면 = (m.channel.id, m.id)
            전투저장(self.b)

    async def _화면수정(self, **kw):
        """전투 화면을 고친다. 메시지가 오래됐으면(디스코드 수정 제한) 같은 채널에 새로 올리고 옛것은 지운다."""
        m = self.message
        await 수정차례(m.channel.id)
        try:
            나이 = (discord.utils.utcnow() - m.created_at).total_seconds()
        except Exception:
            나이 = 0
        if 나이 < 메시지_교체분 * 60:
            await m.edit(**kw)
            return
        새 = await m.channel.send(content=kw.get("content"), embed=kw.get("embed"), view=kw.get("view"))
        self.message = 새
        try:
            await m.delete()
        except discord.HTTPException:
            pass

    def _자동기록(self):
        self.b.자동복원 = [True, bool(getattr(self, "풀오토", False))] if self.자동 else None
        전투저장(self.b)

    async def interaction_check(self, interaction):
        if interaction.user.id != self.주인.id:
            await interaction.response.send_message("다른 사람의 전투예요.", ephemeral=True)
            return False
        if not RPG사용가능(str(self.주인.id)):
            await interaction.response.send_message(점검문구 + " 전투는 그대로 저장돼 있어요.", ephemeral=True)
            return False
        if self.재생중:
            await interaction.response.send_message("전투 내용이 나오는 중이에요. 잠시만요!", ephemeral=True)
            return False
        return True

    async def _갱신(self, interaction):
        """이번 행동에서 생긴 줄을 한 줄씩 보여준 뒤 버튼을 다시 켠다."""
        b = self.b
        새줄 = list(b.새로그)
        b.새로그 = []
        끝남 = b.상태 in ("사망", "철수")

        def 최종화면():
            embed = 전투화면(b, self.주인)
            if 끝남:
                embed.add_field(
                    name="탐험 결과",
                    value=f"🪙 {getattr(b, '누적골드', 0):,}골드 · ✨ 경험치 {getattr(b, '누적경험치', 0):,} · 🦴 간식 {getattr(b, '누적간식', 0):,} · 처치 {b.처치수}명"
                          + (f"\n🎁 {getattr(b, '보상악세')}" if getattr(b, "보상악세", None) else "")
                          + _레이드결과문구(b) + (f"\n{특수결과문구(b)}" if b.던전 else ""),
                    inline=False,
                )
            return embed

        # 한 번에 보여줄 줄이 한두 줄이면 그냥 바로 보여준다
        if len(새줄) <= 1:
            self._구성()
            await interaction.response.edit_message(embed=최종화면(), view=None if 끝남 else self)
        else:
            self.재생중 = True
            for item in self.children:
                item.disabled = True
            이전 = b.로그[: max(0, len(b.로그) - len(새줄))]
            # 디스코드 수정 제한을 넘지 않게 최대 6단계로 나눈다
            단계 = max(1, math.ceil(len(새줄) / 6))
            try:
                for i in range(단계, len(새줄) + 단계, 단계):
                    embed = 전투화면(b, self.주인, 보일로그=이전 + 새줄[:i])
                    if i == 단계:
                        await interaction.response.edit_message(embed=embed, view=self)
                    else:
                        await asyncio.sleep(0.45)
                        await interaction.edit_original_response(embed=embed, view=self)
                await asyncio.sleep(0.3)
            finally:
                self._구성()                       # 중간에 수정이 실패해도 버튼은 다시 켜 둔다 (`!RPG 던전`으로 다시 띄울 수 있게)
                self.재생중 = False
            await interaction.edit_original_response(embed=최종화면(), view=None if 끝남 else self)

        if 끝남:
            self.stop()

        # 업적은 따로 채널에 알린다
        if b.새업적:
            try:
                await interaction.channel.send(f"{self.주인.mention}\n" + 업적알림(b.새업적))
            except discord.HTTPException:
                pass
            b.새업적 = []

    def _행동(self, 종류):
        async def 콜백(interaction):
            self.b.행동(종류, 대상=self.대상)
            self.대상 = 0 if self.대상 >= len(self.b.살아있는적()) else self.대상
            await self._갱신(interaction)
        return 콜백

    async def _대상선택(self, interaction):
        self.대상 = int(interaction.data["values"][0])
        await self._갱신(interaction)

    async def _아이템(self, interaction):
        self.b.행동("아이템", 아이템이름=interaction.data["values"][0])
        await self._갱신(interaction)

    def _상인구매(self, 이름, 할인):
        async def 콜백(interaction):
            성공, r = 구매(str(self.주인.id), 이름, 1, 할인=할인)
            self.b.기록(f"🛒 {이름} 구매 ({r['가격']}골드)" if 성공 else f"🛒 {r}")
            await self._갱신(interaction)
        return 콜백

    async def _다음층(self, interaction):
        self.b.다음층()
        await self._갱신(interaction)

    def _강화(self, 번호):
        async def 콜백(interaction):
            self.b.강화선택(번호)
            if getattr(self, "강화후자동", False) and self.b.상태 == "전투":
                self.강화후자동 = False                 # 자동으로 돌다가 강화 때문에 멈춘 거면 이어서 돈다
                await self._자동켜기(interaction, 문구="🤖 자동 계속", 풀오토유지=True)
                return
            await self._갱신(interaction)
        return 콜백

    async def _창밖(self, interaction):
        self.b.창밖()
        await self._갱신(interaction)

    async def _철수(self, interaction):
        self.b.철수()
        self.b.기록("🏳️ 던전에서 나왔다")
        await self._갱신(interaction)

    # ---------- 자동 모드 ----------
    async def _풀오토켜기(self, interaction):
        self.풀오토 = True
        await self._자동켜기(interaction, 문구="⏩ 풀오토 시작 — 상인도 건너뛰고 계속 올라가요")

    async def _자동켜기(self, interaction, 문구=None, 풀오토유지=False):
        if 문구 is None and not 풀오토유지:
            self.풀오토 = False
        self.자동 = True
        self.강화후자동 = False
        효율문구 = f" · 자동으로 잡은 적은 골드·경험치 {int(자동_효율 * 100)}%" if self.b.비밀 in (None, "보스러시") else ""
        self.b.기록((문구 or "🤖 자동 모드 시작") + 효율문구)
        self._구성()
        await interaction.response.edit_message(embed=전투화면(self.b, self.주인), view=self)
        if self.message is None:
            self.message = await interaction.original_response()
        self._자동기록()
        self._자동작업 = asyncio.create_task(self._자동루프())

    async def _자동끄기(self, interaction):
        self.자동 = False
        self.강화후자동 = False
        self._자동기록()
        self.b.기록("🤖 자동 모드 정지")
        self._구성()
        await interaction.response.edit_message(embed=전투화면(self.b, self.주인), view=self)

    async def _자동루프(self):
        b = self.b
        try:
            while self.자동 and not self.is_finished():
                if not RPG사용가능(str(self.주인.id)):
                    self.자동 = False
                    b.기록("🔧 RPG 점검이 시작돼 자동 모드를 멈췄다")
                    self._구성()
                    await self._화면수정(embed=전투화면(b, self.주인), view=self)
                    break
                결과 = b.자동행동(풀오토=getattr(self, "풀오토", False))
                b.새로그 = []
                if 결과.startswith("정지:"):
                    self.자동 = False
                    if b.비밀 == "로그라이크" and b.상태 == "클리어" and b.던전["선택지"]:
                        self.강화후자동 = True          # 강화를 고르면 자동이 이어진다
                    else:
                        b.기록(f"🤖 자동 정지 — {결과[3:]}")
                끝남 = b.상태 in ("사망", "철수") or 결과 == "끝"
                if 끝남:
                    self.자동 = False
                self._구성()
                embed = 전투화면(b, self.주인)
                if 끝남:
                    embed.add_field(
                        name="탐험 결과",
                        value=f"🪙 {getattr(b, '누적골드', 0):,}골드 · ✨ 경험치 {getattr(b, '누적경험치', 0):,} · 🦴 간식 {getattr(b, '누적간식', 0):,} · 처치 {b.처치수}명"
                          + (f"\n🎁 {getattr(b, '보상악세')}" if getattr(b, "보상악세", None) else "")
                          + _레이드결과문구(b) + (f"\n{특수결과문구(b)}" if b.던전 else ""),
                        inline=False,
                    )
                await self._화면수정(embed=embed, view=None if 끝남 else self)
                if b.새업적:
                    await self.message.channel.send(f"{self.주인.mention}\n" + 업적알림(b.새업적))
                    b.새업적 = []
                if 끝남:
                    self.stop()
                    break
                getattr(self, "_refresh_timeout", lambda: None)()   # 자동으로 도는 동안엔 시간 제한이 흐르지 않게
                self.b.마지막 = datetime.now()
                await asyncio.sleep(1.3)          # 디스코드 수정 제한을 넘지 않게
        except discord.HTTPException:
            self.자동 = False
        finally:
            if not self.자동 and getattr(self.b, "자동복원", None):
                self._자동기록()

    async def on_timeout(self):
        self.자동 = False
        self.b.철수()
        if self.message:
            try:
                await self._화면수정(content="⏰ 오래 움직이지 않아 던전에서 나왔습니다.", view=None)
            except discord.HTTPException:
                pass


# ============================================================
# 디스코드 화면 — 친선전
# ============================================================

def 친선전화면(d):
    """DB 의 대결 하나를 (내용, 임베드) 로 그린다"""
    상태 = d["status"]
    if 상태 in ("pending", "declined", "canceled", "expired"):
        a, b = 캐릭터(d["a"]), 캐릭터(d["b"])
        문구 = {
            "pending": f"**{a['name']}**님이 **{b['name']}**님에게 친선전을 신청했어요!\n"
                       f"전투력 **{친선전능력(d['a'])['전투력']:,}** vs **{친선전능력(d['b'])['전투력']:,}** · 차이만큼 보정해서 비슷하게 맞춰요\n"
                       f"골드·아이템은 쓰지도 걸지도 않아요. {친선전_신청유효초 // 60}분 안에 수락해주세요.",
            "declined": f"{b['name']}님이 친선전을 거절했어요.",
            "canceled": f"{a['name']}님이 신청을 취소했어요.",
            "expired": "⏰ 시간 안에 답이 없어 친선전 신청이 취소됐어요.",
        }[상태]
        return discord.Embed(title="🤝 친선전 신청", description=문구 + f"\n웹에서도 할 수 있어요: {웹_RPG_주소}",
                             color=0xE67E22 if 상태 == "pending" else 0x7F8C8D)
    g = d["game"]
    a, b = g.p
    embed = discord.Embed(title=f"🤝 친선전 — {a['이름']} vs {b['이름']}", description="\n".join(g.로그[-8:]),
                          color=0x7F8C8D if g.끝 else 0xE67E22)
    for x in g.p:
        보정 = (x["보정"] - 1) * 100
        embed.add_field(
            name=f"{'▶ ' if not g.끝 and g.지금()['uid'] == x['uid'] else ''}{x['이름']}  {막대(x['hp'], x['최대'], 8)} {x['hp']:,}/{x['최대']:,}",
            value=(f"🗡️ {x['무기']}" + (f" +{x['강화']}" if x["강화"] else "")
                   + (f" · {악세서리[x['악세']]['이모지']}" if x["악세"] else "")
                   + f"\n전투력 {x['전투력']:,} · {'체력' if 친선전_모드 == '체력' else '공격·체력'} **{보정:+.0f}%**"),
            inline=True,
        )
    if g.끝:
        embed.set_footer(text="무승부" if g.승자 is None else f"🏆 {g.승자['이름']} 승리 · 친선전은 골드·아이템을 쓰지도 주지도 않아요")
    else:
        embed.set_footer(text=f"{g.지금()['이름']}의 차례 · {g.턴 + 1}/{친선전_최대턴}턴 · {친선전_턴제한초}초 안에 행동하지 않으면 기권 · 웹에서도 가능")
    return embed


def 친선전뷰만들기(d):
    if d["status"] == "pending":
        return 친선전초대(d["id"])
    if d["status"] == "active":
        return 친선전뷰(d["id"])
    return None


class 친선전뷰(discord.ui.View):
    def __init__(self, duel_id):
        super().__init__(timeout=None)          # 시간 제한은 DB 기준으로 동기화 루프가 처리한다
        self.duel_id = duel_id
        for 라벨, 이모지, 종류, 스타일 in (
            ("공격", "⚔️", "공격", discord.ButtonStyle.danger),
            ("관찰", "👁️", "관찰", discord.ButtonStyle.secondary),
            ("휴식", "💤", "휴식", discord.ButtonStyle.secondary),
            ("항복", "🏳️", "항복", discord.ButtonStyle.secondary),
        ):
            버튼 = discord.ui.Button(label=라벨, emoji=이모지, style=스타일)
            버튼.callback = self._행동(종류)
            self.add_item(버튼)

    async def interaction_check(self, interaction):
        d = 친선전찾기(self.duel_id)
        uid = str(interaction.user.id)
        if d is None or d["status"] != "active":
            await interaction.response.edit_message(embed=친선전화면(d), view=None) if d else None
            return False
        if uid not in (d["a"], d["b"]):
            await interaction.response.send_message("구경만 할 수 있어요 👀", ephemeral=True)
            return False
        if d["game"].지금()["uid"] != uid:
            await interaction.response.send_message(f"지금은 {d['game'].지금()['이름']}의 차례예요.", ephemeral=True)
            return False
        return True

    def _행동(self, 종류):
        async def 콜백(interaction):
            성공, r = 친선전행동(self.duel_id, str(interaction.user.id), 종류)
            if not 성공:
                await interaction.response.send_message(r, ephemeral=True)
                return
            d = 친선전찾기(self.duel_id)
            await interaction.response.edit_message(embed=친선전화면(d), view=친선전뷰만들기(d))
        return 콜백


class 친선전초대(discord.ui.View):
    def __init__(self, duel_id):
        super().__init__(timeout=None)
        self.duel_id = duel_id

    async def interaction_check(self, interaction):
        d = 친선전찾기(self.duel_id)
        if d is None or d["status"] != "pending":
            await interaction.response.edit_message(embed=친선전화면(d), view=친선전뷰만들기(d)) if d else None
            return False
        if str(interaction.user.id) != d["b"]:
            await interaction.response.send_message("신청받은 사람만 고를 수 있어요.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="수락", emoji="🤝", style=discord.ButtonStyle.success)
    async def 수락(self, interaction, button):
        성공, r = 친선전수락(self.duel_id, str(interaction.user.id))
        if not 성공:
            await interaction.response.send_message(r, ephemeral=True)
            return
        d = 친선전찾기(self.duel_id)
        await interaction.response.edit_message(embed=친선전화면(d), view=친선전뷰만들기(d))

    @discord.ui.button(label="거절", emoji="✋", style=discord.ButtonStyle.secondary)
    async def 거절(self, interaction, button):
        친선전거절(self.duel_id, str(interaction.user.id))
        d = 친선전찾기(self.duel_id)
        await interaction.response.edit_message(embed=친선전화면(d), view=None)


# ---------- 동기화 루프: DM 알림 + 웹에서 한 행동을 디코 메시지에 반영 ----------

_봇 = {"bot": None}


async def _친선전동기화():
    봇 = _봇["bot"]
    기준 = (datetime.now() - timedelta(hours=1)).isoformat()
    cursor.execute(
        "SELECT id FROM rpg_duels WHERE status IN ('pending', 'active') "
        "OR (updated > ? AND (rendered IS NULL OR rendered < updated))", (기준,))
    for (i,) in cursor.fetchall():
        d = 친선전찾기(i)
        if d is None:
            continue
        # 1) 신청 알림 DM
        if d["status"] == "pending" and not d["notified"]:
            cursor.execute("UPDATE rpg_duels SET notified = 1 WHERE id = ?", (i,))
            conn.commit()
            try:
                받는사람 = 봇.get_user(int(d["b"])) or await 봇.fetch_user(int(d["b"]))
                m = await 받는사람.send(content=f"⚔️ **{캐릭터(d['a'])['name']}**님이 친선전을 신청했어요!",
                                       embed=친선전화면(d), view=친선전초대(i))
                친선전메시지추가(i, m.channel.id, m.id)
                d = 친선전찾기(i)
            except discord.HTTPException as e:
                print(f"[{datetime.now()}] 친선전 DM 실패 ({d['b']}): {e}")
        # 2) 바뀐 게 있으면 모든 메시지를 새로 그린다
        if d["rendered"] != d["updated"]:
            for 채널, 메시지 in d["msgs"]:
                try:
                    msg = 봇.get_partial_messageable(int(채널)).get_partial_message(int(메시지))
                    await 수정차례(int(채널))
                    await msg.edit(embed=친선전화면(d), view=친선전뷰만들기(d))
                except discord.HTTPException:
                    pass
            cursor.execute("UPDATE rpg_duels SET rendered = ? WHERE id = ?", (d["updated"], i))
            conn.commit()


def 시작(bot):
    """on_ready 에서 한 번 부른다 (안 불러도 !RPG 를 처음 쓸 때 시작된다)"""
    _봇["bot"] = bot
    if not _봇.get("외침"):
        _봇["외침"] = True
        bot.add_listener(_외침듣기, "on_message")
    if not _친선전루프.is_running():
        _친선전루프.start()
    if not _봇.get("복원함"):
        _봇["복원함"] = True
        asyncio.create_task(_전투화면복원(bot))


async def _전투화면복원(bot):
    """재시작 전 전투를 되살리고, 그 전투 메시지에 버튼을 다시 단다. 자동이었으면 자동도 다시 켠다."""
    try:
        살린것 = 전투복원()
    except Exception as e:
        print(f"[{datetime.now()}] RPG 전투 복원 오류: {e}")
        return
    for b in 살린것:
        try:
            주인 = bot.get_user(int(b.uid)) or await bot.fetch_user(int(b.uid))
            위치 = getattr(b, "_화면", None)
            메시지 = None
            if 위치:
                채널 = bot.get_channel(위치[0]) or await bot.fetch_channel(위치[0])
                메시지 = await 채널.fetch_message(위치[1])
            if 메시지 is None:
                raise LookupError("전투 메시지 위치를 모름")
            뷰 = 전투뷰(주인, b)
            자동 = getattr(b, "자동복원", None)
            if 자동:
                뷰.자동, 뷰.풀오토 = True, bool(자동[1])
                뷰._구성()
            뷰.message = 메시지
            await 뷰._화면수정(embed=전투화면(b, 주인), view=뷰)
            if 자동:
                뷰._자동작업 = asyncio.create_task(뷰._자동루프())
        except Exception as e:
            # 메시지를 못 찾으면 이어 갈 화면이 없다. 모은 보상만 주고 끝낸다
            print(f"[{datetime.now()}] RPG 전투 화면 복원 실패 {b.uid}: {e} — 정산만 함")
            if 진행중.get(b.uid) is b:
                b.철수()


from discord.ext import tasks as _tasks  # noqa: E402


@_tasks.loop(seconds=2)
async def _친선전루프():
    try:
        await _친선전동기화()
    except Exception as e:
        print(f"[{datetime.now()}] 친선전 동기화 오류: {e}")


class 층선택(discord.ui.View):
    def __init__(self, 주인, 최고):
        super().__init__(timeout=60)
        self.주인 = 주인
        층들 = list(range(최고, 0, -10))[:25]                  # 최근 체크포인트부터 (선택지는 최대 25개)
        if 1 not in 층들:
            층들[-1] = 1
        sel = discord.ui.Select(
            placeholder="시작할 층을 고르세요",
            options=[discord.SelectOption(label=f"{f}층부터", value=str(f),
                                          description="최근 체크포인트" if f == 최고 else None,
                                          emoji="👑" if f == 최고 else "🗼") for f in 층들],
        )
        sel.callback = self._고름
        self.add_item(sel)

    async def interaction_check(self, interaction):
        if interaction.user.id != self.주인.id:
            await interaction.response.send_message("명령어를 쓴 사람만 고를 수 있어요.", ephemeral=True)
            return False
        return True

    async def _고름(self, interaction):
        uid = str(self.주인.id)
        층 = int(interaction.data["values"][0])
        if 전투중(uid) or 친선전진행중(uid):
            await interaction.response.edit_message(content="이미 전투 중이에요. 진행 중인 전투를 마치고 오세요.", view=None)
            return
        if 층 > 시작층(uid) or 층 % 10 != 1:
            await interaction.response.edit_message(content="그 층에서는 시작할 수 없어요.", view=None)
            return
        self.stop()
        b = 전투(uid, 층)
        진행중[uid] = b
        뷰 = 전투뷰(self.주인, b)
        await interaction.response.edit_message(content=None, embed=전투화면(b, self.주인), view=뷰)
        뷰.message = await interaction.original_response()


class 비밀공간선택(discord.ui.View):
    def __init__(self, 주인):
        super().__init__(timeout=120)
        self.주인 = 주인
        for 방 in 비밀공간_바로가기:
            제목 = 비밀공간_제목.get(방, 방)
            버튼 = discord.ui.Button(label=제목, style=discord.ButtonStyle.secondary)
            버튼.callback = self._입장(방)
            self.add_item(버튼)

    async def interaction_check(self, interaction):
        if interaction.user.id != self.주인.id:
            await interaction.response.send_message("명령어를 쓴 관리자만 누를 수 있어요.", ephemeral=True)
            return False
        return True

    def _입장(self, 방):
        async def 콜백(interaction):
            성공, b = 비밀공간바로입장(str(self.주인.id), 방)
            if not 성공:
                await interaction.response.send_message(b, ephemeral=True)
                return
            self.stop()
            if b.상태 in ("사망", "철수"):           # 재단은 바로 끝난다
                embed = 전투화면(b, self.주인)
                await interaction.response.edit_message(content=None, embed=embed, view=None)
                return
            뷰 = 전투뷰(self.주인, b)
            await interaction.response.edit_message(content=None, embed=전투화면(b, self.주인), view=뷰)
            뷰.message = await interaction.original_response()
        return 콜백


def _레이드결과문구(b):
    if not hasattr(b, "레이드점수"):
        return ""
    return f"\n⚔️ 레이드 점수 {b.레이드점수:,.1f}" + (" (연습 — 기록 안 됨)" if b.레이드["연습"] else "")


def _남은시간문구(끝):
    초 = max(0, int((끝 - datetime.now()).total_seconds()))
    일, 초 = divmod(초, 86400)
    시, 초 = divmod(초, 3600)
    return (f"{일}일 " if 일 else "") + f"{시}시간 {초 // 60}분"


def 레이드화면(user_id):
    s = 레이드상태(user_id)
    비율 = s["hp"] / s["max"] if s["max"] else 0
    embed = discord.Embed(title=f"⚔️ 주간 레이드 — {s['boss']}", description=s["desc"],
                          color=0x2C2C2C if s["killed"] else 0x8E44AD)
    embed.add_field(
        name="공유 체력",
        value=(f"{막대(s['hp'], s['max'], 14)} **{비율 * 100:.1f}%**\n"
               + (f"🏆 **{s['killer']}**님의 마지막 일격으로 쓰러졌다! 월요일 0시에 새 보스가 나와요."
                  if s["killed"] else f"⏳ 남은 시간 {_남은시간문구(s['ends'])} · 참가 {s['people']}명")),
        inline=False,
    )
    embed.add_field(
        name="규칙",
        value=(f"하루 {s['maxTries']}번 · 한 번에 행동 {s['turns']}번 · 공격 {s['type']} · 패턴 {', '.join(s['patterns'])}\n"
               "보스 세기는 **내 최고층** 기준이라 누구나 같이 깎을 수 있어요.\n"
               "보상(골드)은 보스가 쓰러지면 바로, 못 잡으면 주가 끝날 때 줄어든 채로 나가요. 피해 1등은 🎖️ 정복자의 훈장."),
        inline=False,
    )
    메달 = {1: "🥇", 2: "🥈", 3: "🥉"}
    줄 = [f"{메달.get(i, f'`{i}`')} **{n}** — {dmg:,.1f}점" + (f" · 🪙{rw:,}" if rw is not None else "")
          for i, n, dmg, rw in s["rank"]]
    embed.add_field(name="피해 순위", value="\n".join(줄)[:1024] or "아직 아무도 도전하지 않았어요", inline=False)
    if s["practice"]:
        내 = "👑 관리자는 연습 모드예요 (도전 횟수 무제한 · 기록 안 됨)"
    else:
        내 = (f"{s['mine'][0]}위 · {s['mine'][1]:,.1f}점" if s["mine"] else "기록 없음") + f" · 오늘 도전 {s['tries']}/{s['maxTries']}"
    embed.add_field(name="내 기록", value=내, inline=False)
    if s["last"]:
        l = s["last"]
        top = " · ".join(f"{n} {dmg:,.0f}점" for n, dmg, _ in l["top"]) or "참가자 없음"
        mine = f"\n내 보상: 🪙 {l['mine'][1]:,}골드" if l["mine"] and l["mine"][1] is not None else ""
        embed.add_field(name=f"지난 주 — {l['boss']} {'처치 ✅' if l['killed'] else '실패 ❌'}", value=(top + mine)[:1024], inline=False)
    return embed, s


