    embed = discord.Embed(title=s["title"], description=s["desc"], color={"일일": 0x2980B9, "로그라이크": 0x16A085, "보스러시": 0xD35400}[모드])
    if 모드 == "일일":
        embed.add_field(name="오늘의 규칙", value=f"**{s['rule']['name']}** — {s['rule']['desc']}\n마지막 층 보스: {s['boss']}", inline=False)
