def 상점화면(user_id, 분류):
    c = 캐릭터(user_id)
    embed = discord.Embed(title=f"🏪 상점 — {분류}", color=0xF2C230)
    줄 = []
    if 분류 in ("무기", "갑옷"):
        표, 종류 = (무기, "weapon") if 분류 == "무기" else (갑옷, "armor")
        for n, d in 표.items():
            if d.get("숨김") and not 보유(user_id, 종류, n):
                continue
            됨, 이유 = 해금여부(user_id, 종류, n)
            if n == (c["weapon"] if 종류 == "weapon" else c["armor"]):
                상태 = "🟣 **장착 중**"
            elif 보유(user_id, 종류, n):
                상태 = f"✅ 보유 · `!RPG 장착 {n}`"
            elif not 됨:
                상태 = f"🔒 {이유}"
            else:
                상태 = "무료" if d["price"] == 0 else f"{d['price']:,}골드"
            수치 = f"공격 {d['atk']}" if 종류 == "weapon" else f"방어 {d['dfn']}"
            if 종류 == "weapon" and d["탄약"]:
                수치 += f" · {d['탄약'][0]} {d['탄약'][1]}"
            if 종류 == "armor":
                if d["pen"]:
                    수치 += f" · 회피 -{d['pen'] * 100:.0f}%"
                if d["저항"]:
                    수치 += " · " + " ".join(f"{k}-{v * 100:.0f}%" for k, v in d["저항"].items())
            줄.append(f"**{n}** — {상태}\n└ {수치}" + (f" · {d['설명']}" if 종류 == "weapon" else ""))
    else:
        for n, d in 아이템.items():
            q = 보유(user_id, 'item', n)
            줄.append(f"**{n}** — {d['price']:,}골드 (보유 {'∞' if q >= 관리자_무한 else q})\n└ {d['설명']}")
    embed.description = "\n".join(줄)[:4000]
    embed.set_footer(text=f"보유 골드 {c['gold']:,} · !RPG 구매 [이름] [수량] · !RPG 판매 [이름] [수량]")
    return embed


def 가방화면(user_id, 주인):
    c = 캐릭터(user_id)
    cursor.execute(
        "SELECT kind, name, qty, enhance FROM rpg_inventory WHERE user_id = ? AND qty > 0 ORDER BY kind, name",
        (user_id,),
    )
    무기줄, 갑옷줄, 아이템줄 = [], [], []
    for 종류, n, q, 강 in cursor.fetchall():
        if 종류 == "weapon":
            무기줄.append(f"{무기표시(user_id, n)}" + (f" +{강}" if 강 else "") + (" · **장착 중**" if n == c["weapon"] else ""))
        elif 종류 == "armor":
            갑옷줄.append(f"{n}" + (" · **장착 중**" if n == c["armor"] else ""))
        else:
            아이템줄.append(f"{n} ×{q:,}")
    if 관리자인가(user_id):
        아이템줄 = ["👑 모든 아이템 ∞"]
    embed = discord.Embed(title=f"🎒 {c['name']}의 가방", color=0x8E5CF6)
    embed.add_field(name="🗡️ 무기", value="\n".join(무기줄) or "없음", inline=True)
    embed.add_field(name="🛡️ 갑옷", value="\n".join(갑옷줄) or "없음", inline=True)
    embed.add_field(name="🧪 아이템", value="\n".join(아이템줄)[:1024] or "없음", inline=False)
    embed.set_footer(text=f"🪙 {c['gold']:,}골드 · !RPG 장착 [이름]")
    return embed


def 펫화면(user_id):
    embed = discord.Embed(title="🐾 펫", color=0xF39C12)
    가진 = {p["이름"]: p for p in 내펫들(user_id)}
    for n, d in 펫.items():
        p = 가진.get(n)
        if d.get("숨김") and not p:
            continue
        if p and n == "스탠드":
            st = 내스탠드(user_id) or {"능력들": []}
            embed.add_field(name=f"{d['이모지']} {p['별명']} (스탠드) · Lv.{p['능력lv']}" + (" · **장착 중**" if p["장착"] else ""),
                            value=("\n".join(f"「{a['이름']}」 {a.get('설명', '')}" for a in st["능력들"]) or "능력 없음")[:1000]
                            + "\n`!RPG 스탠드` 로 자세히", inline=False)
            continue
        if p:
            제목 = f"{d['이모지']} {p['별명']}" + (f" ({n})" if p["별명"] != n else "") + (" · **장착 중**" if p["장착"] else "")
            내용 = (f"체력 Lv.{p['체력lv']} ({펫최대체력(n, p['체력lv']):,}) · 능력 Lv.{p['능력lv']}\n"
                    f"{펫능력문구(n, p['능력lv'])}")
        else:
            제목 = f"{d['이모지']} {n} — {d['price']:,}골드"
            내용 = d["설명"]
        embed.add_field(name=제목, value=내용, inline=False)
    embed.add_field(name="🗡️ 펫 무기", value=f"{펫무기(user_id) or '맨손'} · `!RPG 펫 무기 [무기]` 로 변경", inline=False)
    q = 간식(user_id)
    embed.set_footer(text=f"🦴 간식 {'∞' if q >= 관리자_무한 else f'{q:,}'} · 레벨업 비용 = 10 × 다음 레벨")
    return embed


def 스탠드화면(user_id):
    st = 내스탠드(user_id)
    대기 = 스탠드요청목록(user_id)
    embed = discord.Embed(title="👤 스탠드", color=0x9B59B6)
    if st:
        embed.title = f"👤 {st['이름']} · Lv.{st['레벨']}"
        다음 = f"{st['경험']:,} / {st['다음']:,}" if st["다음"] else "최대 레벨"
        칸 = 스탠드능력칸(st["레벨"])
        embed.description = (f"경험치 {다음} · 능력 {len(st['능력들'])}/{칸}칸 "
                             f"(Lv.{스탠드_능력간격}마다 1칸, 최대 {스탠드능력칸(스탠드_최대레벨)}칸) · 능력 배율 ×{스탠드_레벨배율(st['레벨']):.2f}\n"
                             "간식을 먹지 않아요. 펫으로 데리고 싸우면 전투 경험치로 자라요.")
        for a in st["능력들"]:
            embed.add_field(name=f"「{a['이름']}」", value=(a.get("설명") or "-")[:1024], inline=False)
    else:
        q = 스탠드디스크수(user_id)
        embed.description = (f"💿 {스탠드디스크} {q}장\n" + ("`!RPG 스탠드 만들기 [이름] | [능력 설명]` 으로 만들어요."
                             if q else f"💡 {스탠드디스크_힌트}"))
    if 대기:
        embed.add_field(name="⏳ 만드는 중",
                        value="\n".join(f"#{r['id']} {r['종류']} — {r['내용'][:80]}" for r in 대기)[:1024], inline=False)
    embed.set_footer(text="요청은 관리자가 확인해서 밸런스에 맞게 만들어 줘요 · !RPG 스탠드 능력 [설명] · !RPG 펫 장착 스탠드")
    return embed


def 업적화면(user_id, 주인):
    업적확인(user_id)
    달성 = sum(1 for n in 업적 if 업적보유(user_id, n))
    embed = discord.Embed(title=f"🏅 업적 {달성}/{len(업적)}", color=0xE67E22)
    진행 = 업적진행(user_id)
    줄 = []
    for n, d in 업적.items():
        달성함 = 업적보유(user_id, n)
        줄.append(f"{'✅' if 달성함 else '⬜'} **{n}** — {d['설명']} ({업적보상문구(n)})")
        if not 달성함 and n in 진행:
            줄.append("└ " + " · ".join(
                f"{라벨} {min(현재, 목표):,}/{목표:,}" + (" ✓" if 현재 >= 목표 else "")
                for 라벨, 현재, 목표 in 진행[n]))
    embed.description = "\n".join(줄)[:4000]
    return embed


